EstimatePayload = Tuple[Dict[str, float], Dict[str, Any], Dict[str, Any]]


class _SharedPlanEstimateFutureCache:
    """Thread-safe exact-parameter cache that coalesces concurrent estimates."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._futures: Dict[Tuple[Tuple[str, str], ...], Future[EstimatePayload]] = {}
        self._request_count = 0
        self._cache_hit_count = 0
        self._inflight_hit_count = 0
        self._failed_unique_count = 0

    @staticmethod
    def _signature(params: Mapping[str, Any]) -> Tuple[Tuple[str, str], ...]:
        signature: List[Tuple[str, str]] = []
        for raw_name in sorted(params):
            name = str(raw_name)
            try:
                value = float(params[raw_name])
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    f" {name!r} : {params[raw_name]!r}"
                ) from exc
            if not math.isfinite(value):
                raise ValueError(f" {name!r} : {value!r}")
            signature.append((name, value.hex()))
        return tuple(signature)

    def get_or_compute(
        self,
        params: Mapping[str, Any],
        compute: Callable[[], EstimatePayload],
    ) -> Tuple[EstimatePayload, Dict[str, Any]]:
        """Return one exact estimate, sharing the same Future across callers."""
        signature = self._signature(params)
        owner = False
        inflight_hit = False
        with self._lock:
            self._request_count += 1
            future = self._futures.get(signature)
            if future is None:
                future = Future()
                self._futures[signature] = future
                owner = True
            else:
                self._cache_hit_count += 1
                if not future.done():
                    self._inflight_hit_count += 1
                    inflight_hit = True

        if owner:
            try:
                payload = compute()
            except BaseException as exc:
                with self._lock:
                    self._failed_unique_count += 1
                future.set_exception(exc)
            else:
                future.set_result(copy.deepcopy(payload))

        payload = copy.deepcopy(future.result())
        return payload, {
            "cache_hit": not owner,
            "shared_inflight_future": inflight_hit,
            "parameter_signature": [list(item) for item in signature],
        }

    def stats(self) -> Dict[str, int]:
        with self._lock:
            return {
                "request_count": self._request_count,
                "unique_parameter_count": len(self._futures),
                "cache_hit_count": self._cache_hit_count,
                "inflight_hit_count": self._inflight_hit_count,
                "failed_unique_count": self._failed_unique_count,
            }


def _gradient_replay_stage_action(
    *,
    validated_count: int,
    eligible_count: int,
    available_count: int,
    initial_top_k: int = 5,
    max_top_k: int = 10,
) -> str:
    """Return the frozen staged-replay action after the current validation."""
    if validated_count < 0 or eligible_count < 0 or available_count < 0:
        raise ValueError("replay counts cannot be negative")
    if eligible_count > validated_count:
        raise ValueError("eligible_count cannot exceed validated_count")
    if initial_top_k <= 0 or max_top_k < initial_top_k:
        raise ValueError("invalid staged replay top-k")
    if validated_count < min(initial_top_k, available_count):
        return "continue_initial"
    if eligible_count > 0:
        return "accept_current_batch"
    if validated_count < min(max_top_k, available_count):
        return "expand_second_batch"
    return "reject_exploration"


def _gradient_advance_accepted_shrink_count(
    accepted_shrink_count: int,
    *,
    accepted: bool,
) -> int:
    """Advance the outer progress counter only for an accepted real batch."""
    if accepted_shrink_count < 0:
        raise ValueError("accepted_shrink_count cannot be negative")
    return accepted_shrink_count + (1 if accepted else 0)


def _online_update_experience_table_and_rerank(
    sensitivity_table: Dict[str, Dict[str, float]],
    *,
    baseline_params: Mapping[str, Any],
    baseline_validation: Mapping[str, Any],
    evaluations: Sequence[Mapping[str, Any]],
    remaining_candidates: Sequence[Any],
    low_confidence_freeze_threshold: float = 0.50,
    target_resource: str = "memory",
) -> Tuple[Dict[str, Dict[str, float]], List[Any], Dict[str, Any]]:
    """Update T from the first live batch and rerank only the unseen suffix.

    This intentionally keeps the all-subset candidate framework.  The online
    delta is a conservative correlation update: low-confidence rows are
    frozen, while supported rows blend their prior with observed CPU/memory/
    IO/QPS directions.  It is used for ordering, never as outer acceptance.
    """
    updated = copy.deepcopy(sensitivity_table)
    target_resource = str(target_resource).strip().lower()
    if target_resource not in {"cpu", "memory", "io"}:
        raise ValueError(f"unsupported online T target_resource: {target_resource}")
    baseline_util = dict(baseline_validation.get("utilization_pct") or {})
    baseline_qps = _to_float_or_none(
        baseline_validation.get("formal_qps")
        or baseline_validation.get("db_qps")
        or baseline_validation.get("qps")
    )
    if baseline_qps is None or baseline_qps <= 0.0:
        raise RuntimeError("online T update requires positive finite baseline formal_qps")

    samples: List[Dict[str, Any]] = []
    for evaluation in evaluations:
        params = evaluation.get("candidate_optimized_params") or {}
        validation = evaluation.get("candidate_final_validation") or {}
        utilization = validation.get("utilization_pct") or {}
        formal_qps = _to_float_or_none(
            validation.get("formal_qps")
            or validation.get("db_qps")
            or validation.get("qps")
        )
        if not isinstance(params, Mapping) or formal_qps is None:
            continue
        outcomes = {
            name: float(utilization[name]) - float(baseline_util[name])
            for name in ("cpu", "memory", "io")
            if name in utilization and name in baseline_util
        }
        if len(outcomes) != 3:
            continue
        outcomes["qps"] = float(formal_qps) / float(baseline_qps) - 1.0
        samples.append({"params": dict(params), "outcomes": outcomes})

    rows: List[Dict[str, Any]] = []
    for param_name, effects in updated.items():
        prior_confidence = float(effects.get("confidence", 1.0) or 0.0)
        prior_evidence = max(0.0, float(effects.get("evidence_count", 0.0) or 0.0))
        xs: List[float] = []
        ys: Dict[str, List[float]] = {name: [] for name in ("cpu", "memory", "io", "qps")}
        base_value = _to_float_or_none(baseline_params.get(param_name))
        if base_value is not None and base_value > 0.0:
            for sample in samples:
                candidate_value = _to_float_or_none(sample["params"].get(param_name))
                if candidate_value is None or candidate_value <= 0.0:
                    continue
                xs.append(math.log(float(candidate_value) / float(base_value)))
                for outcome_name in ys:
                    ys[outcome_name].append(float(sample["outcomes"][outcome_name]))
        supported = len(xs) >= 3 and (max(xs) - min(xs) > 1e-12)
        frozen = prior_confidence < float(low_confidence_freeze_threshold)
        correlations: Dict[str, float] = {}
        if supported and not frozen:
            x_array = np.asarray(xs, dtype=float)
            for outcome_name, values in ys.items():
                y_array = np.asarray(values, dtype=float)
                correlation = 0.0
                if float(np.std(y_array)) > 1e-12:
                    correlation = float(np.corrcoef(x_array, y_array)[0, 1])
                    if not math.isfinite(correlation):
                        correlation = 0.0
                correlations[outcome_name] = correlation
                empirical_effect = max(-0.20, min(0.20, 0.20 * correlation))
                effects[outcome_name] = (
                    0.50 * float(effects.get(outcome_name, 0.0) or 0.0)
                    + 0.50 * empirical_effect
                )
            signal_confidence = float(
                sum(abs(value) for value in correlations.values())
                / max(1, len(correlations))
            )
            effects["confidence"] = min(
                0.95,
                max(prior_confidence * 0.80, signal_confidence),
            )
        effects["evidence_count"] = prior_evidence + float(len(xs))
        rows.append(
            {
                "parameter": param_name,
                "supported": supported,
                "frozen_low_confidence": frozen,
                "prior_confidence": prior_confidence,
                "updated_confidence": float(effects.get("confidence", prior_confidence)),
                "new_evidence_count": len(xs),
                "correlations": correlations,
                "updated_effects": copy.deepcopy(effects),
            }
        )

    def ranking_key(candidate: Any) -> Tuple[int, float, int]:
        params = getattr(candidate, "optimized_params", {}) or {}
        predicted = {name: 0.0 for name in (target_resource, "qps")}
        for param_name, effects in updated.items():
            confidence = float(effects.get("confidence", 1.0) or 0.0)
            if confidence < float(low_confidence_freeze_threshold):
                continue
            base_value = _to_float_or_none(baseline_params.get(param_name))
            candidate_value = _to_float_or_none(params.get(param_name))
            if (
                base_value is None
                or candidate_value is None
                or base_value <= 0.0
                or candidate_value <= 0.0
            ):
                continue
            delta = math.log(float(candidate_value) / float(base_value))
            for outcome_name in predicted:
                predicted[outcome_name] += (
                    delta
                    * float(effects.get(outcome_name, 0.0) or 0.0)
                    * confidence
                )
        pairwise_direction = int(
            predicted["qps"] > 0.0 and predicted[target_resource] < 0.0
        )
        score = predicted["qps"] - predicted[target_resource]
        old_rank = int(getattr(candidate, "gradient_subset_candidate_rank", 0) or 0)
        setattr(candidate, "gradient_online_delta_prediction", predicted)
        setattr(candidate, "gradient_pre_online_rank", old_rank)
        return pairwise_direction, score, -old_rank

    reranked = sorted(list(remaining_candidates), key=ranking_key, reverse=True)
    for online_rank, candidate in enumerate(reranked, start=1):
        setattr(candidate, "gradient_online_rank", online_rank)
    return updated, reranked, {
        "sample_count": len(samples),
        "low_confidence_freeze_threshold": float(low_confidence_freeze_threshold),
        "parameter_updates": rows,
        "remaining_candidate_count": len(reranked),
        "target_resource": target_resource,
        "remaining_pre_online_ranks": [
            int(getattr(candidate, "gradient_pre_online_rank", 0) or 0)
            for candidate in reranked
        ],
    }


def _bruteforce_first_stage_ranking_gate_applies(
    optimizer_mode: str,
    require_gate: bool,
    summary: Dict[str, Any],
) -> bool:
    """The legacy ranking-quality gate must never terminate SGD outer search."""
    return bool(
        str(optimizer_mode).strip().lower() == "bruteforce"
        and require_gate
        and not bool(summary.get("first_stage_ranking_validation_pass"))
    )


def _gradient_expected_normalized_width(accepted_shrink_count: int) -> float:
    """Each accepted all-dimension binary shrink halves normalized width."""
    if accepted_shrink_count < 0:
        raise ValueError("accepted_shrink_count cannot be negative")
    return 0.5 ** accepted_shrink_count


def _legacy_feedback_early_stop_allowed(optimizer_mode: str) -> bool:
    """Legacy reject/resource convergence stops never complete formal gradient."""
    return str(optimizer_mode).strip().lower() != "gradient"


def _plan_estimator_bootstrap_runtime_source(runtime_source: Any) -> str:
    """Validate the real monitor used by plan-estimator bootstrap-once."""
    normalized = str(runtime_source or "").strip().lower()
    if normalized not in {"docker-runtime", "vm-runtime"}:
        raise ValueError(
            "plan-estimator bootstrap requires final_evaluation.runtime_source "
            "to be 'docker-runtime' or 'vm-runtime', got "
            f"{runtime_source!r}"
        )
    return normalized


def _dispatch_plan_estimator_bootstrap_monitor(
    runtime_source: Any,
    *,
    docker_monitor: Callable[[], Tuple[Dict[str, float], Dict[str, Any]]],
    vm_monitor: Callable[[], Tuple[Dict[str, float], Dict[str, Any]]],
) -> Tuple[Dict[str, float], Dict[str, Any]]:
    """Run exactly one bootstrap monitor selected by the configured runtime."""
    normalized = _plan_estimator_bootstrap_runtime_source(runtime_source)
    if normalized == "docker-runtime":
        return docker_monitor()
    return vm_monitor()


def _baseline_workload_command(
    workload_cmd: str,
    measurement_protocol: Mapping[str, Any],
) -> str:
    """Add an explicit R0-only gate flag without changing candidate commands."""
    flag = str(measurement_protocol.get("r0_profile_enforcement_flag") or "").strip()
    if not flag:
        return workload_cmd
    flag_tokens = shlex.split(flag)
    if not flag_tokens or any(not token.startswith("--") for token in flag_tokens):
        raise ValueError("r0_profile_enforcement_flag must contain option flags only")
    command_tokens = shlex.split(workload_cmd)
    if all(token in command_tokens for token in flag_tokens):
        return workload_cmd
    return f"{workload_cmd} {flag}"


def _gradient_take_unseen_rankings(
    rankings: Sequence[Dict[str, Any]],
    seen_signatures: Set[Tuple[Tuple[str, str], ...]],
    *,
    limit: int,
    excluded_signatures: Optional[Set[Tuple[Tuple[str, str], ...]]] = None,
) -> Tuple[List[Dict[str, Any]], List[int], List[int]]:
    """Peek unseen, non-excluded rankings without claiming replay evidence."""
    if limit <= 0:
        raise ValueError("limit must be positive")
    selected: List[Dict[str, Any]] = []
    selected_ranks: List[int] = []
    skipped_seen_ranks: List[int] = []
    excluded = excluded_signatures or set()
    for candidate_record in rankings:
        params = candidate_record.get("optimized_params") or {}
        if not isinstance(params, dict) or not params:
            continue
        signature = _SharedPlanEstimateFutureCache._signature(params)
        rank = int(candidate_record.get("rank") or 0)
        if signature in excluded:
            continue
        if signature in seen_signatures:
            skipped_seen_ranks.append(rank)
            continue
        selected.append(candidate_record)
        selected_ranks.append(rank)
        if len(selected) >= limit:
            break
    return selected, selected_ranks, skipped_seen_ranks


def _gradient_mark_replayed_params(
    params: Mapping[str, Any],
    seen_signatures: Set[Tuple[Tuple[str, str], ...]],
) -> bool:
    """Commit one parameter signature only after real point evidence exists."""
    signature = _SharedPlanEstimateFutureCache._signature(params)
    was_new = signature not in seen_signatures
    seen_signatures.add(signature)
    return was_new


def _gradient_real_candidate_rank_key(
    validation: Mapping[str, Any],
    params: Mapping[str, Any],
    *,
    target_resource: Optional[str],
    active_param_order: Optional[Sequence[str]] = None,
) -> Tuple[float, ...]:
    """DB-QPS desc, target utilization asc, manifest-active tuple asc."""
    try:
        db_qps = float(validation.get("db_qps"))
    except (TypeError, ValueError):
        db_qps = float("-inf")
    raw_target_util = (validation.get("utilization_pct") or {}).get(
        target_resource or ""
    )
    try:
        target_util = float(raw_target_util)
    except (TypeError, ValueError):
        target_util = float("inf")
    ordered_names = [
        str(name)
        for name in (active_param_order or sorted(params))
        if str(name) in params
    ]
    canonical_param_tiebreak = tuple(-float(params[name]) for name in ordered_names)
    return (db_qps, -target_util, *canonical_param_tiebreak)


def baseline_anchor_correction_exempt_resources(
    *,
    applied_model_paths: Dict[str, str],
    baseline_error_bounds: Dict[str, Any],
    baseline_sanity_gate: Dict[str, Any],
) -> List[str]:
    """Return resources whose learned point estimates are already baseline anchored."""
    if not baseline_sanity_gate.get("passed"):
        return []
    updated = baseline_error_bounds.get("updated") or {}
    applied = set(applied_model_paths)
    exempt: Set[str] = set()
    for check in baseline_sanity_gate.get("checks") or []:
        if not isinstance(check, dict) or not check.get("passed"):
            continue
        resource = str(check.get("resource") or "").strip().lower()
        anchor = check.get("baseline_anchor_calibration")
        if (
            resource in applied
            and resource in updated
            and isinstance(anchor, dict)
            and anchor.get("applied")
        ):
            exempt.add(resource)
    return sorted(exempt)


def apply_baseline_correction_scales(
    normalized_resource: Dict[str, float],
    *,
    scales: Dict[str, float],
    exempt_resources: Sequence[str] = (),
) -> Dict[str, float]:
    """Apply legacy baseline scales without rescaling already anchored resources."""
    corrected = dict(normalized_resource)
    exempt = {str(item).strip().lower() for item in exempt_resources}
    for key, scale in scales.items():
        if str(key).strip().lower() in exempt:
            continue
        corrected[key] = float(corrected.get(key, 0.0) or 0.0) * float(scale)
    return corrected


def phase2_known_real_seed_bypass_allowed(
    record: Dict[str, Any],
    target_resource: str,
    *,
    min_interpolation_step: float = 0.5,
) -> bool:
    """Return whether a known-real seed may bypass estimated direction gates."""
    if not isinstance(record, dict) or not bool(record.get("phase2_known_real_direction_seed")):
        return False
    if not bool(record.get("phase2_known_real_prefix_goal_passed", True)):
        return False
    seed_target = str(
        record.get("phase2_known_real_target_resource") or target_resource or ""
    ).strip().lower()
    if not seed_target or seed_target != str(target_resource or "").strip().lower():
        return False
    source = str(record.get("source") or "").strip()
    if source in {"candidate_anchor_probe", "candidate_near_hit_anchor_probe"} and record.get("value") is not None:
        try:
            interpolation_step = float(record.get("value"))
        except (TypeError, ValueError):
            return False
        if not math.isfinite(interpolation_step):
            return False
        if interpolation_step < max(0.0, float(min_interpolation_step)):
            return False
    return True


def _apply_effective_replay_pruning_gate_summary(
    summary: Dict[str, Any],
    *,
    actual_replayed_candidate_count: int,
    pruned_candidate_count: int,
    pruned_candidates: List[Dict[str, Any]],
    candidate_replay_top_k: int,
    bf_cfg: Dict[str, Any],
    replay_pruning_enabled: bool,
) -> None:
    """Update small-loop ranking summary with pruning-aware replay coverage."""
    if not isinstance(summary, dict):
        return

    effective_potential_replay_count = max(
        0,
        int(candidate_replay_top_k) - int(pruned_candidate_count),
    )
    min_after_pruning_count = max(
        2,
        int(
            bf_cfg.get(
                "small_loop_min_validated_after_pruning_count",
                min(5, int(candidate_replay_top_k)),
            )
        ),
    )
    raw_required_count = int(
        summary.get("required_validated_candidate_count", candidate_replay_top_k)
        or candidate_replay_top_k
    )
    effective_required_after_pruning = min(
        raw_required_count,
        max(min_after_pruning_count, effective_potential_replay_count),
    )
    effective_topk_validation_ready = (
        actual_replayed_candidate_count >= effective_required_after_pruning
    )

    summary.update(
        {
            "replay_pruning_enabled": replay_pruning_enabled,
            "replay_pruning_scope": "pre_real_validation_only",
            "processed_candidate_count": (
                actual_replayed_candidate_count + pruned_candidate_count
            ),
            "actual_replayed_candidate_count": actual_replayed_candidate_count,
            "replay_pruned_candidate_count": pruned_candidate_count,
            "replay_pruned_candidates_participate_in_ranking": False,
            "effective_potential_replay_count_after_pruning": (
                effective_potential_replay_count
            ),
            "effective_required_validated_candidate_count_after_pruning": (
                effective_required_after_pruning
            ),
            "effective_topk_validation_ready_after_pruning": (
                effective_topk_validation_ready
            ),
            "topk_validation_count_basis": (
                "actual_replayed_candidates_after_pruning"
                if replay_pruning_enabled
                else "validated_candidates_without_pruning"
            ),
            "replay_pruned_candidates": copy.deepcopy(pruned_candidates),
        }
    )

    if (
        not replay_pruning_enabled
        or summary.get("topk_validation_ready")
        or not effective_topk_validation_ready
    ):
        return

    summary["topk_validation_ready"] = True
    summary["ranking_validation_basis"] = (
        "actual_replayed_potential_candidates_only; pruned top-k entries were "
        "excluded before real validation by replay pruning"
    )
    pairwise_rate = summary.get("pairwise_inversion_rate")
    pairwise_threshold = float(summary.get("pairwise_inversion_threshold", 0.10))
    pairwise_close = pairwise_rate is not None and float(pairwise_rate) <= pairwise_threshold
    goal_rich_prefix_override = bool(
        summary.get("long_term_goal_hit_count_met")
        and _to_bool(
            bf_cfg.get(
                "small_loop_allow_goal_rich_prefix_despite_pairwise_inversion",
                False,
            ),
            False,
        )
    )
    summary["ranking_close"] = pairwise_close
    summary["goal_rich_prefix_override"] = bool(goal_rich_prefix_override)
    summary["first_stage_ranking_validation_pass"] = bool(
        pairwise_close or goal_rich_prefix_override
    )
    summary["first_stage_only_goal_met"] = bool(
        pairwise_close or goal_rich_prefix_override
    )
    summary["short_term_goal_met"] = bool(
        (pairwise_close or goal_rich_prefix_override)
        and summary.get("long_term_goal_hit_count_met")
    )
    if pairwise_close or goal_rich_prefix_override:
        summary["next_action_hint"] = (
            "continue_outer_amplification"
            if summary.get("long_term_goal_hit_count_met")
            else "adjust_score_to_put_3_5_long_term_goal_candidates_in_topk"
        )
    else:
        summary["next_action_hint"] = "improve_inner_loop_ranking_before_long_run"


def _lane_aware_replay_prefix_validation(
    replayed_candidates: List[Dict[str, Any]],
    *,
    target_resource: str,
    baseline_resource: Dict[str, float],
    capability: Dict[str, float],
    mandatory_anchor_indices: Sequence[int] = (),
    forced_anchor_indices: Sequence[int] = (),
    lane_quota_config: Optional[Any] = None,
    conservative_error_bound_pp: Optional[float] = None,
    min_delta_util_pct: float = 0.50,
    min_other_up_util_pct: float = 0.50,
    plateau_predicted_values: Optional[List[float]] = None,
) -> Dict[str, Any]:
    """ lane aware replay prefix validation."""


    from adaptive_replay_controller import (
        LaneQuotaConfig,
        ReplayLane,
        assign_lanes,
        enforce_lane_quotas,
    )

    quota = lane_quota_config if lane_quota_config is not None else LaneQuotaConfig()
    empty_lanes = {lane.value: [] for lane in ReplayLane}
    empty_counts = {lane.value: 0 for lane in ReplayLane}

    if not replayed_candidates:
        return {
            "lane_counts": dict(empty_counts),
            "explainable_lane_empty": True,
            "explainable_lane_hit_count": 0,
            "lane_quota_exceeded": {},
            "no_count_fill_applied": True,
            "mandatory_anchor_count": 0,
            "quota_config": {
                "max_budget": quota.max_budget,
                "min_evidence": quota.min_evidence,
                "batch_size": quota.batch_size,
                "max_expansions": quota.max_expansions,
                "explainable": quota.explainable,
                "fallback": quota.fallback,
                "diagnostic": quota.diagnostic,
                "mandatory_anchor": quota.mandatory_anchor,
                "reserve": quota.reserve,
            },
            "lane_assignment": dict(empty_lanes),
            "target_resource": target_resource,
        }

    lane_assignment = assign_lanes(
        list(replayed_candidates),
        target_resource=target_resource,
        baseline_resource=baseline_resource,
        capability=capability,
        mandatory_anchor_indices=tuple(mandatory_anchor_indices),
        forced_anchor_indices=tuple(forced_anchor_indices),
        min_delta_util_pct=min_delta_util_pct,
        min_other_up_util_pct=min_other_up_util_pct,
        conservative_error_bound_pp=conservative_error_bound_pp,
        plateau_predicted_values=plateau_predicted_values,
    )

    enforcement = enforce_lane_quotas(lane_assignment, quota)
    lane_counts = enforcement["lane_counts"]

    return {
        "lane_counts": lane_counts,
        "explainable_lane_empty": enforcement["explainable_lane_empty"],
        "explainable_lane_hit_count": int(lane_counts.get("explainable", 0)),
        "lane_quota_exceeded": enforcement["lane_quota_exceeded"],
        "no_count_fill_applied": True,
        "mandatory_anchor_count": int(lane_counts.get("mandatory_anchor", 0)),
        "quota_config": enforcement["quota_config"],
        "lane_assignment": lane_assignment,
        "target_resource": target_resource,
    }


def _collect_mandatory_anchor_indices(
    candidates: List[Dict[str, Any]],
    *,
    target_resource: str = "",
) -> List[int]:
    """ collect mandatory anchor indices."""


    if not candidates:
        return []
    indices: List[int] = []
    for idx, item in enumerate(candidates):
        if not isinstance(item, dict):
            continue
        if bool(item.get("is_mandatory_anchor")):
            indices.append(idx)
            continue
        reason = str(item.get("selection_reason") or "")
        if (
            "forced_replay_anchor" in reason or "anchor" in reason
        ) and bool(item.get("phase2_known_real_direction_seed")):
            indices.append(idx)
            continue
        if bool(item.get("phase2_known_replay_anchor")):
            indices.append(idx)
            continue
        if bool(item.get("is_global_best_replay_anchor")):
            indices.append(idx)
            continue
    return indices


def _collect_forced_anchor_indices(
    candidates: List[Dict[str, Any]],
) -> List[int]:
    """ collect forced anchor indices."""


    if not candidates:
        return []
    indices: List[int] = []
    for idx, item in enumerate(candidates):
        if not isinstance(item, dict):
            continue
        if bool(item.get("is_forced_anchor")):
            indices.append(idx)
            continue
        reason = str(item.get("selection_reason") or "")
        if "forced_replay_anchor" in reason:
            indices.append(idx)
            continue
    return indices


def _apply_lane_aware_replay_summary(
    summary: Dict[str, Any],
    *,
    replayed_candidates: List[Dict[str, Any]],
    target_resource: str,
    baseline_resource: Dict[str, float],
    capability: Dict[str, float],
    mandatory_anchor_indices: Sequence[int] = (),
    forced_anchor_indices: Sequence[int] = (),
    lane_quota_config: Optional[Any] = None,
    conservative_error_bound_pp: Optional[float] = None,
    min_delta_util_pct: float = 0.50,
    min_other_up_util_pct: float = 0.50,
    plateau_predicted_values: Optional[List[float]] = None,
) -> Dict[str, Any]:
    """ apply lane aware replay summary."""


    if not isinstance(summary, dict):
        return {}

    lane_info = _lane_aware_replay_prefix_validation(
        list(replayed_candidates),
        target_resource=target_resource,
        baseline_resource=baseline_resource,
        capability=capability,
        mandatory_anchor_indices=tuple(mandatory_anchor_indices),
        forced_anchor_indices=tuple(forced_anchor_indices),
        lane_quota_config=lane_quota_config,
        conservative_error_bound_pp=conservative_error_bound_pp,
        min_delta_util_pct=min_delta_util_pct,
        min_other_up_util_pct=min_other_up_util_pct,
        plateau_predicted_values=plateau_predicted_values,
    )

    summary.update(
        {
            "lane_aware_replay_validation": True,
            "lane_counts": lane_info.get("lane_counts", {}),
            "explainable_lane_empty": bool(
                lane_info.get("explainable_lane_empty", False)
            ),
            "explainable_lane_hit_count": int(
                lane_info.get("explainable_lane_hit_count", 0)
            ),
            "lane_quota_exceeded": lane_info.get("lane_quota_exceeded", {}),
            "no_count_fill_applied": bool(
                lane_info.get("no_count_fill_applied", True)
            ),
            "mandatory_anchor_count": int(
                lane_info.get("mandatory_anchor_count", 0)
            ),
            "lane_quota_config": lane_info.get("quota_config", {}),
            "lane_assignment": lane_info.get("lane_assignment", {}),
        }
    )


    if lane_info.get("explainable_lane_empty"):
        summary["first_stage_ranking_validation_pass"] = False
        summary["short_term_goal_met"] = False
        summary["first_stage_only_goal_met"] = False
        summary["next_action_hint"] = "stop_fix_ranking_explainable_lane_empty"
        summary["explainable_lane_empty_stop_fix"] = True

    return lane_info


def _compute_adaptive_replay_decision(
    *,
    candidate_evaluations: List[Dict[str, Any]],
    summary: Dict[str, Any],
    target_resource: str,
    baseline_resource: Dict[str, float],
    capability: Dict[str, float],
    replayed_count: int,
    batch_index: int = 0,
    batches_so_far: int = 1,
    expansions_used: int = 0,
    safety_model_gate_passed: bool = True,
    io_source_valid: bool = True,
    io_stable_sample_count_positive: bool = True,
    remaining_upper_bound_beats_best: bool = False,
    lane_quota_config: Optional[Any] = None,
    target_resource_for_lane: Optional[str] = None,
) -> Dict[str, Any]:
    """ compute adaptive replay decision."""


    try:

        from adaptive_replay_controller import (
            AdaptiveReplayController,
            BatchInputs,
            LaneQuotaConfig,
        )


        # I2: explainable lane conservative-pass count

        explainable_conservative_pass_count = int(
            summary.get("explainable_lane_hit_count", 0)
        )


        fallback_best_db_qps_delta_pct: Optional[float] = None
        for item in candidate_evaluations:
            if not isinstance(item, dict):
                continue
            status = item.get("candidate_primary_target_status") or {}
            if not isinstance(status, dict):
                continue
            db_delta = status.get("db_qps_delta_pct")
            if db_delta is None:
                continue
            try:
                db_delta_f = float(db_delta)
            except (TypeError, ValueError):
                continue
            if (
                fallback_best_db_qps_delta_pct is None
                or db_delta_f > fallback_best_db_qps_delta_pct
            ):
                fallback_best_db_qps_delta_pct = db_delta_f

        # I4: pairwise inversion rate
        pairwise_inversion_rate = float(summary.get("pairwise_inversion_rate") or 0.0)


        ranking_stable = bool(
            summary.get("first_stage_ranking_validation_pass", False)
        )

        # I7: cumulative target-down evidence count

        cumulative_target_down_evidence_count = 0
        for item in candidate_evaluations:
            if not isinstance(item, dict):
                continue
            status = item.get("candidate_primary_target_status") or {}
            if not isinstance(status, dict):
                continue
            bottleneck_delta_pp = status.get("bottleneck_resource_delta_pp")
            if bottleneck_delta_pp is None:
                continue
            try:
                if float(bottleneck_delta_pp) < 0.0:
                    cumulative_target_down_evidence_count += 1
            except (TypeError, ValueError):
                continue

        # lane_counts from summary (cumulative this round)
        lane_counts = dict(summary.get("lane_counts") or {})


        inputs = BatchInputs(
            safety_model_gate_passed=safety_model_gate_passed,
            io_source_valid=io_source_valid,
            io_stable_sample_count_positive=io_stable_sample_count_positive,
            explainable_conservative_pass_count=explainable_conservative_pass_count,
            fallback_best_db_qps_delta_pct=fallback_best_db_qps_delta_pct,
            pairwise_inversion_rate=pairwise_inversion_rate,
            remaining_upper_bound_beats_best=remaining_upper_bound_beats_best,
            ranking_stable=ranking_stable,
            cumulative_target_down_evidence_count=cumulative_target_down_evidence_count,
            batch_index=batch_index,
            batches_so_far=batches_so_far,
            replayed_count=replayed_count,
            expansions_used=expansions_used,
            lane_counts=lane_counts,
        )


        controller = AdaptiveReplayController(
            quota=lane_quota_config if lane_quota_config is not None else LaneQuotaConfig(),
            target_resource=target_resource,
        )
        decision = controller.decide_batch(inputs)


        record = decision.to_jsonl_record()
        record["phase1_integration"] = True
        record["phase_note"] = (
            "phase 1 replay-all + summary  decide_batch"
            " per-batch  JSONL  replay "
        )
        record["target_resource"] = target_resource
        record["replayed_count"] = int(replayed_count)
        return record
    except Exception as exc:
        return {
            "event": "adaptive_replay_decision",
            "decision": "compute_error",
            "reason": f"phase1 helper exception: {type(exc).__name__}: {exc}",
            "phase1_integration": True,
            "target_resource": target_resource,
            "replayed_count": int(replayed_count),
        }


def load_optimizer_config(config_path: str) -> Dict[str, Any]:
    """
    Load optimizer configuration from a JSON file.
    Returns {} when config is missing/invalid so code can keep defaults.
    """
    try:
        if not config_path or not os.path.exists(config_path):
            return {}
        with open(config_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def save_optimizer_config(config_path: str, cfg: Dict[str, Any]) -> None:
    """
    Persist optimizer configuration to JSON.

    This is used by optional runtime calibration logic that intentionally
    adjusts capability limits before optimization starts.
    """
    if not config_path:
        raise ValueError("config_path is empty")
    with open(config_path, "w", encoding="utf-8") as f:
        json.dump(cfg, f, ensure_ascii=False, indent=2)
        f.write("\n")


def enforce_cost_param_scope(cfg: Dict[str, Any]) -> None:
    """Enforce the Bonect hard constraint: only seven planner cost params tune."""
    constraints = cfg.get("tuning_constraints")
    if not isinstance(constraints, dict) or not bool(constraints.get("strict_cost_params_only")):
        return

    allowed = constraints.get("allowed_params")
    allowed_set = {str(item) for item in allowed} if isinstance(allowed, list) else set(COST_PARAM_SET)
    if allowed_set != COST_PARAM_SET:
        raise ValueError(
            "strict_cost_params_only requires exactly these allowed_params: "
            f"{COST_PARAM_KEYS}; got {sorted(allowed_set)}"
        )

    violations: List[str] = []

    def check_keys(path: str, value: Any) -> None:
        if value is None:
            return
        if isinstance(value, dict):
            keys = value.keys()
        elif isinstance(value, list):
            keys = [str(item) for item in value]
        elif isinstance(value, str):
            keys = [part.strip() for part in value.split(",") if part.strip()]
        else:
            return
        invalid = sorted(str(key) for key in keys if str(key) not in COST_PARAM_SET)
        if invalid:
            violations.append(f"{path}: {invalid}")

    check_keys("p_real", cfg.get("p_real"))
    check_keys("p_candidate", cfg.get("p_candidate"))
    check_keys("initial_params", cfg.get("initial_params"))
    check_keys("param_ranges", cfg.get("param_ranges"))
    check_keys("param_step_scale", cfg.get("param_step_scale"))
    check_keys("sensitivity_table", cfg.get("sensitivity_table"))
    check_keys("fixed_params", cfg.get("fixed_params"))

    optimizer = cfg.get("optimizer")
    if isinstance(optimizer, dict):
        check_keys("optimizer.active_params", optimizer.get("active_params"))
        check_keys("optimizer.param_step_scale", optimizer.get("param_step_scale"))
        check_keys("optimizer.sensitivity_table", optimizer.get("sensitivity_table"))
        gradient = optimizer.get("gradient")
        if isinstance(gradient, dict):
            check_keys("optimizer.gradient.active_params", gradient.get("active_params"))
            check_keys("optimizer.gradient.boosted_params", gradient.get("boosted_params"))
            trial = gradient.get("aggressive_trial")
            if isinstance(trial, dict):
                check_keys("optimizer.gradient.aggressive_trial.params", trial.get("params"))
        bruteforce = optimizer.get("bruteforce")
        if isinstance(bruteforce, dict):
            check_keys("optimizer.bruteforce.active_params", bruteforce.get("active_params"))

    if violations:
        raise ValueError(
            "Bonect tuning is restricted to the seven PostgreSQL planner cost parameters only: "
            f"{COST_PARAM_KEYS}. Non-cost tuning fields found: {'; '.join(violations)}"
        )


def load_explicit_experience_table_contract(
    cfg: Dict[str, Any],
    config_path: str,
    active_params: Sequence[str],
) -> Tuple[Optional[Dict[str, Dict[str, float]]], Dict[str, Any]]:
    """Load and fail-closed validate a benchmark-scoped frozen experience table.

    Legacy configurations remain supported unless either the contract or the
    gradient section explicitly requires a frozen table.  Once required, the
    table must be present in full in the runtime configuration and must exactly
    match the separately hashed artifact.  Partial overrides and the built-in
    fallback are therefore impossible on the formal path.
    """
    optimizer_cfg = cfg.get("optimizer")
    if not isinstance(optimizer_cfg, dict):
        optimizer_cfg = {}
    gradient_cfg = optimizer_cfg.get("gradient")
    if not isinstance(gradient_cfg, dict):
        gradient_cfg = {}
    contract = cfg.get("experience_table_contract")
    contract_required = bool(
        isinstance(contract, dict) and contract.get("required") is True
    )
    gradient_required = gradient_cfg.get("require_explicit_sensitivity_table") is True
    required = contract_required or gradient_required
    if not required:
        return None, {"required": False, "fallback_disabled": False}
    if not isinstance(contract, dict):
        raise ValueError(
            " experience_table_contract  fallback"
        )
    if contract.get("required") is not True:
        raise ValueError("experience_table_contract.required  true")
    if contract.get("disable_fallback") is not True:
        raise ValueError("experience_table_contract.disable_fallback  true")
    if contract.get("fallback_enabled") is not False:
        raise ValueError("experience_table_contract.fallback_enabled  false")
    if gradient_cfg.get("require_explicit_sensitivity_table") is not True:
        raise ValueError(
            "optimizer.gradient.require_explicit_sensitivity_table  true"
        )

    artifact_path_raw = contract.get("artifact_path")
    if not isinstance(artifact_path_raw, str) or not artifact_path_raw.strip():
        raise ValueError("experience_table_contract.artifact_path ")
    artifact_path = Path(artifact_path_raw)
    if not artifact_path.is_absolute():
        artifact_path = Path(config_path).resolve().parent / artifact_path
    artifact_path = artifact_path.resolve()
    if not artifact_path.is_file():
        raise ValueError(f" artifact : {artifact_path}")

    artifact_bytes = artifact_path.read_bytes()
    actual_artifact_sha256 = hashlib.sha256(artifact_bytes).hexdigest()
    expected_artifact_sha256 = str(contract.get("artifact_sha256") or "").lower()
    if actual_artifact_sha256 != expected_artifact_sha256:
        raise ValueError(
            " artifact SHA256 : "
            f"actual={actual_artifact_sha256}, expected={expected_artifact_sha256}"
        )
    try:
        artifact = json.loads(artifact_bytes.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError(f" artifact  UTF-8 JSON: {artifact_path}") from exc
    if not isinstance(artifact, dict):
        raise ValueError(" artifact ")

    for key in ("table_id", "version", "table_sha256"):
        expected_value = contract.get(key)
        actual_value = artifact.get(key)
        if not isinstance(expected_value, str) or not expected_value:
            raise ValueError(f"experience_table_contract.{key} ")
        if actual_value != expected_value:
            raise ValueError(
                f" {key} : actual={actual_value!r}, "
                f"expected={expected_value!r}"
            )
    for key in ("finite_difference_direction_enabled", "random_direction_enabled"):
        if contract.get(key) is not False or artifact.get(key) is not False:
            raise ValueError(f" contract  artifact  {key}=false")

    canonical_active_params = [str(name) for name in active_params]
    contract_active_params = contract.get("active_params")
    artifact_active_params = artifact.get("active_params")
    active_param_set = set(canonical_active_params)
    expected_active_order = [
        name for name in COST_PARAM_KEYS if name in active_param_set
    ]
    if not canonical_active_params or canonical_active_params != expected_active_order:
        raise ValueError(
            " active_params  cost : "
            f"actual={canonical_active_params}, canonical_order={COST_PARAM_KEYS}"
        )
    if contract_active_params != canonical_active_params:
        raise ValueError(
            "experience_table_contract.active_params  active_params "
        )
    if artifact_active_params != canonical_active_params:
        raise ValueError(" artifact.active_params  active_params ")

    contract_fixed_params = contract.get("fixed_params", {})
    artifact_fixed_params = artifact.get("fixed_params", {})
    if contract_fixed_params != artifact_fixed_params:
        raise ValueError("experience_table_contract.fixed_params  artifact ")
    if not isinstance(contract_fixed_params, dict):
        raise ValueError("experience_table_contract.fixed_params ")
    parsed_fixed_params: Dict[str, float] = {}
    initial_params = cfg.get("initial_params")
    if not isinstance(initial_params, dict):
        initial_params = {}
    for raw_name, raw_value in contract_fixed_params.items():
        name = str(raw_name)
        if name not in COST_PARAM_SET:
            raise ValueError(f" fixed_params  cost : {name}")
        if name in active_param_set:
            raise ValueError(f" active_params: {name}")
        if isinstance(raw_value, bool) or not isinstance(raw_value, (int, float)):
            raise ValueError(f"experience_table_contract.fixed_params.{name} ")
        value = float(raw_value)
        if not math.isfinite(value):
            raise ValueError(f"experience_table_contract.fixed_params.{name} ")
        try:
            initial_value = float(initial_params[name])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError(f"initial_params  {name}={value}") from exc
        if not math.isfinite(initial_value) or initial_value != value:
            raise ValueError(
                f"initial_params.{name} : "
                f"actual={initial_value}, expected={value}"
            )
        parsed_fixed_params[name] = value

    artifact_schema_version = int(artifact.get("schema_version", 1) or 1)
    low_confidence_freeze_threshold = float(
        artifact.get("low_confidence_freeze_threshold", 0.50) or 0.50
    )
    if not 0.0 <= low_confidence_freeze_threshold <= 1.0:
        raise ValueError(
            "artifact.low_confidence_freeze_threshold  [0, 1]"
        )
    contract_freeze_threshold = contract.get("low_confidence_freeze_threshold")
    if (
        artifact_schema_version >= 2
        and contract_freeze_threshold is not None
        and float(contract_freeze_threshold) != low_confidence_freeze_threshold
    ):
        raise ValueError(
            "experience_table_contract.low_confidence_freeze_threshold "
            " artifact "
        )
    resource_names = {"cpu", "memory", "io"}
    table_value_names = (
        resource_names
        if artifact_schema_version < 2
        else resource_names | {"qps", "confidence", "evidence_count"}
    )

    def validate_table(raw_table: Any, label: str) -> Dict[str, Dict[str, float]]:
        if not isinstance(raw_table, dict):
            raise ValueError(f"{label} ")
        if set(raw_table.keys()) != set(canonical_active_params):
            raise ValueError(
                f"{label} : actual={sorted(raw_table.keys())}, "
                f"expected={canonical_active_params}"
            )
        parsed: Dict[str, Dict[str, float]] = {}
        for param_name in canonical_active_params:
            resource_values = raw_table.get(param_name)
            if not isinstance(resource_values, dict):
                raise ValueError(f"{label}.{param_name} ")
            if set(resource_values) != table_value_names:
                raise ValueError(
                    f"{label}.{param_name}  experience-table schema "
                    f"v{artifact_schema_version}: "
                    f"actual={sorted(resource_values)}"
                )
            parsed[param_name] = {}
            for resource_name in sorted(table_value_names):
                value = resource_values[resource_name]
                if isinstance(value, bool) or not isinstance(value, (int, float)):
                    raise ValueError(
                        f"{label}.{param_name}.{resource_name} "
                    )
                numeric = float(value)
                if not math.isfinite(numeric):
                    raise ValueError(
                        f"{label}.{param_name}.{resource_name} "
                    )
                if resource_name == "confidence" and not 0.0 <= numeric <= 1.0:
                    raise ValueError(
                        f"{label}.{param_name}.confidence  [0, 1]"
                    )
                if resource_name == "evidence_count" and numeric < 0.0:
                    raise ValueError(
                        f"{label}.{param_name}.evidence_count "
                    )
                parsed[param_name][resource_name] = numeric
        return parsed

    artifact_table_raw = artifact.get("table")
    artifact_table = validate_table(artifact_table_raw, "artifact.table")
    actual_table_sha256 = hashlib.sha256(
        json.dumps(
            artifact_table_raw,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    expected_table_sha256 = str(contract.get("table_sha256") or "").lower()
    if actual_table_sha256 != expected_table_sha256:
        raise ValueError(
            " canonical table SHA256 : "
            f"actual={actual_table_sha256}, expected={expected_table_sha256}"
        )

    configured_table_raw = cfg.get("sensitivity_table")
    configured_table = validate_table(configured_table_raw, "sensitivity_table")
    configured_table_sha256 = hashlib.sha256(
        json.dumps(
            configured_table_raw,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    if configured_table_sha256 != expected_table_sha256:
        raise ValueError(
            "Configuration sensitivity_table canonical SHA256 : "
            f"actual={configured_table_sha256}, expected={expected_table_sha256}"
        )
    if configured_table != artifact_table:
        raise ValueError("Configuration sensitivity_table  artifact.table ")
    if "sensitivity_table" in optimizer_cfg:
        raise ValueError(
            " sensitivity_table optimizer.sensitivity_table "
        )

    binding = {
        "required": True,
        "fallback_disabled": True,
        "artifact_path": str(artifact_path),
        "artifact_sha256": actual_artifact_sha256,
        "table_id": artifact["table_id"],
        "version": artifact["version"],
        "table_sha256": actual_table_sha256,
        "active_params": canonical_active_params,
        "fixed_params": parsed_fixed_params,
        "finite_difference_direction_enabled": False,
        "random_direction_enabled": False,
        "schema_version": artifact_schema_version,
        "low_confidence_freeze_threshold": low_confidence_freeze_threshold,
    }
    return configured_table, binding


def _resource_quality_bool(value: Any, default: bool) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, str):
        v = value.strip().lower()
        if v in ("1", "true", "yes", "on"):
            return True
        if v in ("0", "false", "no", "off"):
            return False
    return default


def _to_bool(value: Any, default: bool) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    if isinstance(value, str):
        v = value.strip().lower()
        if v in ("1", "true", "yes", "on"):
            return True
        if v in ("0", "false", "no", "off"):
            return False
    return default


def _to_float_or_none(value: Any) -> Optional[float]:
    try:
        if value in (None, ""):
            return None
        result = float(value)
    except (TypeError, ValueError):
        return None
    return result if math.isfinite(result) else None


def _resolve_formal_db_qps(
    *,
    source: Any,
    benchmark_metrics: Mapping[str, Any],
    db_view_monitor: Mapping[str, Any],
) -> Tuple[float, str]:
    """Resolve formal DB QPS without falling back to workload QPS/TPS.

    ``formal_benchmark_db_qps`` is for a fresh/remote formal point whose runner
    samples ``pg_stat_statements`` inside that point. ``db_view_monitor`` is
    allowed only when the optimizer monitor is connected to the same database
    endpoint that executes the measured workload. The source must be explicit
    so a control database can never be mistaken for the formal point.
    """

    normalized_source = str(source or "").strip().lower()
    benchmark_aliases = {
        "formal_benchmark_db_qps",
        "benchmark.db_qps",
    }
    monitor_aliases = {
        "db_view_monitor",
        "formal_db_view_monitor",
    }
    if normalized_source in benchmark_aliases:
        value = _to_float_or_none(benchmark_metrics.get("db_qps"))
        canonical_source = "formal_benchmark_db_qps"
    elif normalized_source in monitor_aliases:
        value = _to_float_or_none(db_view_monitor.get("db_qps"))
        canonical_source = "formal_db_view_monitor"
    else:
        raise RuntimeError(
            "formal_pg_resource_semantics.db_qps_source must be explicitly "
            "'formal_benchmark_db_qps' or 'db_view_monitor'; workload QPS/TPS "
            "fallback is forbidden"
        )
    if value is None or value <= 0.0:
        raise RuntimeError(
            f"formal PostgreSQL validation is missing positive finite DB QPS "
            f"from {canonical_source}"
        )
    return float(value), canonical_source


def _baseline_only_measurement_issues(
    *,
    qps: Any,
    tps: Any,
    resource_normalized: Dict[str, Any],
    resource_utilization_pct: Dict[str, Any],
    benchmark: Dict[str, Any],
    collected_sql: Sequence[Any],
    benchmark_mode: str = "tp_mixed",
) -> List[str]:
    """Return missing/invalid fields that make a measured baseline unusable.

    Args:
        qps: measured queries-per-second
        tps: measured transactions-per-second
        resource_normalized: normalized resource usage dict
        resource_utilization_pct: utilization percentage dict
        benchmark: benchmark metadata dict
        collected_sql: collected SQL list
        benchmark_mode: one of "ap_only", "tp_only", "tp_mixed" (default).
            When "ap_only", db_tps may be zero/absent but db_qps must still be positive finite.
    """
    issues: List[str] = []
    is_ap_only = (benchmark_mode or "tp_mixed").strip().lower() == "ap_only"
    qps_num = _to_float_or_none(qps)
    if qps_num is None or qps_num <= 0.0:
        issues.append("db_qps")
    if not is_ap_only:
        tps_num = _to_float_or_none(tps)
        if tps_num is None or tps_num <= 0.0:
            issues.append("db_tps")
    for name in ("cpu", "memory", "io"):
        normalized = _to_float_or_none(resource_normalized.get(name))
        utilization = _to_float_or_none(resource_utilization_pct.get(name))
        if normalized is None or normalized <= 0.0:
            issues.append(f"resource_normalized.{name}")
        if utilization is None or utilization <= 0.0:
            issues.append(f"resource_utilization_pct.{name}")
    if not benchmark:
        issues.append("benchmark")
    if not collected_sql:
        issues.append("collected_sql")
    return issues


def _re_evaluate_single_bottleneck_gate(
    baseline_runtime_util: Dict[str, float],
    target_resource: str,
    strong_cfg: Dict[str, Any],
) -> Tuple[bool, List[Dict[str, Any]]]:
    """Re-evaluate single-bottleneck baseline gate with current utilization.

    Args:
        baseline_runtime_util: Current utilization dict (post-calibration).
        target_resource: Target bottleneck resource (cpu/memory/io).
        strong_cfg: Strong constraints config dict.

    Returns:
        (passed, checks) tuple.
    """
    target_min = float(
        _to_float_or_none(
            strong_cfg.get("bottleneck_initial_target_min_util_pct", 85.0)
        )
        or 85.0
    )
    target_max = float(
        _to_float_or_none(
            strong_cfg.get("bottleneck_initial_target_max_util_pct", 95.0)
        )
        or 95.0
    )
    non_target_min = float(
        _to_float_or_none(
            strong_cfg.get("bottleneck_initial_non_target_min_util_pct", 30.0)
        )
        or 30.0
    )
    non_target_max = float(
        _to_float_or_none(
            strong_cfg.get("bottleneck_initial_non_target_max_util_pct", 50.0)
        )
        or 50.0
    )
    if not 0.0 <= target_min <= target_max <= 100.0:
        raise ValueError(
            "bottleneck initial target band must satisfy 0 <= min <= max <= 100"
        )
    if not 0.0 <= non_target_min <= non_target_max <= 100.0:
        raise ValueError(
            "bottleneck initial non-target band must satisfy "
            "0 <= min <= max <= 100"
        )
    checks: List[Dict[str, Any]] = []
    for resource_name in ("cpu", "memory", "io"):
        util_value = _to_float_or_none(baseline_runtime_util.get(resource_name))
        is_target = resource_name == target_resource
        passed = (
            util_value is not None
            and (
                target_min <= float(util_value) <= target_max
                if is_target
                else non_target_min <= float(util_value) <= non_target_max
            )
        )
        checks.append({
            "resource": resource_name,
            "metric_source": "utilization_pct",
            "metric_value": util_value,
            "role": "target" if is_target else "non_target",
            "required_min": target_min if is_target else non_target_min,
            "required_max": target_max if is_target else non_target_max,
            "passed": bool(passed),
        })
    gate_passed = all(item.get("passed") for item in checks)
    return bool(gate_passed), checks


def _deprecated_phase2_env_overrides_enabled() -> bool:
    """Keep old short-loop env overrides opt-in only.

    Phase-2 top20 ranking gate now requires top20 replay diagnostics and
    CPU/IO/Memory retraining. Older automation used env vars to force top2 and
    Memory optional; those must not silently override the generated config.
    """
    return _to_bool(os.environ.get("BONECT_ENABLE_DEPRECATED_PHASE2_ENV_OVERRIDES"), False)


def _resource_quality_float(value: Any, default: Optional[float]) -> Optional[float]:
    try:
        if value in (None, ""):
            return default
        if isinstance(value, str) and value.strip().lower() in {"none", "null", "disabled"}:
            return None
        parsed = float(value)
        return parsed if math.isfinite(parsed) else default
    except (TypeError, ValueError):
        return default


def _resource_quality_int(value: Any, default: int) -> int:
    try:
        if value in (None, ""):
            return default
        return int(float(value))
    except (TypeError, ValueError):
        return default


def _resource_quality_list(value: Any, default: List[str]) -> List[str]:
    if value is None:
        return list(default)
    if isinstance(value, str):
        items = [item.strip() for item in value.split(",") if item.strip()]
        return items if items else list(default)
    if isinstance(value, list):
        items = [str(item).strip() for item in value if str(item).strip()]
        return items if items else list(default)
    return list(default)


def _resource_quality_workload_family(gate_cfg: Dict[str, Any]) -> str:
    for key in ("workload_family", "benchmark", "scenario", "workload_type"):
        value = str(gate_cfg.get(key) or "").strip().lower().replace("-", "_")
        if value in ("h", "tpch", "tpc_h", "ap", "runap", "h_serial", "hybench_ap"):
            return "H"
        if value in ("c", "tpcc", "tpc_c", "tp", "runtp", "c_only", "hybench_tp"):
            return "C"
        if value in ("ch", "hc", "mixed", "xp", "runxp", "hybench_xp"):
            return "CH"
    return "CH"


def _resource_quality_selected_record(
    *,
    resource_name: str,
    label: str,
    workload_family: str,
    io_hard_targets: Set[str],
    runtime_selected_model_set: str = "",
) -> bool:
    parts = [part for part in str(label or "").split(".") if part]
    if not parts:
        return False
    if resource_name == "cpu":
        expected = runtime_selected_model_set or {
            "H": "H_serial",
            "C": "C_only",
            "CH": "CH_only",
        }.get(workload_family, "CH_only")
        return parts[0] == expected
    if resource_name == "io":
        expected = runtime_selected_model_set or (
            workload_family if workload_family in {"H", "C", "CH"} else "CH"
        )
        if parts[0] != expected:
            return False
        if not io_hard_targets:
            return True
        return len(parts) >= 2 and parts[1] in io_hard_targets
    return True


def _iter_resource_model_metrics(node: Any, label: str = "") -> List[Dict[str, Any]]:
    """Extract train/test metric dictionaries from nested resource retrain summaries."""
    records: List[Dict[str, Any]] = []
    if isinstance(node, dict):
        train_metrics = node.get("train")
        test_metrics = node.get("test")
        if isinstance(train_metrics, dict) and isinstance(test_metrics, dict):
            records.append({"label": label or "model", "metrics": node})
            return records
        for key, value in node.items():
            child_label = f"{label}.{key}" if label else str(key)
            records.extend(_iter_resource_model_metrics(value, child_label))
    elif isinstance(node, list):
        for idx, value in enumerate(node):
            child_label = f"{label}[{idx}]" if label else f"[{idx}]"
            records.extend(_iter_resource_model_metrics(value, child_label))
    return records


def _role_aware_r2_fallback_decision(
    *,
    resource_name: str,
    metrics: Dict[str, Any],
    test_metrics: Dict[str, Any],
    retrain_result: Dict[str, Any],
    gate_cfg: Dict[str, Any],
) -> Dict[str, Any]:
    """Evaluate the explicit campaign-scoped R2 fallback, failing closed.

    This is not a global R2 relaxation.  It only applies when the retrain
    artifact supplies grouped-LOVO label-distribution evidence and the exact
    campaign/workload/target scope matches the configured policy.
    """
    policy = (
        gate_cfg.get("r2_fallback")
        if isinstance(gate_cfg.get("r2_fallback"), dict)
        else {}
    )
    context = (
        retrain_result.get("quality_gate_context")
        if isinstance(retrain_result.get("quality_gate_context"), dict)
        else {}
    )
    decision: Dict[str, Any] = {
        "enabled": _resource_quality_bool(policy.get("enabled", False), False),
        "eligible": False,
        "policy_id": str(policy.get("policy_id") or ""),
        "resource": resource_name,
        "reasons": [],
    }
    reasons: List[str] = decision["reasons"]
    if not decision["enabled"]:
        reasons.append("r2_fallback_disabled")
        return decision

    expected_scope = {
        "campaign_id": str(policy.get("campaign_id") or ""),
        "workload": str(policy.get("workload") or "").strip().lower(),
        "target_resource": str(policy.get("target_resource") or "").strip().lower(),
    }
    actual_scope = {
        "campaign_id": str(context.get("campaign_id") or ""),
        "workload": str(context.get("workload") or "").strip().lower(),
        "target_resource": str(context.get("target_resource") or "").strip().lower(),
    }
    decision["expected_scope"] = expected_scope
    decision["actual_scope"] = actual_scope
    if not all(expected_scope.values()):
        reasons.append("incomplete_policy_scope")
    if expected_scope != actual_scope:
        reasons.append("campaign_workload_or_target_scope_mismatch")
    if expected_scope.get("target_resource") != "memory":
        reasons.append("campaign_policy_target_resource_is_not_memory")
    configured_target = str(gate_cfg.get("target_resource") or "").strip().lower()
    if configured_target != expected_scope.get("target_resource"):
        reasons.append("quality_gate_target_resource_mismatch")

    unique_vectors = _resource_quality_int(
        context.get("unique_parameter_vector_count"),
        0,
    )
    minimum_vectors = max(
        1,
        _resource_quality_int(policy.get("min_unique_parameter_vectors"), 9),
    )
    decision["unique_parameter_vector_count"] = unique_vectors
    decision["min_unique_parameter_vectors"] = minimum_vectors
    if unique_vectors < minimum_vectors:
        reasons.append(
            f"unique_parameter_vector_count {unique_vectors} < {minimum_vectors}"
        )

    required_split = "grouped_leave_one_unique_parameter_vector_out"
    split_strategy = str(metrics.get("split_strategy") or "")
    decision["split_strategy"] = split_strategy
    if _resource_quality_bool(policy.get("require_grouped_lovo", True), True):
        if split_strategy != required_split:
            reasons.append("split_strategy_is_not_grouped_lovo")
        outer_fold_count = _resource_quality_int(metrics.get("outer_fold_count"), 0)
        decision["outer_fold_count"] = outer_fold_count
        if outer_fold_count != unique_vectors:
            reasons.append("outer_fold_count_does_not_match_unique_vectors")

    role = (
        "target"
        if resource_name == expected_scope.get("target_resource")
        else "non_target"
    )
    threshold_key = (
        "target_low_variance" if role == "target" else "non_target_bounded_level"
    )
    thresholds = (
        policy.get(threshold_key)
        if isinstance(policy.get(threshold_key), dict)
        else {}
    )
    decision["role"] = role
    decision["threshold_key"] = threshold_key
    decision["thresholds"] = copy.deepcopy(thresholds)
    if not thresholds:
        reasons.append(f"missing_{threshold_key}_thresholds")

    distribution = (
        test_metrics.get("label_distribution")
        if isinstance(test_metrics.get("label_distribution"), dict)
        else {}
    )
    observed = {
        "label_cv": _resource_quality_float(distribution.get("coefficient_of_variation"), None),
        "label_range_over_mean": _resource_quality_float(
            distribution.get("range_over_abs_mean"), None
        ),
        "relative_error_p95": _resource_quality_float(
            test_metrics.get("relative_error_p95"), None
        ),
        "relative_error_max": _resource_quality_float(
            test_metrics.get("relative_error_max"), None
        ),
        "abs_error_max_utilization_pp": _resource_quality_float(
            test_metrics.get("abs_error_max_utilization_pp"), None
        ),
        "oof_abs_error_max": _resource_quality_float(
            test_metrics.get("abs_error_max"), None
        ),
    }
    decision["observed"] = observed
    checks = (
        ("label_cv", "max_label_cv"),
        ("label_range_over_mean", "max_label_range_over_mean"),
        ("relative_error_p95", "max_relative_error_p95"),
        ("relative_error_max", "max_relative_error_max"),
        ("abs_error_max_utilization_pp", "max_abs_error_utilization_pp"),
    )
    for observed_name, threshold_name in checks:
        observed_value = observed.get(observed_name)
        threshold_value = _resource_quality_float(thresholds.get(threshold_name), None)
        if observed_value is None or threshold_value is None:
            reasons.append(f"missing_{observed_name}_or_{threshold_name}")
        elif observed_value > threshold_value:
            reasons.append(
                f"{observed_name} {observed_value:.6g} > {threshold_value:.6g}"
            )
    if _resource_quality_bool(policy.get("require_oof_abs_error_max", True), True):
        if observed.get("oof_abs_error_max") is None:
            reasons.append("missing_oof_abs_error_max")

    decision["eligible"] = not reasons
    return decision


def validate_resource_model_quality_gate(
    retrain_result: Dict[str, Any],
    gate_cfg: Optional[Dict[str, Any]] = None,
    baseline_estimation_metadata: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Validate pre-optimization CPU/IO/Memory resource-model train/test quality.

    The optimizer may run baseline and model retraining first, but it must not
    enter bruteforce/top-k optimization when required resource models fail this
    gate. Memory is optional by default for older configs, but when memory is
    required it must have real train/test evidence; a current-baseline
    single-sample intercept calibration is not a valid quality-gate pass.
    """
    gate_cfg = gate_cfg if isinstance(gate_cfg, dict) else {}
    enabled = _resource_quality_bool(gate_cfg.get("enabled", True), True)
    required_resources = _resource_quality_list(
        gate_cfg.get("required_resources"),
        ["cpu", "io"],
    )
    optional_resources_raw = gate_cfg.get("optional_resources")
    if "optional_resources" in gate_cfg and optional_resources_raw in (None, ""):
        optional_resources = []
    elif isinstance(optional_resources_raw, list) and not optional_resources_raw:
        optional_resources = []
    else:
        optional_resources = _resource_quality_list(
            optional_resources_raw,
            ["memory"],
        )
    min_test_samples = max(0, _resource_quality_int(gate_cfg.get("min_test_samples"), 5))
    max_test_relative_error_p95 = (
        None
        if "max_test_relative_error_p95" in gate_cfg
        and gate_cfg.get("max_test_relative_error_p95") in (None, "")
        else _resource_quality_float(gate_cfg.get("max_test_relative_error_p95"), 1.0)
    )
    max_test_relative_error_max = (
        None
        if "max_test_relative_error_max" in gate_cfg
        and gate_cfg.get("max_test_relative_error_max") in (None, "")
        else _resource_quality_float(gate_cfg.get("max_test_relative_error_max"), 5.0)
    )
    min_test_r2 = _resource_quality_float(gate_cfg.get("min_test_r2"), -0.25)
    selected_model_only = _resource_quality_bool(
        gate_cfg.get("selected_model_only", False),
        False,
    )
    workload_family = _resource_quality_workload_family(gate_cfg)
    io_hard_targets = set(
        _resource_quality_list(gate_cfg.get("io_hard_targets"), ["total"])
    )
    warning_test_relative_error_p95 = _resource_quality_float(
        gate_cfg.get("warning_test_relative_error_p95"),
        1.0,
    )
    warning_test_relative_error_max = _resource_quality_float(
        gate_cfg.get("warning_test_relative_error_max"),
        5.0,
    )
    enforce_test_relative_error_p95 = _resource_quality_bool(
        gate_cfg.get("enforce_test_relative_error_p95", False),
        False,
    )
    enforce_test_relative_error_max = _resource_quality_bool(
        gate_cfg.get("enforce_test_relative_error_max", False),
        False,
    )
    enforce_test_r2 = _resource_quality_bool(
        gate_cfg.get("enforce_test_r2", False),
        False,
    )
    fail_on_missing_metrics = _resource_quality_bool(
        gate_cfg.get("fail_on_missing_metrics", True),
        True,
    )
    fail_on_optional_resource = _resource_quality_bool(
        gate_cfg.get("fail_on_optional_resource", False),
        False,
    )
    runtime_selected_model_sets: Dict[str, str] = {}
    baseline_metadata = (
        baseline_estimation_metadata
        if isinstance(baseline_estimation_metadata, dict)
        else {}
    )
    resource_breakdown = baseline_metadata.get("resource_breakdown")
    if isinstance(resource_breakdown, dict):
        for resource_name in ("cpu", "io", "memory"):
            breakdown = resource_breakdown.get(resource_name)
            if not isinstance(breakdown, dict):
                continue
            calibration = breakdown.get("calibration_breakdown")
            if not isinstance(calibration, dict):
                continue
            learned = calibration.get("learned_model")
            if not isinstance(learned, dict):
                continue
            selected_model_set = str(learned.get("model_set") or "").strip()
            if selected_model_set:
                runtime_selected_model_sets[resource_name] = selected_model_set
    configured_model_sets = gate_cfg.get("runtime_selected_model_sets")
    if isinstance(configured_model_sets, dict):
        for resource_name in ("cpu", "io", "memory"):
            configured_model_set = str(
                configured_model_sets.get(resource_name) or ""
            ).strip()
            if configured_model_set:
                runtime_selected_model_sets.setdefault(
                    resource_name,
                    configured_model_set,
                )
    # RC#1b: Memory replay-calibration gate (override §311-354 item 1 + §8 #4).
    # Beyond point-prediction R2/relative_error, Memory models must also be
    # checked for DIRECTION-prediction reliability using historical real-replay
    # calibration evidence. v6 40 replays: 21 predicted Memory down but only 3
    # actual down → predicted-down-actual-up ratio ~85% → model is unreliable
    # for direction ranking. This gate accepts pre-computed calibration evidence
    # (caller loads prior-run replay results + model predictions and computes
    # the counts) so the gate stays decoupled from replay-data loading logic.
    memory_replay_calibration_cfg = (
        gate_cfg.get("memory_replay_calibration")
        if isinstance(gate_cfg.get("memory_replay_calibration"), dict)
        else {}
    )
    memory_replay_calibration_enabled = _resource_quality_bool(
        memory_replay_calibration_cfg.get("enabled", False),
        False,
    )
    memory_replay_calibration_hard_fail = _resource_quality_bool(
        memory_replay_calibration_cfg.get("hard_fail", False),
        False,
    )
    memory_replay_calibration_max_predicted_down_actual_up_ratio = (
        _resource_quality_float(
            memory_replay_calibration_cfg.get(
                "max_predicted_down_actual_up_ratio", 0.5
            ),
            0.5,
        )
    )
    memory_replay_calibration_min_predicted_down_count = (
        _resource_quality_int(
            memory_replay_calibration_cfg.get(
                "min_predicted_down_count", 5
            ),
            5,
        )
    )
    memory_replay_calibration_evidence = (
        memory_replay_calibration_cfg.get("evidence")
        if isinstance(
            memory_replay_calibration_cfg.get("evidence"), dict
        )
        else {}
    )

    summary: Dict[str, Any] = {
        "enabled": enabled,
        "passed": True,
        "required_resources": required_resources,
        "optional_resources": optional_resources,
        "thresholds": {
            "min_test_samples": min_test_samples,
            "max_test_relative_error_p95": max_test_relative_error_p95,
            "max_test_relative_error_max": max_test_relative_error_max,
            "min_test_r2": min_test_r2,
            "selected_model_only": selected_model_only,
            "workload_family": workload_family,
            "io_hard_targets": sorted(io_hard_targets),
            "warning_test_relative_error_p95": warning_test_relative_error_p95,
            "warning_test_relative_error_max": warning_test_relative_error_max,
            "enforce_test_relative_error_p95": enforce_test_relative_error_p95,
            "enforce_test_relative_error_max": enforce_test_relative_error_max,
            "enforce_test_r2": enforce_test_r2,
            "target_resource": str(gate_cfg.get("target_resource") or "")
            .strip()
            .lower(),
            "r2_fallback": copy.deepcopy(
                gate_cfg.get("r2_fallback")
                if isinstance(gate_cfg.get("r2_fallback"), dict)
                else {}
            ),
            "fail_on_missing_metrics": fail_on_missing_metrics,
            "fail_on_optional_resource": fail_on_optional_resource,
            "runtime_selected_model_sets": copy.deepcopy(
                runtime_selected_model_sets
            ),
            "memory_replay_calibration_enabled": memory_replay_calibration_enabled,
            "memory_replay_calibration_hard_fail": memory_replay_calibration_hard_fail,
            "memory_replay_calibration_max_predicted_down_actual_up_ratio": (
                memory_replay_calibration_max_predicted_down_actual_up_ratio
            ),
            "memory_replay_calibration_min_predicted_down_count": (
                memory_replay_calibration_min_predicted_down_count
            ),
        },
        "checks": [],
        "failures": [],
        "warnings": [],
        "skipped": [],
    }
    if not enabled:
        return summary

    resources = retrain_result.get("resources") if isinstance(retrain_result, dict) else {}
    if not isinstance(resources, dict):
        resources = {}
    seen: Set[str] = set()
    ordered_resources: List[str] = []
    for name in required_resources + optional_resources:
        if name not in seen:
            ordered_resources.append(name)
            seen.add(name)

    for resource_name in ordered_resources:
        resource_required = resource_name in required_resources
        enforce_resource = resource_required or fail_on_optional_resource
        resource_summary = resources.get(resource_name)
        if resource_summary is None:
            item = {
                "resource": resource_name,
                "reason": "missing_retrain_resource_summary",
                "required": resource_required,
            }
            if enforce_resource:
                summary["failures"].append(item)
            else:
                summary["skipped"].append(item)
            continue

        if resource_name == "memory":
            memory_status = str(resource_summary.get("status") or "").strip()
            memory_source = str(resource_summary.get("source") or "").strip()
            updated_model_sets = (
                resource_summary.get("updated_model_sets")
                if isinstance(resource_summary.get("updated_model_sets"), dict)
                else {}
            )
            selected_memory_model_set = str(
                resource_summary.get("selected_model_set") or ""
            ).strip()
            memory_failures: List[str] = []
            if memory_status != "retrained":
                memory_failures.append(f"status {memory_status!r} != 'retrained'")
            if not memory_source:
                memory_failures.append("missing memory retrain source")
            elif memory_source == "baseline_memory_single_sample_retrain":
                memory_failures.append(
                    "source 'baseline_memory_single_sample_retrain' is only a "
                    "single-sample calibration, not train/test retraining"
                )
            actual_memory_mb = _resource_quality_float(
                resource_summary.get("actual_memory_mb"),
                None,
            )
            if (
                memory_source == "baseline_memory_single_sample_retrain"
                and (actual_memory_mb is None or actual_memory_mb <= 0.0)
            ):
                memory_failures.append("missing positive actual_memory_mb")
            if not updated_model_sets:
                memory_failures.append("missing updated_model_sets")

            checked_model_sets = updated_model_sets
            if selected_model_only:
                if workload_family == "H" and "AP_only" in updated_model_sets:
                    expected_model_set = "AP_only"
                else:
                    expected_model_set = selected_memory_model_set
                    if not expected_model_set:
                        expected_model_set = "TP_Hybrid"
                selected_model = updated_model_sets.get(expected_model_set)
                if not isinstance(selected_model, dict):
                    memory_failures.append(
                        f"missing selected Memory model set {expected_model_set!r}"
                    )
                    checked_model_sets = {}
                else:
                    checked_model_sets = {expected_model_set: selected_model}

            for model_set, model_info in checked_model_sets.items():
                model_info = model_info if isinstance(model_info, dict) else {}
                metrics = model_info.get("metrics") if isinstance(model_info.get("metrics"), dict) else {}
                train_metrics = (
                    metrics.get("train")
                    if isinstance(metrics.get("train"), dict)
                    else {}
                )
                train_samples = _resource_quality_int(
                    train_metrics.get("sample_count", metrics.get("train_samples")),
                    0,
                )
                test_metrics = (
                    metrics.get("test")
                    if isinstance(metrics.get("test"), dict)
                    else {}
                )
                test_samples = _resource_quality_int(
                    test_metrics.get("sample_count", metrics.get("test_samples")),
                    0,
                )
                # RC#1 fix: Memory branch must check test R2 / relative_error just like
                # the CPU/IO branch below. Without this, an AP_only Memory model with
                # test r2=-10.8868 and relative_error_p95=0.3455 still passes the gate,
                # which is the root cause of v6 small_loop_ranking_gate_failed.
                rel_p95 = _resource_quality_float(
                    test_metrics.get("relative_error_p95"), None
                )
                rel_max = _resource_quality_float(
                    test_metrics.get("relative_error_max"), None
                )
                r2_value = _resource_quality_float(test_metrics.get("r2"), None)
                error_bound = (
                    model_info.get("error_bound")
                    if isinstance(model_info.get("error_bound"), dict)
                    else {}
                )
                error_bound_samples = _resource_quality_int(
                    error_bound.get("sample_count"),
                    0,
                )
                check = {
                    "resource": resource_name,
                    "model": f"updated_model_sets.{model_set}",
                    "required": resource_required,
                    "status": memory_status,
                    "source": memory_source,
                    "train_samples": train_samples,
                    "test_samples": test_samples,
                    "test_relative_error_p95": rel_p95,
                    "test_relative_error_max": rel_max,
                    "test_r2": r2_value,
                    "actual_memory_mb": actual_memory_mb,
                    "error_bound_sample_count": error_bound_samples,
                    "selected_model_set": selected_memory_model_set,
                }
                summary["checks"].append(check)
                record_failures: List[str] = []
                if train_samples < min_test_samples:
                    record_failures.append(
                        f"train_samples {train_samples} < min_test_samples {min_test_samples}"
                    )
                if test_samples < min_test_samples:
                    record_failures.append(
                        f"test_samples {test_samples} < min_test_samples {min_test_samples}"
                    )
                if error_bound_samples < 1:
                    record_failures.append("baseline error_bound sample_count < 1")
                if max_test_relative_error_p95 is not None and enforce_test_relative_error_p95:
                    if rel_p95 is None:
                        record_failures.append("missing test.relative_error_p95")
                    elif rel_p95 > max_test_relative_error_p95:
                        record_failures.append(
                            "test.relative_error_p95 "
                            f"{rel_p95:.6g} > {max_test_relative_error_p95:.6g}"
                        )
                if max_test_relative_error_max is not None and enforce_test_relative_error_max:
                    if rel_max is None:
                        record_failures.append("missing test.relative_error_max")
                    elif rel_max > max_test_relative_error_max:
                        record_failures.append(
                            "test.relative_error_max "
                            f"{rel_max:.6g} > {max_test_relative_error_max:.6g}"
                        )
                if min_test_r2 is not None and enforce_test_r2:
                    if r2_value is None:
                        record_failures.append("missing test.r2")
                    elif r2_value < min_test_r2:
                        fallback_policy = gate_cfg.get("r2_fallback")
                        if isinstance(fallback_policy, dict) and _resource_quality_bool(
                            fallback_policy.get("enabled", False), False
                        ):
                            fallback_decision = _role_aware_r2_fallback_decision(
                                resource_name=resource_name,
                                metrics=metrics,
                                test_metrics=test_metrics,
                                retrain_result=retrain_result,
                                gate_cfg=gate_cfg,
                            )
                            check["r2_fallback"] = fallback_decision
                            if fallback_decision.get("eligible") is not True:
                                record_failures.append(
                                    "test.r2 "
                                    f"{r2_value:.6g} < {min_test_r2:.6g}; "
                                    "role-aware fallback failed: "
                                    + "; ".join(fallback_decision.get("reasons") or [])
                                )
                        else:
                            r2_low_error_escape = (
                                r2_value >= -0.25
                                and rel_p95 is not None
                                and rel_max is not None
                                and rel_p95 <= 0.10
                                and rel_max <= 0.20
                                and test_samples >= min_test_samples
                            )
                            if r2_low_error_escape:
                                check["r2_low_error_escape"] = True
                            else:
                                record_failures.append(
                                    f"test.r2 {r2_value:.6g} < {min_test_r2:.6g}"
                                )
                record_warnings: List[str] = []
                if warning_test_relative_error_p95 is not None and rel_p95 is not None:
                    if rel_p95 > warning_test_relative_error_p95:
                        record_warnings.append(
                            "test.relative_error_p95 "
                            f"{rel_p95:.6g} > warning {warning_test_relative_error_p95:.6g}; "
                            "covered by robust-ranking residual error bounds"
                        )
                if warning_test_relative_error_max is not None and rel_max is not None:
                    if rel_max > warning_test_relative_error_max:
                        record_warnings.append(
                            "test.relative_error_max "
                            f"{rel_max:.6g} > warning {warning_test_relative_error_max:.6g}; "
                            "treated as tail-risk warning, not a hard gate"
                        )
                if check.get("r2_low_error_escape"):
                    record_warnings.append(
                        "test.r2 "
                        f"{r2_value:.6g} < {min_test_r2:.6g}, but Memory relative "
                        f"error is low (p95={rel_p95:.6g}, max={rel_max:.6g}); "
                        "treated as low-variance R2 warning, not a hard gate"
                    )
                if (
                    isinstance(check.get("r2_fallback"), dict)
                    and check["r2_fallback"].get("eligible") is True
                ):
                    record_warnings.append(
                        "test.r2 "
                        f"{r2_value:.6g} < {min_test_r2:.6g}; accepted only by "
                        f"campaign-scoped {check['r2_fallback'].get('role')} "
                        f"policy {check['r2_fallback'].get('policy_id')} with "
                        "bounded OOF level error; no direction-accuracy claim"
                    )
                if record_warnings:
                    warn_item = dict(check)
                    warn_item["warnings"] = record_warnings
                    summary["warnings"].append(warn_item)
                if record_failures:
                    item = dict(check)
                    item["reasons"] = record_failures
                    if enforce_resource:
                        summary["failures"].append(item)
                    else:
                        summary["skipped"].append(item)

            if memory_failures:
                item = {
                    "resource": resource_name,
                    "reason": "memory_baseline_retrain_incomplete",
                    "required": resource_required,
                    "status": memory_status,
                    "source": memory_source,
                    "reasons": memory_failures,
                }
                if enforce_resource:
                    summary["failures"].append(item)
                else:
                    summary["skipped"].append(item)
            # Memory replay-calibration evidence is a direction-risk signal for
            # robust ranking, not a permanent launch veto by default. v6 had 21
            # predicted-down but only 3 actual-down, which means raw Memory-down
            # predictions must be treated cautiously. Keep an explicit
            # hard_fail switch for strict audits, but normal Phase2 v7+ runs
            # should let the optimizer proceed with warnings/error bounds.
            #
            # Evidence dict shape:
            #   predicted_down_count: int   — candidates model predicted Memory down
            #   actual_down_count: int      — candidates with actual Memory down
            #   predicted_down_actual_up_count: int — predicted down but actual up
            #   source_run_id: str         — provenance of the calibration data
            if (
                memory_replay_calibration_enabled
                and resource_required
                and memory_replay_calibration_evidence
            ):
                ev = memory_replay_calibration_evidence
                predicted_down_count = _resource_quality_int(
                    ev.get("predicted_down_count"), 0
                )
                actual_down_count = _resource_quality_int(
                    ev.get("actual_down_count"), 0
                )
                predicted_down_actual_up_count = _resource_quality_int(
                    ev.get("predicted_down_actual_up_count"), 0
                )
                calibration_source = str(ev.get("source_run_id") or "").strip()
                ratio: Optional[float] = None
                if predicted_down_count > 0:
                    ratio = (
                        predicted_down_actual_up_count / predicted_down_count
                    )
                cal_check = {
                    "resource": resource_name,
                    "check": "memory_replay_calibration",
                    "required": resource_required,
                    "predicted_down_count": predicted_down_count,
                    "actual_down_count": actual_down_count,
                    "predicted_down_actual_up_count": (
                        predicted_down_actual_up_count
                    ),
                    "predicted_down_actual_up_ratio": ratio,
                    "max_allowed_ratio": (
                        memory_replay_calibration_max_predicted_down_actual_up_ratio
                    ),
                    "min_predicted_down_count": (
                        memory_replay_calibration_min_predicted_down_count
                    ),
                    "source_run_id": calibration_source,
                }
                summary["checks"].append(cal_check)
                cal_failures: List[str] = []
                if predicted_down_count < memory_replay_calibration_min_predicted_down_count:
                    cal_failures.append(
                        f"predicted_down_count {predicted_down_count} < "
                        f"min {memory_replay_calibration_min_predicted_down_count}"
                    )
                if (
                    ratio is not None
                    and ratio
                    > memory_replay_calibration_max_predicted_down_actual_up_ratio
                ):
                    cal_failures.append(
                        f"predicted_down_actual_up_ratio {ratio:.4f} > "
                        f"max {memory_replay_calibration_max_predicted_down_actual_up_ratio:.4f}"
                    )
                if cal_failures:
                    cal_item = dict(cal_check)
                    cal_item["reason"] = "memory_replay_calibration_failed"
                    cal_item["reasons"] = cal_failures
                    if enforce_resource and memory_replay_calibration_hard_fail:
                        summary["failures"].append(cal_item)
                    else:
                        warn_item = dict(cal_item)
                        warn_item["reason"] = "memory_replay_calibration_risk"
                        warn_item["warnings"] = [
                            f"{reason}; treated as robust-ranking direction-risk warning"
                            for reason in cal_failures
                        ]
                        summary["warnings"].append(warn_item)
            continue

        all_metric_records = _iter_resource_model_metrics(resource_summary)
        metric_records = all_metric_records
        if selected_model_only and resource_name in {"cpu", "io"}:
            metric_records = [
                record
                for record in all_metric_records
                if _resource_quality_selected_record(
                    resource_name=resource_name,
                    label=str(record.get("label") or ""),
                    workload_family=workload_family,
                    io_hard_targets=io_hard_targets,
                    runtime_selected_model_set=runtime_selected_model_sets.get(
                        resource_name,
                        "",
                    ),
                )
            ]
            skipped_count = max(0, len(all_metric_records) - len(metric_records))
            if skipped_count:
                summary["skipped"].append(
                    {
                        "resource": resource_name,
                        "reason": "not_runtime_selected_model_for_workload_family",
                        "workload_family": workload_family,
                        "runtime_selected_model_set": runtime_selected_model_sets.get(
                            resource_name,
                            "",
                        ),
                        "skipped_metric_records": skipped_count,
                    }
                )
        if not metric_records:
            item = {
                "resource": resource_name,
                "reason": (
                    "missing_selected_train_test_metrics"
                    if selected_model_only and resource_name in {"cpu", "io"}
                    else "missing_train_test_metrics"
                ),
                "required": resource_required,
                "workload_family": workload_family if resource_name in {"cpu", "io"} else None,
            }
            if enforce_resource and fail_on_missing_metrics:
                summary["failures"].append(item)
            else:
                summary["skipped"].append(item)
            continue

        for record in metric_records:
            metrics = record.get("metrics") or {}
            test_metrics = metrics.get("test") if isinstance(metrics.get("test"), dict) else {}
            test_samples = _resource_quality_int(
                test_metrics.get("sample_count", metrics.get("test_samples")),
                0,
            )
            rel_p95 = _resource_quality_float(test_metrics.get("relative_error_p95"), None)
            rel_max = _resource_quality_float(test_metrics.get("relative_error_max"), None)
            r2_value = _resource_quality_float(test_metrics.get("r2"), None)
            check = {
                "resource": resource_name,
                "model": record.get("label"),
                "required": resource_required,
                "test_samples": test_samples,
                "test_relative_error_p95": rel_p95,
                "test_relative_error_max": rel_max,
                "test_r2": r2_value,
            }
            summary["checks"].append(check)

            record_failures: List[str] = []
            if test_samples < min_test_samples:
                record_failures.append(
                    f"test_samples {test_samples} < min_test_samples {min_test_samples}"
                )
            if max_test_relative_error_p95 is not None and enforce_test_relative_error_p95:
                if rel_p95 is None:
                    record_failures.append("missing test.relative_error_p95")
                elif rel_p95 > max_test_relative_error_p95:
                    record_failures.append(
                        "test.relative_error_p95 "
                        f"{rel_p95:.6g} > {max_test_relative_error_p95:.6g}"
                    )
            if max_test_relative_error_max is not None and enforce_test_relative_error_max:
                if rel_max is None:
                    record_failures.append("missing test.relative_error_max")
                elif rel_max > max_test_relative_error_max:
                    record_failures.append(
                        "test.relative_error_max "
                        f"{rel_max:.6g} > {max_test_relative_error_max:.6g}"
                    )
            if min_test_r2 is not None and enforce_test_r2:
                if r2_value is None:
                    record_failures.append("missing test.r2")
                elif r2_value < min_test_r2:
                    fallback_decision = _role_aware_r2_fallback_decision(
                        resource_name=resource_name,
                        metrics=metrics,
                        test_metrics=test_metrics,
                        retrain_result=retrain_result,
                        gate_cfg=gate_cfg,
                    )
                    check["r2_fallback"] = fallback_decision
                    if fallback_decision.get("eligible") is not True:
                        record_failures.append(
                            "test.r2 "
                            f"{r2_value:.6g} < {min_test_r2:.6g}; "
                            "role-aware fallback failed: "
                            + "; ".join(fallback_decision.get("reasons") or [])
                        )
            record_warnings: List[str] = []
            if warning_test_relative_error_p95 is not None and rel_p95 is not None:
                if rel_p95 > warning_test_relative_error_p95:
                    record_warnings.append(
                        "test.relative_error_p95 "
                        f"{rel_p95:.6g} > warning {warning_test_relative_error_p95:.6g}; "
                        "covered by robust-ranking residual error bounds"
                    )
            if warning_test_relative_error_max is not None and rel_max is not None:
                if rel_max > warning_test_relative_error_max:
                    record_warnings.append(
                        "test.relative_error_max "
                        f"{rel_max:.6g} > warning {warning_test_relative_error_max:.6g}; "
                        "treated as tail-risk warning, not a hard gate"
                    )
            if (
                isinstance(check.get("r2_fallback"), dict)
                and check["r2_fallback"].get("eligible") is True
            ):
                record_warnings.append(
                    "test.r2 "
                    f"{r2_value:.6g} < {min_test_r2:.6g}; accepted only by "
                    f"campaign-scoped {check['r2_fallback'].get('role')} "
                    f"policy {check['r2_fallback'].get('policy_id')} with "
                    "bounded OOF level error; no direction-accuracy claim"
                )
            if record_warnings:
                item = dict(check)
                item["warnings"] = record_warnings
                summary["warnings"].append(item)

            if record_failures:
                item = dict(check)
                item["reasons"] = record_failures
                if enforce_resource:
                    summary["failures"].append(item)
                else:
                    summary["skipped"].append(item)

    summary["passed"] = not bool(summary["failures"])
    return summary


def validate_resource_model_baseline_sanity_gate(
    *,
    baseline_actual_normalized: Dict[str, float],
    baseline_estimated_normalized: Dict[str, float],
    baseline_estimation_metadata: Dict[str, Any],
    gate_cfg: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Validate current-workload baseline predictions before anchor calibration."""
    gate_cfg = gate_cfg if isinstance(gate_cfg, dict) else {}
    enabled = _resource_quality_bool(gate_cfg.get("enabled", False), False)
    required_resources = _resource_quality_list(
        gate_cfg.get("required_resources"),
        ["cpu", "io", "memory"],
    )
    max_relative_error = max(
        0.0,
        _resource_quality_float(gate_cfg.get("max_relative_error"), 1.0) or 1.0,
    )
    per_resource_limits = gate_cfg.get("max_relative_error_by_resource")
    if not isinstance(per_resource_limits, dict):
        per_resource_limits = {}
    signal_floor = max(
        1e-12,
        _resource_quality_float(gate_cfg.get("signal_floor"), 1e-9) or 1e-9,
    )
    allow_plan_formula_fallback = _resource_quality_bool(
        gate_cfg.get("allow_plan_formula_fallback", True),
        True,
    )
    anchor_scale_min_by_resource = gate_cfg.get("anchor_delta_scale_min_by_resource")
    if not isinstance(anchor_scale_min_by_resource, dict):
        anchor_scale_min_by_resource = {}
    anchor_scale_max_by_resource = gate_cfg.get("anchor_delta_scale_max_by_resource")
    if not isinstance(anchor_scale_max_by_resource, dict):
        anchor_scale_max_by_resource = {}
    summary: Dict[str, Any] = {
        "enabled": enabled,
        "passed": True,
        "required_resources": required_resources,
        "thresholds": {
            "max_relative_error": max_relative_error,
            "max_relative_error_by_resource": copy.deepcopy(per_resource_limits),
            "signal_floor": signal_floor,
            "allow_plan_formula_fallback": allow_plan_formula_fallback,
            "anchor_delta_scale_min_by_resource": copy.deepcopy(
                anchor_scale_min_by_resource
            ),
            "anchor_delta_scale_max_by_resource": copy.deepcopy(
                anchor_scale_max_by_resource
            ),
        },
        "checks": [],
        "failures": [],
    }
    if not enabled:
        return summary

    resource_breakdown = baseline_estimation_metadata.get("resource_breakdown")
    if not isinstance(resource_breakdown, dict):
        resource_breakdown = {}
    workload_context = (
        ((resource_breakdown.get("io") or {}).get("execution_breakdown") or {}).get(
            "workload_context"
        )
        or {}
    )
    prediction_window_seconds = _resource_quality_float(
        workload_context.get("feature_window_seconds")
        if isinstance(workload_context, dict)
        else None,
        5.0,
    ) or 5.0
    prediction_window_seconds = max(1e-9, prediction_window_seconds)

    def _plan_formula_fallback_prediction(
        resource_name: str,
        calibration: Dict[str, Any],
    ) -> Optional[float]:
        if resource_name == "cpu":
            value = _resource_quality_float(
                calibration.get("plan_formula_cpu_cores"),
                None,
            )
            if value is not None:
                return value
            total_cpu_seconds = _resource_quality_float(
                calibration.get("plan_formula_total_cpu_seconds"),
                None,
            )
            if total_cpu_seconds is None:
                return None
            return total_cpu_seconds / prediction_window_seconds
        if resource_name == "io":
            total_bytes = _resource_quality_float(
                calibration.get("total_io_bytes"),
                None,
            )
        elif resource_name == "io_read":
            total_bytes = _resource_quality_float(
                calibration.get("total_read_bytes"),
                None,
            )
        elif resource_name == "io_write":
            total_bytes = _resource_quality_float(
                calibration.get("total_write_bytes"),
                None,
            )
        else:
            return None
        if total_bytes is None:
            return None
        return (total_bytes / prediction_window_seconds) / (1024.0 ** 2)

    for resource_name in required_resources:
        actual = _resource_quality_float(
            baseline_actual_normalized.get(resource_name),
            None,
        )
        breakdown = resource_breakdown.get(resource_name)
        if not isinstance(breakdown, dict):
            breakdown = {}
        calibration = breakdown.get("calibration_breakdown")
        if not isinstance(calibration, dict):
            calibration = {}
        learned = calibration.get("learned_model")
        if not isinstance(learned, dict):
            learned = {}
        learned_fallback = calibration.get("learned_model_fallback")
        if not isinstance(learned_fallback, dict):
            learned_fallback = {}

        prediction_stage = str(
            gate_cfg.get("prediction_stage") or "after_baseline_anchor_before_error_bound"
        ).strip().lower()
        source = "learned_model_pre_anchor"
        raw_prediction: Optional[float]
        raw_pre_anchor_prediction: Optional[float] = None
        raw_pre_anchor_relative_error: Optional[float] = None
        if learned_fallback and allow_plan_formula_fallback:
            source = "plan_formula_fallback"
            raw_prediction = _resource_quality_float(
                baseline_estimated_normalized.get(resource_name),
                None,
            )
        elif learned:
            raw_pre_anchor_value = _resource_quality_float(
                learned.get("prediction_before_anchor_calibration"),
                None,
            )
            raw_model_value = _resource_quality_float(
                learned.get("prediction_before_error_bound"),
                None,
            )
            if raw_model_value is not None:
                source = "learned_model_after_baseline_anchor"
            else:
                raw_model_value = raw_pre_anchor_value
            model_window_seconds = _resource_quality_float(
                learned.get("prediction_window_seconds"),
                prediction_window_seconds,
            ) or prediction_window_seconds
            if raw_pre_anchor_value is None:
                raw_pre_anchor_prediction = None
            elif resource_name == "cpu":
                raw_pre_anchor_prediction = raw_pre_anchor_value / max(model_window_seconds, 1e-9)
            elif resource_name in {"io", "io_read", "io_write"}:
                raw_pre_anchor_prediction = raw_pre_anchor_value / max(model_window_seconds, 1e-9)
            elif resource_name == "memory":
                raw_pre_anchor_prediction = raw_pre_anchor_value / 1024.0
            else:
                raw_pre_anchor_prediction = raw_pre_anchor_value

            if raw_model_value is None:
                raw_prediction = None
            elif resource_name == "cpu":
                raw_prediction = raw_model_value / max(model_window_seconds, 1e-9)
            elif resource_name in {"io", "io_read", "io_write"}:
                raw_prediction = raw_model_value / max(model_window_seconds, 1e-9)
            elif resource_name == "memory":
                raw_prediction = raw_model_value / 1024.0
            else:
                raw_prediction = raw_model_value
        else:
            source = "missing_pre_anchor_prediction"
            raw_prediction = None

        limit = _resource_quality_float(
            per_resource_limits.get(resource_name),
            max_relative_error,
        )
        if limit is None:
            limit = max_relative_error
        reasons: List[str] = []
        if actual is None or not math.isfinite(actual) or actual <= signal_floor:
            reasons.append("actual_baseline_nonpositive_or_nonfinite")
        if raw_prediction is None or not math.isfinite(raw_prediction):
            reasons.append("raw_prediction_missing_or_nonfinite")
        elif raw_prediction <= signal_floor:
            reasons.append("raw_prediction_nonpositive_or_clip_to_zero")
        anchor = learned.get("baseline_anchor_calibration")
        anchor_scale: Optional[float] = None
        anchor_scale_min = _resource_quality_float(
            anchor_scale_min_by_resource.get(resource_name),
            None,
        )
        anchor_scale_max = _resource_quality_float(
            anchor_scale_max_by_resource.get(resource_name),
            None,
        )
        if source == "learned_model_after_baseline_anchor" and isinstance(anchor, dict) and anchor.get("applied"):
            anchor_scale = _resource_quality_float(
                anchor.get("unclamped_delta_scale", anchor.get("delta_scale")),
                None,
            )
            if anchor_scale is None or not math.isfinite(anchor_scale) or anchor_scale <= 0.0:
                reasons.append("baseline_anchor_delta_scale_nonpositive_or_nonfinite")
            else:
                if anchor_scale_min is not None and anchor_scale < anchor_scale_min:
                    reasons.append(
                        "baseline_anchor_delta_scale "
                        f"{anchor_scale:.6g} < {anchor_scale_min:.6g}"
                    )
                if anchor_scale_max is not None and anchor_scale > anchor_scale_max:
                    reasons.append(
                        "baseline_anchor_delta_scale "
                        f"{anchor_scale:.6g} > {anchor_scale_max:.6g}"
                    )

        relative_error: Optional[float] = None
        if (
            actual is not None
            and math.isfinite(actual)
            and actual > signal_floor
            and raw_pre_anchor_prediction is not None
            and math.isfinite(raw_pre_anchor_prediction)
        ):
            raw_pre_anchor_relative_error = abs(raw_pre_anchor_prediction - actual) / max(
                abs(actual),
                signal_floor,
            )

        if (
            actual is not None
            and math.isfinite(actual)
            and actual > signal_floor
            and raw_prediction is not None
            and math.isfinite(raw_prediction)
        ):
            relative_error = abs(raw_prediction - actual) / max(abs(actual), signal_floor)
            if relative_error > limit:
                reasons.append(
                    f"baseline_relative_error {relative_error:.6g} > {limit:.6g}"
                )
        fallback_prediction: Optional[float] = None
        fallback_relative_error: Optional[float] = None
        fallback_reasons: List[str] = []
        if reasons and allow_plan_formula_fallback and not learned_fallback:
            fallback_prediction = _plan_formula_fallback_prediction(
                resource_name,
                calibration,
            )
            if (
                fallback_prediction is None
                or not math.isfinite(fallback_prediction)
            ):
                fallback_reasons.append("plan_formula_fallback_missing_or_nonfinite")
            elif fallback_prediction <= signal_floor:
                fallback_reasons.append("plan_formula_fallback_nonpositive")
            if (
                actual is not None
                and math.isfinite(actual)
                and actual > signal_floor
                and fallback_prediction is not None
                and math.isfinite(fallback_prediction)
            ):
                fallback_relative_error = abs(fallback_prediction - actual) / max(
                    abs(actual),
                    signal_floor,
                )
                if fallback_relative_error > limit:
                    fallback_reasons.append(
                        "plan_formula_fallback_relative_error "
                        f"{fallback_relative_error:.6g} > {limit:.6g}"
                    )
            if not fallback_reasons:
                source = "plan_formula_fallback_after_failed_raw"
                raw_prediction = fallback_prediction
                relative_error = fallback_relative_error
                learned_fallback = {
                    "fallback_to_plan_formula": True,
                    "fallback_reason": (
                        "baseline_sanity_plan_formula_fallback_after_failed_raw"
                    ),
                }
                reasons = []

        check = {
            "resource": resource_name,
            "source": source,
            "actual_normalized": actual,
            "raw_prediction_normalized": raw_prediction,
            "relative_error": relative_error,
            "prediction_stage": prediction_stage,
            "raw_pre_anchor_prediction_normalized": raw_pre_anchor_prediction,
            "raw_pre_anchor_relative_error": raw_pre_anchor_relative_error,
            "baseline_anchor_calibration": learned.get("baseline_anchor_calibration"),
            "baseline_anchor_delta_scale": anchor_scale,
            "baseline_anchor_delta_scale_min": anchor_scale_min,
            "baseline_anchor_delta_scale_max": anchor_scale_max,
            "max_relative_error": limit,
            "learned_model_set": learned.get("model_set"),
            "learned_model_type": learned.get("model_type"),
            "fallback_reason": learned_fallback.get("fallback_reason"),
            "plan_formula_fallback_prediction": fallback_prediction,
            "plan_formula_fallback_relative_error": fallback_relative_error,
            "plan_formula_fallback_reasons": fallback_reasons,
            "formula_name": breakdown.get("formula_name"),
            "passed": not reasons,
            "reasons": reasons,
        }
        summary["checks"].append(check)
        if reasons:
            summary["failures"].append(copy.deepcopy(check))

    summary["passed"] = not bool(summary["failures"])
    return summary


def evaluate_baseline_resource_band_gate(
    *,
    utilization_pct: Dict[str, float],
    gate_cfg: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Validate the measured baseline against an explicit utilization band."""
    gate_cfg = gate_cfg if isinstance(gate_cfg, dict) else {}
    enabled = _resource_quality_bool(gate_cfg.get("enabled", False), False)
    hard_fail = _resource_quality_bool(gate_cfg.get("hard_fail", True), True)
    target_resource = str(gate_cfg.get("target_resource") or "").strip().lower()
    ranges_cfg = gate_cfg.get("ranges_pct")
    if not isinstance(ranges_cfg, dict):
        ranges_cfg = {}

    summary: Dict[str, Any] = {
        "enabled": enabled,
        "hard_fail": hard_fail,
        "target_resource": target_resource,
        "passed": True,
        "checks": [],
        "failures": [],
        "stage": "after_stable_baseline_before_retrain_and_candidate_search",
        "affects_outer_acceptance": False,
    }
    if not enabled:
        return summary

    for resource_name in ("cpu", "memory", "io"):
        bounds = ranges_cfg.get(resource_name)
        if not isinstance(bounds, dict):
            bounds = {}
        min_pct = _to_float_or_none(bounds.get("min_pct"))
        max_pct = _to_float_or_none(bounds.get("max_pct"))
        min_exclusive = _resource_quality_bool(
            bounds.get("min_exclusive", False),
            False,
        )
        max_exclusive = _resource_quality_bool(
            bounds.get("max_exclusive", False),
            False,
        )
        measured_pct = _to_float_or_none(utilization_pct.get(resource_name))
        valid_bounds = (
            (min_pct is not None or max_pct is not None)
            and (
                min_pct is None
                or max_pct is None
                or float(min_pct) <= float(max_pct)
            )
        )
        lower_passed = (
            min_pct is None
            or (
                measured_pct is not None
                and (
                    float(measured_pct) > float(min_pct)
                    if min_exclusive
                    else float(measured_pct) >= float(min_pct)
                )
            )
        )
        upper_passed = (
            max_pct is None
            or (
                measured_pct is not None
                and (
                    float(measured_pct) < float(max_pct)
                    if max_exclusive
                    else float(measured_pct) <= float(max_pct)
                )
            )
        )
        passed = bool(
            valid_bounds
            and measured_pct is not None
            and lower_passed
            and upper_passed
        )
        check = {
            "resource": resource_name,
            "role": "target" if resource_name == target_resource else "non_target",
            "metric_source": "utilization_pct",
            "metric_value": measured_pct,
            "required_min_pct": min_pct,
            "required_max_pct": max_pct,
            "min_exclusive": min_exclusive,
            "max_exclusive": max_exclusive,
            "valid_bounds": bool(valid_bounds),
            "passed": passed,
        }
        summary["checks"].append(check)
        if not passed:
            summary["failures"].append(copy.deepcopy(check))

    summary["passed"] = not bool(summary["failures"])
    return summary


@dataclass
class ParameterRange:
    """ParameterRange."""
    min_value: float
    max_value: float
    step: Optional[float] = None
    discrete_count: int = 10
    priority: int = 1
    values: Optional[List[float]] = None
    transform: str = ""

    def __post_init__(self):
        normalized_transform = str(self.transform or "").strip().lower()
        if normalized_transform not in {"", "linear", "log"}:
            raise ValueError(f": {self.transform!r}")
        if normalized_transform == "log" and self.min_value <= 0.0:
            raise ValueError("log  min_value  0")
        self.transform = normalized_transform
        if self.values is not None:
            deduped = sorted({float(value) for value in self.values})
            if len(deduped) >= 2:
                self.values = deduped
                self.discrete_count = len(deduped)
                return
            self.values = None


def clone_parameter_ranges(
    ranges: Dict[str, ParameterRange],
    active_params: Optional[List[str]] = None,
) -> Dict[str, ParameterRange]:
    """Clone parameter ranges, optionally keeping only active parameters."""
    active_set = set(active_params) if active_params else None
    cloned: Dict[str, ParameterRange] = {}
    for name, value in ranges.items():
        if active_set is not None and name not in active_set:
            continue
        cloned[name] = ParameterRange(
            min_value=float(value.min_value),
            max_value=float(value.max_value),
            step=float(value.step) if value.step is not None else None,
            discrete_count=int(value.discrete_count),
            priority=int(value.priority),
            values=list(value.values) if value.values is not None else None,
            transform=str(value.transform or ""),
        )
    return cloned


@dataclass
class OptimizationResult:
    """OptimizationResult."""
    optimized_params: Dict[str, float]
    initial_params: Dict[str, float]
    initial_resource: Dict[str, float]
    final_resource: Dict[str, float]
    initial_score: float
    final_score: float
    score_improvement: float
    score_improvement_pct: Optional[float]
    initial_utilization: Dict[str, float]
    final_utilization: Dict[str, float]
    initial_qps: Optional[float]
    final_qps: Optional[float]
    qps_improvement: Optional[float]
    qps_improvement_pct: Optional[float]
    initial_query_count: Optional[float]
    final_query_count: Optional[float]
    initial_query_time: Optional[float]
    final_query_time: Optional[float]
    degraded: Optional[bool]
    degradation_pct: Optional[float]
    iterations: int
    history: List[Dict]


class ParameterOptimizer:
    """ParameterOptimizer."""

    def __init__(
        self,
        resource_estimation_func: Callable,
        capability: Dict[str, float],
        reward_type: str = 'log',
        penalty_type: str = 'power',
        use_continuous: bool = False,
        continuous_type: str = 'gaussian',
        overload_threshold: float = 0.8,
        score_mode: str = 'threshold',
        resource_weights: Optional[Dict[str, float]] = None,
        resource_reward_weights: Optional[Dict[str, float]] = None,
        resource_penalty_weights: Optional[Dict[str, float]] = None,
        resource_target_ranges: Optional[Dict[str, Dict[str, Any]]] = None,
        verbose: bool = True
    ):
        """  init  ."""


        self.resource_estimation_func = resource_estimation_func
        self.capability = capability
        self.resource_target_ranges = copy.deepcopy(resource_target_ranges or {})
        self.verbose = verbose


        self.utility_calculator = ResourceUtilityCalculator(
            reward_type=reward_type,
            penalty_type=penalty_type,
            use_continuous=use_continuous,
            continuous_type=continuous_type,
            overload_threshold=overload_threshold,
            score_mode=score_mode,
            resource_weights=resource_weights,
            resource_reward_weights=resource_reward_weights,
            resource_penalty_weights=resource_penalty_weights,
            resource_target_ranges=resource_target_ranges,
        )


        self.history = []

    def discretize(self, param_range: ParameterRange) -> List[float]:
        """discretize."""


        if param_range.values:
            return [
                float(value)
                for value in param_range.values
                if (
                    float(param_range.min_value) - 1e-15
                    <= float(value)
                    <= float(param_range.max_value) + 1e-15
                )
            ]

        if param_range.step is not None and param_range.step > 0:
            min_value = float(param_range.min_value)
            max_value = float(param_range.max_value)
            step = float(param_range.step)
            values: List[float] = []
            current = min_value
            # Bound the loop so a bad tiny step cannot explode estimator-only search.
            max_points = max(2, min(10000, int(param_range.discrete_count) * 20))
            while current <= max_value + step * 1e-9 and len(values) < max_points:
                values.append(current)
                current += step
            if values and values[-1] < max_value - step * 1e-6 and len(values) < max_points:
                values.append(max_value)
            return values

        values = np.linspace(
            param_range.min_value,
            param_range.max_value,
            param_range.discrete_count
        )
        return values.tolist()

    def shrink_range(
        self,
        param_range: ParameterRange,
        best_value: float,
        shrink_factor: float = 0.5
    ) -> ParameterRange:
        """shrink range."""


        current_range = param_range.max_value - param_range.min_value
        new_range = current_range * shrink_factor


        new_min = max(
            param_range.min_value,
            best_value - new_range / 2
        )
        new_max = min(
            param_range.max_value,
            best_value + new_range / 2
        )


        min_range = (param_range.max_value - param_range.min_value) * 0.01
        if new_max - new_min < min_range:
            new_min = max(param_range.min_value, best_value - min_range / 2)
            new_max = min(param_range.max_value, best_value + min_range / 2)

        return ParameterRange(
            min_value=new_min,
            max_value=new_max,
            step=param_range.step,
            discrete_count=param_range.discrete_count,
            priority=param_range.priority
        )

    def is_improved(
        self,
        resource_old: Dict[str, float],
        resource_new: Dict[str, float]
    ) -> bool:
        """is improved."""


        return self.utility_calculator.is_improved(
            resource_old,
            resource_new,
            self.capability
        )

    def identify_bottleneck(
        self,
        resource: Dict[str, float]
    ) -> Dict[str, Any]:
        """identify bottleneck."""


        bottleneck_info = {
            'bottleneck_resources': [],
            'overload_resources': [],
            'underutilized_resources': [],
            'utilization': {}
        }

        for res_name in resource:
            if res_name not in self.capability:
                continue

            utilization = resource[res_name] / self.capability[res_name]
            bottleneck_info['utilization'][res_name] = utilization

            if utilization > 1.0:
                bottleneck_info['overload_resources'].append(res_name)
                bottleneck_info['bottleneck_resources'].append(res_name)
            elif utilization > 0.8:
                bottleneck_info['bottleneck_resources'].append(res_name)
            elif utilization < 0.3:
                bottleneck_info['underutilized_resources'].append(res_name)

        return bottleneck_info

    def optimize(
        self,
        p_real: Dict[str, float],
        p_candidate: Dict[str, float],
        param_ranges: Dict[str, ParameterRange],
        sql_set: Any,
        max_iter: int = 10,
        shrink_factor: float = 0.5,
        early_stop_threshold: int = 3,
        candidate_top_k: int = 1,
        candidate_gate: Optional[Dict[str, Any]] = None,
        candidate_pair_probe: Optional[Dict[str, Any]] = None,
        log_path: Optional[str] = None
    ) -> OptimizationResult:
        """optimize."""


        p_opt = copy.deepcopy(p_candidate)
        no_improve_cnt = 0
        self.history = []
        candidate_top_k = max(1, int(candidate_top_k))
        candidate_pool: List[Dict[str, Any]] = []
        candidate_rankings: List[Dict[str, Any]] = []
        candidate_seen: Set[Tuple[Tuple[str, float], ...]] = set()
        estimated_resource_cache: Dict[
            Tuple[Tuple[str, float], ...],
            Tuple[
                Dict[str, float],
                Optional[Dict[str, Dict[str, float]]],
                Optional[Tuple[float, float]],
                Optional[Dict[str, Any]],
            ],
        ] = {}
        active_param_names = list(param_ranges.keys())
        candidate_scope_ranges = clone_parameter_ranges(param_ranges)
        ranking_base_params = copy.deepcopy(p_real)
        ranking_base_resource: Dict[str, float] = {}
        candidate_gate_cfg = candidate_gate if isinstance(candidate_gate, dict) else {}
        candidate_adaptive_replay_controller_enabled = _to_bool(
            candidate_gate_cfg.get("adaptive_replay_controller_enabled", False),
            False,
        )
        real_delta_cfg = (
            candidate_gate_cfg.get("real_delta_calibration")
            if isinstance(candidate_gate_cfg.get("real_delta_calibration"), dict)
            else {}
        )
        real_delta_enabled = _to_bool(real_delta_cfg.get("enabled", False), False)
        real_delta_require_training_gate = _to_bool(
            real_delta_cfg.get("require_training_gate", True),
            True,
        )
        real_delta_require_prediction = _to_bool(
            real_delta_cfg.get("require_prediction", True),
            True,
        )
        real_delta_require_support = _to_bool(
            real_delta_cfg.get("require_support", True),
            True,
        )
        real_delta_unsupported_policy = str(
            real_delta_cfg.get("unsupported_policy", "keep_uncertain")
            or "keep_uncertain"
        ).strip().lower()
        if real_delta_unsupported_policy not in {"error", "keep_uncertain"}:
            raise ValueError(
                "real_delta_calibration.unsupported_policy must be error or "
                "keep_uncertain"
            )
        real_delta_uncertain_replay_min_count = max(
            0,
            int(real_delta_cfg.get("uncertain_replay_min_count", 0) or 0),
        )
        real_delta_min_plan_feature_coverage = min(
            1.0,
            max(
                0.0,
                float(real_delta_cfg.get("min_plan_feature_coverage", 0.80) or 0.80),
            ),
        )
        real_delta_artifact_path = str(real_delta_cfg.get("artifact_path") or "").strip()
        candidate_gate_baseline_resource_override_cfg = (
            candidate_gate_cfg.get("baseline_resource_override")
            if isinstance(candidate_gate_cfg.get("baseline_resource_override"), dict)
            else None
        )
        candidate_gate_baseline_resource_override: Dict[str, float] = {}
        if isinstance(candidate_gate_baseline_resource_override_cfg, dict):
            for _resource_name, _resource_value in candidate_gate_baseline_resource_override_cfg.items():
                _parsed_resource_value = _to_float_or_none(_resource_value)
                if _parsed_resource_value is not None:
                    candidate_gate_baseline_resource_override[str(_resource_name)] = float(
                        _parsed_resource_value
                    )
        candidate_gate_baseline_resource_override_source = str(
            candidate_gate_cfg.get("baseline_resource_override_source")
            or candidate_gate_cfg.get("baseline_resource_override_reason")
            or ""
        ).strip()
        candidate_gate_enabled = bool(candidate_gate_cfg.get("enabled", False))
        candidate_gate_allow_known_real_direction_seed_bypass = bool(
            candidate_gate_cfg.get("allow_known_real_direction_seed_gate_bypass", False)
        )
        candidate_gate_known_real_seed_min_interpolation_step = max(
            0.0,
            float(
                _to_float_or_none(
                    candidate_gate_cfg.get("known_real_seed_min_interpolation_step", 0.5)
                )
                or 0.0
            ),
        )
        candidate_gate_target_resource = str(
            candidate_gate_cfg.get("target_resource")
            or candidate_gate_cfg.get("bottleneck_resource")
            or ""
        )
        candidate_gate_require_bottleneck_decrease = bool(
            candidate_gate_cfg.get("require_predicted_bottleneck_decrease", True)
        )
        candidate_gate_require_passed_candidate = bool(
            candidate_gate_cfg.get("require_passed_candidate", candidate_gate_enabled)
        )
        candidate_gate_require_explainable_direction = bool(
            candidate_gate_cfg.get("require_explainable_direction", False)
        )
        if (
            _deprecated_phase2_env_overrides_enabled()
            and
            _to_bool(os.environ.get("BONECT_PHASE2_FORCE_DIRECTION_GATE", False), False)
            and candidate_gate_target_resource.strip().lower() in {"cpu", "memory", "io"}
        ):
            candidate_gate_enabled = True
            candidate_gate_require_bottleneck_decrease = True
