def example_resource_estimation(sql_set: Any, params: Dict[str, float]) -> Dict[str, float]:
    """example resource estimation."""


    cpu_usage = 2.0
    memory_usage = 4.0
    io_usage = 50.0


    if 'random_page_cost' in params:

        io_usage += (params['random_page_cost'] - 4.0) * 10


    if 'work_mem' in params:

        memory_usage += params['work_mem'] / 1024  # MB
        cpu_usage -= params['work_mem'] / 2048 * 0.5


    if 'shared_buffers' in params:
        memory_usage += params['shared_buffers'] / 1024


    if 'effective_cache_size' in params:
        cpu_usage -= params['effective_cache_size'] / 4096 * 0.3

    return {
        'cpu': max(0.1, cpu_usage),
        'memory': max(0.1, memory_usage),
        'io': max(0.1, io_usage)
    }


