if __name__ == "__main__":
    print("=" * 80)
    print("".center(80))
    print("=" * 80)

    config_path = os.environ.get("OPTIMIZER_CONFIG", "config/optimizer_config.json")
    cfg = load_optimizer_config(config_path)
    enforce_cost_param_scope(cfg)

    def _to_bool(value: Any, default: bool) -> bool:
        if value is None:
            return default
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return bool(value)
        if isinstance(value, str):
            v = value.strip().lower()
            if v in ("1", "true", "yes", "on"):
                return True
            if v in ("0", "false", "no", "off"):
                return False
        return default

    def _to_int(value: Any, default: int) -> int:
        try:
            if value in (None, ""):
                return default
            return int(float(value))
        except (TypeError, ValueError):
            return default

    def _section_value(section_name: str, key: str, default: Any = "") -> Any:
        section = cfg.get(section_name)
        if not isinstance(section, dict):
            return default
        return section.get(key, default)

    def _to_float(value: Any, default: float) -> float:
        try:
            if value in (None, ""):
                return default
            result = float(value)
            return result if math.isfinite(result) else default
        except (TypeError, ValueError):
            return default

    run_hint_parts = [
        config_path,
        str(_section_value("logging", "output_dir") or ""),
        str(_section_value("logging", "history_path") or ""),
        str(_section_value("benchmark", "name") or ""),
        str(_section_value("benchmark", "benchmark") or ""),
        str(_section_value("optimizer", "phase") or ""),
    ]
    phase2_run_hint = " ".join(run_hint_parts).lower()
    deprecated_phase2_env_overrides_enabled = _deprecated_phase2_env_overrides_enabled()
    phase2_auto_force_controls = False
    phase2_memory_ap_hint = (
        "phase2" in phase2_run_hint
        and "memory" in phase2_run_hint
        and "hybench_ap" in phase2_run_hint
    )
    phase2_force_direction_gate = deprecated_phase2_env_overrides_enabled and _to_bool(
        os.environ.get("BONECT_PHASE2_FORCE_DIRECTION_GATE"),
        False,
    )
    phase2_memory_ap_quality_memory_optional = deprecated_phase2_env_overrides_enabled and _to_bool(
        os.environ.get("BONECT_PHASE2_MEMORY_AP_QUALITY_MEMORY_OPTIONAL"),
        False,
    )
    if phase2_force_direction_gate:
        os.environ.setdefault("BONECT_PHASE2_FORCE_DIRECTION_GATE", "1")
    if phase2_memory_ap_quality_memory_optional:
        os.environ.setdefault("BONECT_PHASE2_MEMORY_AP_QUALITY_MEMORY_OPTIONAL", "1")

    optimizer_lock_enabled = _to_bool(
        os.environ.get("BONECT_OPTIMIZER_GLOBAL_LOCK"),
        True,
    )
    optimizer_lock_fp = None
    if optimizer_lock_enabled:
        lock_path = Path(
            os.environ.get(
                "BONECT_OPTIMIZER_LOCK_PATH",
                "/tmp/resource_adaptive_bonect_parameter_optimizer.lock",
            )
        )
        lock_path.parent.mkdir(parents=True, exist_ok=True)
        optimizer_lock_fp = lock_path.open("a+", encoding="utf-8")
        try:
            fcntl.flock(optimizer_lock_fp.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            optimizer_lock_fp.seek(0)
            owner = optimizer_lock_fp.read().strip()
            print(
                "[Bonect Guard] Another parameter_optimizer run already holds "
                f"{lock_path}; refuse to start before DB restart/baseline. owner={owner}",
                flush=True,
            )
            sys.exit(75)
        optimizer_lock_fp.seek(0)
        optimizer_lock_fp.truncate()
        optimizer_lock_fp.write(
            json.dumps(
                {
                    "pid": os.getpid(),
                    "config_path": config_path,
                    "started_at": datetime.now().isoformat(timespec="seconds"),
                    "phase2_auto_force_controls": phase2_auto_force_controls,
                    "phase2_memory_ap_hint": phase2_memory_ap_hint,
                },
                ensure_ascii=False,
            )
            + "\n"
        )
        optimizer_lock_fp.flush()

        def _release_optimizer_lock() -> None:
            try:
                fcntl.flock(optimizer_lock_fp.fileno(), fcntl.LOCK_UN)
                optimizer_lock_fp.close()
            except Exception:
                pass

        atexit.register(_release_optimizer_lock)

