    def _apply_param_value_overrides(
        target: Dict[str, float],
        overrides: Any,
        *,
        label: str,
    ) -> None:
        if not isinstance(overrides, dict):
            return
        for name, value in overrides.items():
            if name not in target:
                print(f"{label}: {name}", flush=True)
                continue
            try:
                target[name] = float(value)
            except (TypeError, ValueError):
                print(f"{label}: {name}={value}", flush=True)

    def _apply_param_range_overrides(
        target: Dict[str, ParameterRange],
        overrides: Any,
    ) -> None:
        if not isinstance(overrides, dict):
            return
        for name, value in overrides.items():
            if name not in target:
                print(f": {name}", flush=True)
                continue
            if not isinstance(value, dict):
                print(f"Configuration: {name}={value}", flush=True)
                continue
            old_range = target[name]
            try:
                min_value = float(value.get("min_value", old_range.min_value))
                max_value = float(value.get("max_value", old_range.max_value))
                discrete_count = int(value.get("discrete_count", old_range.discrete_count))
                priority = int(value.get("priority", old_range.priority))
                transform = resolve_parameter_transform(
                    name,
                    value.get("transform", old_range.transform),
                )
                step_raw = value.get("step", None)
                step = float(step_raw) if step_raw not in (None, "") else None
                explicit_values_raw = value.get("values")
                explicit_values: Optional[List[float]] = None
                if isinstance(explicit_values_raw, list):
                    explicit_values = [
                        float(item)
                        for item in explicit_values_raw
                    ]
            except (TypeError, ValueError):
                print(f": {name}={value}", flush=True)
                continue
            if min_value >= max_value:
                print(f": {name}=[{min_value}, {max_value}]", flush=True)
                continue
            target[name] = ParameterRange(
                min_value=min_value,
                max_value=max_value,
                step=step,
                discrete_count=max(2, discrete_count),
                priority=priority,
                values=explicit_values,
                transform=transform,
            )

