    def _psql_args(sql: str, *, dbname: str) -> List[str]:
        return [
            "psql",
            "-h",
            pg_host,
            "-p",
            str(pg_port),
            "-U",
            pg_user,
            "-d",
            dbname,
            "-v",
            "ON_ERROR_STOP=1",
            "-At",
            "-F",
            "\t",
            "-c",
            sql,
        ]

    def _psql_error_is_retryable(detail: str) -> bool:
        lowered = str(detail or "").lower()
        retryable_markers = (
            "no route to host",
            "connection refused",
            "could not connect to server",
            "server closed the connection unexpectedly",
            "the database system is starting up",
            "is the server running on that host",
        )
        return any(marker in lowered for marker in retryable_markers)

    def _psql_query(sql: str, *, dbname: str) -> str:
        env = os.environ.copy()
        if psql_statement_timeout_ms > 0:
            pgoptions = str(env.get("PGOPTIONS") or "").strip()
            timeout_opt = f"-c statement_timeout={psql_statement_timeout_ms}"
            env["PGOPTIONS"] = f"{pgoptions} {timeout_opt}".strip()
        max_attempts = max(1, psql_query_retry_count + 1)
        for attempt in range(1, max_attempts + 1):
            try:
                proc = subprocess.run(
                    _psql_args(sql, dbname=dbname),
                    check=False,
                    capture_output=True,
                    text=True,
                    timeout=psql_query_timeout_sec if psql_query_timeout_sec > 0 else None,
                    env=env,
                )
            except subprocess.TimeoutExpired as exc:
                raise RuntimeError(
                    f"psql query timed out after {psql_query_timeout_sec:.1f}s "
                    f"for db={dbname}. sql={sql!r}"
                ) from exc
            if proc.returncode == 0:
                return (proc.stdout or "").strip()
            stderr = (proc.stderr or "").strip()
            stdout = (proc.stdout or "").strip()
            detail = stderr or stdout or f"psql exited with code {proc.returncode}"
            if attempt < max_attempts and _psql_error_is_retryable(detail):
                time.sleep(psql_query_retry_sleep_sec)
                continue
            raise RuntimeError(
                f"psql query failed for db={dbname}. sql={sql!r}. detail={detail}"
            )
        raise RuntimeError(f"psql query failed for db={dbname}. sql={sql!r}.")

    def _safe_label(value: str) -> str:
        return re.sub(r"[^A-Za-z0-9_.-]+", "_", str(value or "")).strip("_") or "run"

    def _window_timestamp(ts: float) -> str:
        return time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(ts))

    def _parse_logged_timestamp(raw: str) -> Optional[float]:
        text = str(raw or "").strip()
        if not text:
            return None
        iso_text = re.sub(r"\s+([+-]\d{2}(?::?\d{2})?)$", r"\1", text)
        if re.search(r"[+-]\d{2}$", iso_text):
            iso_text = iso_text + ":00"
        try:
            return datetime.fromisoformat(iso_text).timestamp()
        except ValueError:
            pass
        for fmt in ("%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%d %H:%M:%S"):
            try:
                return time.mktime(time.strptime(text, fmt))
            except ValueError:
                continue
        return None

    auto_explain_state = {"configured": False}

    def _configure_auto_explain(tag: str) -> None:
        if not auto_explain_enabled or auto_explain_state["configured"]:
            return
        payload: Dict[str, Any] = {
            "event": "auto_explain_config",
            "tag": tag,
            "dbname": pg_stat_dbname,
            "settings": dict(auto_explain_settings),
            "postgres_logging": dict(auto_explain_pg_logging),
            "log_subdir": auto_explain_log_subdir,
        }
        try:
            preload = _psql_query("SHOW shared_preload_libraries;", dbname=pg_stat_dbname)
            payload["shared_preload_libraries"] = preload
            if "auto_explain" not in {
                item.strip() for item in preload.split(",") if item.strip()
            }:
                raise RuntimeError(
                    "shared_preload_libraries does not contain auto_explain; restart with auto_explain preloaded first"
                )
            restart_required = False
            current_logging_collector = _psql_query("SHOW logging_collector;", dbname=pg_stat_dbname)
            current_log_destination = _psql_query("SHOW log_destination;", dbname=pg_stat_dbname)
            current_log_directory = _psql_query("SHOW log_directory;", dbname=pg_stat_dbname)
            current_log_filename = _psql_query("SHOW log_filename;", dbname=pg_stat_dbname)
            payload["current_postgres_logging"] = {
                "logging_collector": current_logging_collector,
                "log_destination": current_log_destination,
                "log_directory": current_log_directory,
                "log_filename": current_log_filename,
            }
            if current_logging_collector.strip().lower() != auto_explain_pg_logging["logging_collector"]:
                _ = _psql_query(
                    f"ALTER SYSTEM SET logging_collector = '{auto_explain_pg_logging['logging_collector']}';",
                    dbname=pg_stat_dbname,
                )
                restart_required = True
            if current_log_destination.strip() != auto_explain_pg_logging["log_destination"]:
                _ = _psql_query(
                    f"ALTER SYSTEM SET log_destination = '{auto_explain_pg_logging['log_destination']}';",
                    dbname=pg_stat_dbname,
                )
            if current_log_directory.strip() != auto_explain_pg_logging["log_directory"]:
                _ = _psql_query(
                    f"ALTER SYSTEM SET log_directory = '{auto_explain_pg_logging['log_directory']}';",
                    dbname=pg_stat_dbname,
                )
                restart_required = True
            if current_log_filename.strip() != auto_explain_pg_logging["log_filename"]:
                _ = _psql_query(
                    f"ALTER SYSTEM SET log_filename = '{auto_explain_pg_logging['log_filename']}';",
                    dbname=pg_stat_dbname,
                )
            for name, value in auto_explain_settings.items():
                _ = _psql_query(
                    f"ALTER SYSTEM SET auto_explain.{name} = '{value}';",
                    dbname=pg_stat_dbname,
                )
            _ = _psql_query("SELECT pg_reload_conf();", dbname=pg_stat_dbname)
            if restart_required:
                _restart_db_container_after_benchmark("auto_explain_setup", force=True)
                _ = _psql_query("SELECT pg_reload_conf();", dbname=pg_stat_dbname)
            payload["restart_required"] = restart_required
            auto_explain_state["configured"] = True
            payload["success"] = True
        except Exception as exc:
            payload["success"] = False
            payload["error"] = str(exc)
            main_logger.log_struct(payload)
            if auto_explain_required:
                raise
            print(f"[WARN] Auto explain configuration failed ({tag}): {exc}", flush=True)
            return
        main_logger.log_struct(payload)

    def _set_auto_explain_collection_enabled(enabled: bool, tag: str) -> None:
        if not auto_explain_enabled:
            return
        payload: Dict[str, Any] = {
            "event": "auto_explain_toggle",
            "tag": tag,
            "enabled": bool(enabled),
            "dbname": pg_stat_dbname,
        }
        try:
            target_value = (
                str(auto_explain_settings.get("log_min_duration", "0"))
                if enabled
                else "-1"
            )
            _ = _psql_query(
                f"ALTER SYSTEM SET auto_explain.log_min_duration = '{target_value}';",
                dbname=pg_stat_dbname,
            )
            _ = _psql_query("SELECT pg_reload_conf();", dbname=pg_stat_dbname)
            payload["log_min_duration"] = target_value
            payload["success"] = True
        except Exception as exc:
            payload["success"] = False
            payload["error"] = str(exc)
            main_logger.log_struct(payload)
            if auto_explain_required:
                raise
            print(f"[WARN] Auto explain toggle failed ({tag}): {exc}", flush=True)
            return
        main_logger.log_struct(payload)

    def _collect_auto_explain_events(
        *,
        tag: str,
        start_ts: float,
        end_ts: float,
    ) -> Dict[str, Any]:
        if not auto_explain_enabled:
            return {
                "enabled": False,
                "collected": False,
                "reason": "auto_explain_disabled",
            }
        if not auto_explain_collect_logs:
            return {
                "enabled": True,
                "collected": False,
                "reason": "collect_logs_disabled",
            }

        artifact_root = os.path.join(
            auto_explain_output_dir,
            f"{_safe_label(tag)}_{time.strftime('%Y%m%d_%H%M%S', time.localtime(end_ts))}",
        )
        raw_dir = os.path.join(artifact_root, "raw")
        parsed_jsonl = os.path.join(artifact_root, "events.jsonl")
        summary_csv = os.path.join(artifact_root, "summary.csv")
        collect_script = os.path.join(
            os.path.dirname(__file__),
            "shell",
            "shell",
            "collect_auto_explain_logs.sh",
        )
        parse_script = os.path.join(
            os.path.dirname(__file__),
            "shell",
            "shell",
            "parse_auto_explain_logs.py",
        )
        os.makedirs(artifact_root, exist_ok=True)
        since_text = _window_timestamp(start_ts)
        until_text = _window_timestamp(end_ts)
        payload: Dict[str, Any] = {
            "enabled": True,
            "collected": False,
            "tag": tag,
            "container": auto_explain_db_container,
            "window": [start_ts, end_ts],
            "window_text": [since_text, until_text],
            "artifact_root": artifact_root,
        }
        try:
            collect_cmd = [
                "bash",
                collect_script,
                "--container",
                auto_explain_db_container,
                "--since",
                since_text,
                "--until",
                until_text,
                "--output-dir",
                raw_dir,
                "--log-subdir",
                auto_explain_log_subdir,
                "--pattern",
                auto_explain_collect_pattern,
            ]
            collect_proc = subprocess.run(
                collect_cmd,
                check=False,
                capture_output=True,
                text=True,
            )
            payload["collect_returncode"] = collect_proc.returncode
            payload["collect_stdout"] = (collect_proc.stdout or "").strip()
            payload["collect_stderr"] = (collect_proc.stderr or "").strip()
            if collect_proc.returncode != 0:
                raise RuntimeError(payload["collect_stderr"] or payload["collect_stdout"] or "collect_auto_explain_logs failed")

            parse_cmd = [
                sys.executable,
                parse_script,
                "--log-dir",
                raw_dir,
                "--output-jsonl",
                parsed_jsonl,
                "--output-summary-csv",
                summary_csv,
                "--pattern",
                auto_explain_parse_pattern,
            ]
            parse_proc = subprocess.run(
                parse_cmd,
                check=False,
                capture_output=True,
                text=True,
            )
            payload["parse_returncode"] = parse_proc.returncode
            payload["parse_stdout"] = (parse_proc.stdout or "").strip()
            payload["parse_stderr"] = (parse_proc.stderr or "").strip()
            if parse_proc.returncode != 0:
                raise RuntimeError(payload["parse_stderr"] or payload["parse_stdout"] or "parse_auto_explain_logs failed")

            event_count = 0
            distinct_fingerprints: Set[str] = set()
            distinct_queries: Set[str] = set()
            query_counts: Dict[str, int] = {}
            query_samples: Dict[str, str] = {}
            fingerprint_by_query: Dict[str, str] = {}
            first_ts: Optional[float] = None
            last_ts: Optional[float] = None
            if os.path.exists(parsed_jsonl):
                with open(parsed_jsonl, "r", encoding="utf-8") as fh:
                    for line in fh:
                        text = line.strip()
                        if not text:
                            continue
                        try:
                            row = json.loads(text)
                        except Exception:
                            continue
                        event_ts = _parse_logged_timestamp(str(row.get("timestamp") or ""))
                        if event_ts is None or event_ts < start_ts or event_ts > end_ts:
                            continue
                        event_count += 1
                        if first_ts is None or event_ts < first_ts:
                            first_ts = event_ts
                        if last_ts is None or event_ts > last_ts:
                            last_ts = event_ts
                        fp = str(row.get("query_fingerprint") or "").strip()
                        query_text = str(row.get("query_text") or "").strip()
                        if fp:
                            distinct_fingerprints.add(fp)
                        if query_text:
                            distinct_queries.add(query_text)
                            query_counts[query_text] = query_counts.get(query_text, 0) + 1
                            query_samples.setdefault(query_text, query_text)
                            if fp:
                                fingerprint_by_query.setdefault(query_text, fp)

            top_queries: List[Dict[str, Any]] = []
            replay_queries: List[Dict[str, Any]] = []
            for query_text, count in sorted(query_counts.items(), key=lambda item: item[1], reverse=True):
                replay_queries.append(
                    {
                        "query": query_text,
                        "calls": count,
                        "replay_count": count,
                        "query_fingerprint": fingerprint_by_query.get(query_text),
                    }
                )
            replay_queries_file = os.path.join(artifact_root, "replay_queries.json")
            with open(replay_queries_file, "w", encoding="utf-8") as fh:
                json.dump(replay_queries, fh, ensure_ascii=False, indent=2)

            for item in replay_queries[: max(0, auto_explain_log_topn)]:
                query_text = str(item.get("query") or "")
                count = int(item.get("replay_count") or 0)
                compact = query_samples.get(query_text, query_text).replace("\n", " ").strip()
                if len(compact) > 200:
                    compact = compact[:197] + "..."
                top_queries.append({"query": compact, "count": count})

            payload.update(
                {
                    "collected": True,
                    "raw_dir": raw_dir,
                    "parsed_jsonl": parsed_jsonl,
                    "summary_csv": summary_csv,
                    "sql_event_count": event_count,
                    "distinct_sql_fingerprint_count": len(distinct_fingerprints),
                    "distinct_sql_text_count": len(distinct_queries),
                    "top_sql_by_count": top_queries,
                    "replay_queries_file": replay_queries_file,
                    "replay_queries": replay_queries,
                    "filtered_event_window": [
                        _window_timestamp(first_ts) if first_ts is not None else None,
                        _window_timestamp(last_ts) if last_ts is not None else None,
                    ],
                }
            )
        except Exception as exc:
            payload["success"] = False
            payload["error"] = str(exc)
            main_logger.log_struct({"event": "auto_explain_collection", **payload})
            if auto_explain_required:
                raise
            print(f"[WARN] Auto explain collection failed ({tag}): {exc}", flush=True)
            return payload

        payload["success"] = True
        log_payload = {k: v for k, v in payload.items() if k != "replay_queries"}
        main_logger.log_struct({"event": "auto_explain_collection", **log_payload})
        return payload

    def _read_effective_params(
        params: Dict[str, float], *, dbname: str
    ) -> Dict[str, Dict[str, Any]]:
        effective: Dict[str, Dict[str, Any]] = {}
        for name, expected in params.items():
            try:
                raw = _psql_query(f"SHOW {name};", dbname=dbname)
                actual = float(raw.strip()) if raw.strip() else None
                effective[name] = {
                    "expected": float(expected),
                    "actual": actual,
                    "matched": actual is not None and abs(actual - float(expected)) <= 1e-12,
                }
            except Exception as exc:
                effective[name] = {
                    "expected": float(expected),
                    "actual": None,
                    "matched": False,
                    "error": str(exc),
                }
        return effective

    def _normalize_plan_structure(plan_obj: Any) -> Any:
        if isinstance(plan_obj, list):
            return [_normalize_plan_structure(item) for item in plan_obj]
        if not isinstance(plan_obj, dict):
            return plan_obj

        kept_fields = [
            "Node Type",
            "Join Type",
            "Relation Name",
            "Alias",
            "Index Name",
            "Index Cond",
            "Recheck Cond",
            "Filter",
            "Join Filter",
            "Hash Cond",
            "Merge Cond",
            "TID Cond",
            "Function Name",
            "Subplan Name",
            "Parent Relationship",
            "Strategy",
            "Operation",
            "Scan Direction",
            "Parallel Aware",
            "Async Capable",
            "Inner Unique",
            "Sort Key",
            "Group Key",
            "Grouping Sets",
            "Output",
            "CTE Name",
            "Workers Planned",
            "Plans",
        ]

        normalized: Dict[str, Any] = {}
        for key in kept_fields:
            if key not in plan_obj:
                continue
            value = plan_obj[key]
            if key == "Plans":
                normalized[key] = (
                    [_normalize_plan_structure(child) for child in value]
                    if isinstance(value, list)
                    else []
                )
            else:
                normalized[key] = _normalize_plan_structure(value)
        return normalized

    def _plan_fingerprint(plan_obj: Any) -> str:
        structural_plan = _normalize_plan_structure(plan_obj)
        canonical = json.dumps(structural_plan, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(canonical.encode("utf-8")).hexdigest()[:16]

    def _plan_detail_filename(label: str, queryid: Any, query_text: str) -> str:
        timestamp = time.strftime("%Y%m%d_%H%M%S")
        safe_label = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(label or "iteration")).strip("_")
        safe_queryid = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(queryid or "unknown")).strip("_")
        if not safe_queryid:
            safe_queryid = hashlib.sha256(query_text.encode("utf-8")).hexdigest()[:12]
        return f"{safe_label}_{timestamp}_queryid_{safe_queryid}.json"

    def _normalize_plan_query_text(query_text: Any) -> str:
        """Normalize SQL text for plan matching across pg_stat_statements queryid changes."""
        text = str(query_text or "").strip().rstrip(";").lower()
        return re.sub(r"\s+", " ", text)

    def _is_plannable_plan_query(query_text: Any) -> bool:
        """Return True for SQL statements that PostgreSQL EXPLAIN can plan."""
        normalized = _normalize_plan_query_text(query_text)
        if not normalized:
            return False
        if normalized.startswith("with "):
            return True
        return bool(re.match(r"^(select|insert|update|delete)\b", normalized))

    def _plan_query_key(item: Dict[str, Any]) -> str:
        # pg_stat_statements.queryid can change after reloads/restarts or between
        # generic/custom captures. The normalized SQL text is the stable identity
        # for comparing baseline/final plan captures.
        query_key = _normalize_plan_query_text(item.get("query"))
        if query_key:
            return f"query:{query_key}"
        queryid = item.get("queryid")
        if queryid not in (None, ""):
            return f"queryid:{queryid}"
        return "query:"

    def _quote_sql_literal(value: Any) -> str:
        if value is None:
            return "NULL"
        if isinstance(value, bool):
            return "TRUE" if value else "FALSE"
        if isinstance(value, (int, float)):
            return str(value)
        text_value = str(value)
        if text_value.upper() == "NULL":
            return "NULL"
        if re.fullmatch(r"[-+]?\d+(?:\.\d+)?", text_value):
            return text_value
        if text_value.startswith(("'", "DATE '", "TIMESTAMP '", "INTERVAL '")):
            return text_value
        return "'" + text_value.replace("'", "''") + "'"

    def _guess_custom_plan_param_values(queryid: str, query_text: str) -> Dict[int, str]:
        configured = plan_capture_custom_plan_params.get(queryid or "")
        if configured:
            return {
                idx + 1: _quote_sql_literal(value)
                for idx, value in enumerate(configured)
            }

        guessed: Dict[int, str] = {}
        for match in re.finditer(r"\$(\d+)", query_text):
            idx = int(match.group(1))
            guessed.setdefault(idx, "1")

        for idx in list(guessed.keys()):
            placeholder = rf"\${idx}\b"
            if re.search(rf"cast\(\s*{placeholder}\s+as\s+date\s*\)", query_text, flags=re.IGNORECASE):
                guessed[idx] = "DATE '2026-03-01'"
            elif re.search(
                rf"date\s*\([^)]*\)\s+between\s+{placeholder}\b",
                query_text,
                flags=re.IGNORECASE,
            ):
                guessed[idx] = "DATE '2026-03-01'"
            elif re.search(
                rf"cast\(\s*\$\d+\s+as\s+date\s*\)\s*\+\s*{placeholder}",
                query_text,
                flags=re.IGNORECASE,
            ):
                guessed[idx] = "1"
            elif re.search(rf"limit\s+{placeholder}", query_text, flags=re.IGNORECASE):
                guessed[idx] = "100"
            elif re.search(rf"\blike\s+{placeholder}", query_text, flags=re.IGNORECASE):
                guessed[idx] = "'%A%'"
            elif re.search(
                rf"\b(status|type|category|name)\s*=\s*{placeholder}",
                query_text,
                flags=re.IGNORECASE,
            ):
                guessed[idx] = "'A'"
            elif re.search(rf"\bin\s*\([^)]*{placeholder}", query_text, flags=re.IGNORECASE):
                guessed[idx] = "'A'"
            elif re.search(rf"[<>]=?\s*{placeholder}", query_text, flags=re.IGNORECASE):
                guessed[idx] = "1000"
        return guessed

    def _materialize_query_for_custom_plan(query_text: str, queryid: Any) -> str:
        values = _guess_custom_plan_param_values(str(queryid or ""), query_text)
        materialized = query_text
        for idx in sorted(values.keys(), reverse=True):
            materialized = re.sub(rf"\${idx}\b", values[idx], materialized)
        return materialized

    def _normalize_query_for_explain(query_text: str) -> str:
        # GENERIC_PLAN cannot infer the type of "$n" in expressions like "date + $n".
        return re.sub(
            r"(cast\(\$\d+\s+as\s+date\)\s*\+\s*)(\$\d+\b)",
            r"\1cast(\2 as integer)",
            query_text,
            flags=re.IGNORECASE,
        )

    def _build_explain_sql(query_text: str, *, mode: str, queryid: Any = None) -> Tuple[str, str]:
        has_params = bool(re.search(r"\$\d+\b", query_text))
        explain_mode = str(mode or "generic").strip().lower()
        if explain_mode == "generic":
            if not has_params:
                return (
                    "EXPLAIN (FORMAT JSON, COSTS true, VERBOSE false, BUFFERS false) " + query_text,
                    "generic",
                )
            return (
                "EXPLAIN (FORMAT JSON, GENERIC_PLAN true, COSTS true, VERBOSE false, BUFFERS false) "
                + query_text,
                "generic",
            )
        custom_query = _materialize_query_for_custom_plan(query_text, queryid) if has_params else query_text
        return (
            "EXPLAIN (FORMAT JSON, COSTS true, VERBOSE false, BUFFERS false) " + custom_query,
            explain_mode,
        )

    def _build_explain_attempts(query_text: str, *, mode: str, queryid: Any = None) -> List[Tuple[str, str]]:
        normalized_query = _normalize_query_for_explain(query_text)
        attempts: List[Tuple[str, str]] = []
        seen: Set[Tuple[str, str]] = set()
        if normalized_query != query_text:
            query_attempts = [
                (normalized_query, "_rewritten"),
                (query_text, ""),
            ]
        else:
            query_attempts = [(query_text, "")]
        for candidate_query, mode_suffix in query_attempts:
            explain_sql, explain_mode = _build_explain_sql(candidate_query, mode=mode, queryid=queryid)
            item = (explain_sql, explain_mode + mode_suffix)
            if item not in seen:
                attempts.append(item)
                seen.add(item)
        return attempts

    def _explain_query_json(query_text: str, *, dbname: str, mode: str, queryid: Any = None) -> Tuple[Any, str]:
        errors: List[str] = []
        for explain_sql, explain_mode in _build_explain_attempts(query_text, mode=mode, queryid=queryid):
            try:
                raw = _psql_query(explain_sql, dbname=dbname)
                return json.loads(raw), explain_mode
            except Exception as exc:
                errors.append(f"{explain_mode}: {exc}")
        raise RuntimeError(" ; ".join(errors))

    def _select_plan_queries(
        candidates: List[Dict[str, Any]],
        *,
        limit: int,
        coverage_pct: float,
        min_queries: int,
        changed_keys: Set[str],
        slow_mean_ms: float,
    ) -> List[Dict[str, Any]]:
        if not candidates:
            return []

        total_time_sum = sum(max(0.0, float(item.get("total_time_ms") or 0.0)) for item in candidates)
        effective_limit = max(0, int(limit))
        effective_min = max(0, min(int(min_queries), effective_limit))
        target_coverage = min(max(float(coverage_pct), 0.0), 1.0)

        selected: List[Dict[str, Any]] = []
        seen_keys: Set[str] = set()
        cumulative_total = 0.0

        for item in candidates:
            if len(selected) >= effective_limit:
                break
            key = _plan_query_key(item)
            if key in seen_keys:
                continue
            selected.append(item)
            seen_keys.add(key)
            cumulative_total += max(0.0, float(item.get("total_time_ms") or 0.0))
            coverage_now = 1.0 if total_time_sum <= 0 else cumulative_total / total_time_sum
            if len(selected) >= effective_min and coverage_now >= target_coverage:
                break

        for item in candidates:
            if len(selected) >= effective_limit:
                break
            key = _plan_query_key(item)
            mean_ms = float(item.get("mean_time_ms") or 0.0)
            if key in seen_keys:
                continue
            if key in changed_keys or mean_ms >= slow_mean_ms or _matches_plan_whitelist(item):
                selected.append(item)
                seen_keys.add(key)

        return selected

    def _merge_plan_query_candidates(*groups: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        merged: List[Dict[str, Any]] = []
        seen_keys: Set[str] = set()
        for group in groups:
            for item in group or []:
                key = _plan_query_key(item)
                if key in seen_keys:
                    continue
                merged.append(item)
                seen_keys.add(key)
        return merged

    def _matches_plan_whitelist(item: Dict[str, Any]) -> bool:
        queryid = str(item.get("queryid") or "").strip()
        query_text = str(item.get("query") or "")
        if queryid and queryid in plan_capture_whitelist_queryids:
            return True
        return any(pattern in query_text for pattern in plan_capture_whitelist_substrings)

    def _capture_plan_signatures(
        queries: List[Dict[str, Any]], *, dbname: str, limit: int = 10
    ) -> List[Dict[str, Any]]:
        plan_items: List[Dict[str, Any]] = []
        requested_modes = [mode for mode in plan_capture_modes if mode in ("generic", "custom")]
        if not requested_modes:
            requested_modes = ["generic"]
        for item in queries[: max(0, int(limit))]:
            query_text = str(item.get("query") or "").strip().rstrip(";")
            if not query_text:
                continue
            if not _is_plannable_plan_query(query_text):
                continue
            for requested_mode in requested_modes:
                try:
                    plan_json, explain_mode = _explain_query_json(
                        query_text,
                        dbname=dbname,
                        mode=requested_mode,
                        queryid=item.get("queryid"),
                    )
                    plan_doc = plan_json[0] if isinstance(plan_json, list) and plan_json else plan_json
                    plan_root = (
                        ((plan_doc or {}).get("Plan") or plan_doc)
                        if isinstance(plan_doc, dict)
                        else plan_doc
                    )
                    normalized_plan = _normalize_plan_structure(plan_root)
                    fingerprint = _plan_fingerprint(plan_root)
                    plan_items.append(
                        {
                            "queryid": item.get("queryid"),
                            "query": query_text,
                            "plan_hash": fingerprint,
                            "plan_mode": explain_mode,
                            "plan_summary": (
                                (plan_root or {}).get("Node Type")
                                if isinstance(plan_root, dict)
                                else None
                            ),
                            "normalized_plan": normalized_plan,
                            "raw_plan_json": plan_json,
                        }
                    )
                except Exception as exc:
                    plan_items.append(
                        {
                            "queryid": item.get("queryid"),
                            "query": query_text,
                            "plan_hash": None,
                            "plan_mode": requested_mode,
                            "error": str(exc),
                        }
                    )
                except KeyboardInterrupt as exc:
                    plan_items.append(
                        {
                            "queryid": item.get("queryid"),
                            "query": query_text,
                            "plan_hash": None,
                            "plan_mode": requested_mode,
                            "error": f"plan_capture_interrupted: {exc}",
                        }
                    )
                    continue
        return plan_items

    def _plan_log_view(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        view: List[Dict[str, Any]] = []
        for item in items:
            view.append(
                {
                    "queryid": item.get("queryid"),
                    "query": item.get("query"),
                    "plan_hash": item.get("plan_hash"),
                    "plan_mode": item.get("plan_mode"),
                    "plan_summary": item.get("plan_summary"),
                    "error": item.get("error"),
                }
            )
        return view

    def _dump_plan_capture(
        items: List[Dict[str, Any]], *, label: str, output_dir: str
    ) -> Optional[str]:
        if not items:
            return None
        os.makedirs(output_dir, exist_ok=True)
        file_path = os.path.join(
            output_dir,
            f"{re.sub(r'[^A-Za-z0-9_.-]+', '_', str(label or 'capture')).strip('_')}_{time.strftime('%Y%m%d_%H%M%S')}.json",
        )
        with open(file_path, "w", encoding="utf-8") as fh:
            json.dump(
                {
                    "label": label,
                    "captured_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                    "items": items,
                },
                fh,
                ensure_ascii=False,
                indent=2,
            )
        return file_path

    def _diff_plan_signatures(
        previous: List[Dict[str, Any]],
        current: List[Dict[str, Any]],
    ) -> List[Dict[str, Any]]:
        prev_map = {
            (_plan_query_key(item), str(item.get("plan_mode") or "generic")): item
            for item in previous
        }
        changes: List[Dict[str, Any]] = []
        for item in current:
            key = (_plan_query_key(item), str(item.get("plan_mode") or "generic"))
            prev = prev_map.get(key)
            if not prev:
                continue
            prev_hash = prev.get("plan_hash")
            curr_hash = item.get("plan_hash")
            prev_plan = prev.get("normalized_plan")
            curr_plan = item.get("normalized_plan")
            compare_mode = "hash"
            changed = prev_hash != curr_hash
            if prev_plan is not None and curr_plan is not None:
                compare_mode = "normalized_json"
                changed = prev_plan != curr_plan
            if not changed:
                continue
            changes.append(
                {
                    "queryid": item.get("queryid"),
                    "query": item.get("query"),
                    "plan_mode": item.get("plan_mode"),
                    "compare_mode": compare_mode,
                    "previous_plan_hash": prev_hash,
                    "current_plan_hash": curr_hash,
                    "previous_plan_summary": prev.get("plan_summary"),
                    "current_plan_summary": item.get("plan_summary"),
                    "previous_normalized_plan": prev_plan,
                    "current_normalized_plan": curr_plan,
                }
            )
        return changes

    def _dump_changed_plan_details(
        changes: List[Dict[str, Any]],
        *,
        dbname: str,
        label: str,
        output_dir: str = "history/plan_details",
    ) -> List[Dict[str, Any]]:
        dumped: List[Dict[str, Any]] = []
        if not changes:
            return dumped
        os.makedirs(output_dir, exist_ok=True)
        for item in changes:
            query_text = str(item.get("query") or "").strip().rstrip(";")
            if not query_text:
                continue
            try:
                filename = _plan_detail_filename(
                    label=label,
                    queryid=item.get("queryid"),
                    query_text=query_text,
                )
                file_path = os.path.join(output_dir, filename)
                with open(file_path, "w", encoding="utf-8") as fh:
                    json.dump(
                        {
                            "label": label,
                            "captured_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                            "queryid": item.get("queryid"),
                            "query": query_text,
                            "compare_mode": item.get("compare_mode"),
                            "previous_plan_hash": item.get("previous_plan_hash"),
                            "current_plan_hash": item.get("current_plan_hash"),
                            "previous_plan_summary": item.get("previous_plan_summary"),
                            "current_plan_summary": item.get("current_plan_summary"),
                            "previous_normalized_plan": item.get("previous_normalized_plan"),
                            "current_normalized_plan": item.get("current_normalized_plan"),
                        },
                        fh,
                        ensure_ascii=False,
                        indent=2,
                    )
                dumped.append(
                    {
                        "queryid": item.get("queryid"),
                        "query": query_text,
                        "file": file_path,
                        "compare_mode": item.get("compare_mode"),
                        "previous_plan_hash": item.get("previous_plan_hash"),
                        "current_plan_hash": item.get("current_plan_hash"),
                    }
                )
            except Exception as exc:
                dumped.append(
                    {
                        "queryid": item.get("queryid"),
                        "query": query_text,
                        "error": str(exc),
                    }
                )
        return dumped

    def _print_plan_changes(changes: List[Dict[str, Any]], limit: int = 10) -> None:
        lines = []
        lines.append("=" * 90)
        lines.append("  Iteration Plan Changes")
        lines.append("=" * 90)
        if not changes:
            lines.append("  (no plan hash changes compared with previous iteration)")
        else:
            grouped: Dict[str, List[Dict[str, Any]]] = {}
            for item in changes:
                mode = str(item.get("plan_mode") or "generic")
                grouped.setdefault(mode, []).append(item)
            for mode in sorted(grouped.keys()):
                lines.append(f"  [{mode}]")
                mode_items = grouped[mode][: max(0, int(limit))]
                for idx, item in enumerate(mode_items, start=1):
                    query = str(item.get("query") or "").strip().replace("\n", " ")
                    if len(query) > 80:
                        query = query[:77] + "..."
                    lines.append(
                        f"  {idx}. {item.get('previous_plan_summary')} -> {item.get('current_plan_summary')} "
                        f"| {item.get('previous_plan_hash')} -> {item.get('current_plan_hash')}"
                    )
                    lines.append(f"     {query}")
        lines.append("=" * 90)
        print("\n" + "\n".join(lines) + "\n")

    def _read_total_statement_calls(dbname: str) -> Optional[int]:
        sql = (
            "SELECT COALESCE(SUM(calls), 0) "
            "FROM pg_stat_statements "
            "WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database());"
        )
        try:
            raw = _psql_query(sql, dbname=dbname)
            if not raw:
                return None
            return int(float(raw))
        except Exception:
            return None

