    def _tag_matches_configured(configured_tags: Set[str], tag: str) -> bool:
        """Match exact tags plus feedback final validation tags."""
        normalized_tag = str(tag or "").strip().lower()
        normalized_tags = {str(item).strip().lower() for item in configured_tags}
        if normalized_tag in normalized_tags:
            return True
        if normalized_tag.startswith("feedbackfinal"):
            return "feedback" in normalized_tags or "final" in normalized_tags
        return False

    def _run_pre_benchmark_snapshot_restore(tag: str) -> None:
        if (
            not recovery_snapshot_enabled
            or not _tag_matches_configured(recovery_snapshot_tags, tag)
            or (recovery_snapshot_only_for_tp and not hybench_workload_has_tp)
        ):
            return

        if not recovery_snapshot_command:
            detail = (
                "pre-benchmark snapshot restore is enabled for TP/XP/HTAP workloads, "
                "but pre_benchmark_recovery.snapshot_restore.command is empty"
            )
            main_logger.log_struct(
                {
                    "event": "pre_benchmark_snapshot_restore",
                    "tag": tag,
                    "mode": hybench_workload_mode,
                    "success": False,
                    "error": detail,
                }
            )
            if recovery_snapshot_required:
                raise RuntimeError(detail)
            print(f"[WARN] {detail}", flush=True)
            return

        format_values = {
            "tag": tag,
            "mode": hybench_workload_mode,
            "dbname": recovery_target_db,
        }
        try:
            command = recovery_snapshot_command.format(**format_values)
        except Exception:
            command = recovery_snapshot_command

        if recovery_snapshot_runner == "ssh":
            run_cmd = [
                "ssh",
                "-o", "BatchMode=yes",
                "-o", f"ConnectTimeout={max(1, int(vm_rt_connect_timeout))}",
                "-p", str(int(recovery_snapshot_ssh_port)),
            ]
            if recovery_snapshot_ssh_identity_file:
                run_cmd.extend(["-i", recovery_snapshot_ssh_identity_file])
            run_cmd.extend([
                recovery_snapshot_ssh_target or vm_rt_ssh_target or vm_rt_host,
                f"bash -lc {shlex.quote(command)}",
            ])
            shell_flag = False
        else:
            run_cmd = command
            shell_flag = True

        stream_logs = _to_bool(
            os.environ.get("PRE_BENCHMARK_RECOVERY_STREAM_LOGS", True),
            True,
        )
        if stream_logs:
            proc = subprocess.run(
                run_cmd,
                shell=shell_flag,
                check=False,
                timeout=max(1.0, recovery_snapshot_timeout_sec),
            )
        else:
            proc = subprocess.run(
                run_cmd,
                shell=shell_flag,
                check=False,
                capture_output=True,
                text=True,
                timeout=max(1.0, recovery_snapshot_timeout_sec),
            )
        if proc.returncode == 0:
            main_logger.log_struct(
                {
                    "event": "pre_benchmark_snapshot_restore",
                    "tag": tag,
                    "mode": hybench_workload_mode,
                    "runner": recovery_snapshot_runner,
                    "command": command,
                    "success": True,
                }
            )
            return

        if stream_logs:
            detail = f"exit_code={proc.returncode}"
        else:
            detail = (
                (proc.stderr or "").strip()
                or (proc.stdout or "").strip()
                or f"exit_code={proc.returncode}"
            )
        main_logger.log_struct(
            {
                "event": "pre_benchmark_snapshot_restore",
                "tag": tag,
                "mode": hybench_workload_mode,
                "runner": recovery_snapshot_runner,
                "command": command,
                "success": False,
                "error": detail,
            }
        )
        if recovery_snapshot_required:
            raise RuntimeError(f"pre-benchmark snapshot restore failed: {detail}")
        print(f"[WARN] Pre-benchmark snapshot restore failed ({tag}): {detail}", flush=True)

    def _read_pg_noise_snapshot(dbname: str) -> Dict[str, Any]:
        snapshot: Dict[str, Any] = {}

        def _query_float_map(sql: str, fields: List[str]) -> Dict[str, float]:
            raw = _psql_query(sql, dbname=dbname)
            parts = (raw or "").strip().split("|")
            result: Dict[str, float] = {}
            for field, value in zip(fields, parts):
                try:
                    result[field] = float(value or 0.0)
                except Exception:
                    result[field] = 0.0
            return result

        try:
            snapshot["bgwriter"] = _query_float_map(
                "SELECT checkpoints_timed, checkpoints_req, buffers_checkpoint, buffers_backend "
                "FROM pg_stat_bgwriter;",
                [
                    "checkpoints_timed",
                    "checkpoints_req",
                    "buffers_checkpoint",
                    "buffers_backend",
                ],
            )
        except Exception as exc:
            snapshot["bgwriter_error"] = str(exc)

        try:
            snapshot["wal"] = _query_float_map(
                "SELECT wal_bytes FROM pg_stat_wal;",
                ["wal_bytes"],
            )
        except Exception as exc:
            snapshot["wal_error"] = str(exc)

        try:
            snapshot["database"] = _query_float_map(
                "SELECT xact_commit, xact_rollback "
                "FROM pg_stat_database WHERE datname = current_database();",
                ["xact_commit", "xact_rollback"],
            )
        except Exception as exc:
            snapshot["database_error"] = str(exc)

        try:
            wait_raw = _psql_query(
                "SELECT coalesce(wait_event_type, 'none'), coalesce(wait_event, 'none'), count(*) "
                "FROM pg_stat_activity "
                "WHERE datname = current_database() "
                "GROUP BY 1, 2 ORDER BY 3 DESC, 1, 2;",
                dbname=dbname,
            )
            wait_events: List[Dict[str, Any]] = []
            for line in (wait_raw or "").splitlines():
                parts = line.strip().split("|")
                if len(parts) != 3:
                    continue
                try:
                    count = int(float(parts[2] or 0))
                except Exception:
                    count = 0
                wait_events.append(
                    {
                        "wait_event_type": parts[0],
                        "wait_event": parts[1],
                        "count": count,
                    }
                )
            snapshot["wait_events"] = wait_events
        except Exception as exc:
            snapshot["wait_events_error"] = str(exc)

        return snapshot

    def _delta_numeric_dict(before: Dict[str, Any], after: Dict[str, Any]) -> Dict[str, float]:
        keys = set(before.keys()) | set(after.keys())
        delta: Dict[str, float] = {}
        for key in keys:
            try:
                delta[key] = float(after.get(key, 0.0) or 0.0) - float(before.get(key, 0.0) or 0.0)
            except Exception:
                continue
        return delta

    def _build_pg_noise_delta(before: Dict[str, Any], after: Dict[str, Any]) -> Dict[str, Any]:
        return {
            "before": before,
            "after": after,
            "delta": {
                "bgwriter": _delta_numeric_dict(
                    before.get("bgwriter") or {},
                    after.get("bgwriter") or {},
                ),
                "wal": _delta_numeric_dict(
                    before.get("wal") or {},
                    after.get("wal") or {},
                ),
                "database": _delta_numeric_dict(
                    before.get("database") or {},
                    after.get("database") or {},
                ),
            },
            "wait_events_after": after.get("wait_events") or [],
        }

    def _is_noisy_candidate_run(
        label: str,
        resource_avg: Dict[str, float],
        pg_noise: Dict[str, Any],
    ) -> Tuple[bool, List[str]]:
        if not noise_guard_enabled or not str(label).startswith("iter_"):
            return False, []
        io_cap = float(capability.get("io", 0.0) or 0.0)
        io_value = float(resource_avg.get("io", 0.0) or 0.0)
        io_util = io_value / io_cap if io_cap > 0 else 0.0
        if io_util < noise_guard_io_util_threshold:
            return False, []

        delta = pg_noise.get("delta") or {}
        bgwriter_delta = delta.get("bgwriter") or {}
        wal_delta = delta.get("wal") or {}
        reasons: List[str] = []
        wal_bytes = float(wal_delta.get("wal_bytes", 0.0) or 0.0)
        buffers_checkpoint = float(bgwriter_delta.get("buffers_checkpoint", 0.0) or 0.0)
        buffers_backend = float(bgwriter_delta.get("buffers_backend", 0.0) or 0.0)
        if wal_bytes >= noise_guard_wal_bytes_threshold:
            reasons.append(
                f"wal_bytes_delta={wal_bytes:.0f} >= {noise_guard_wal_bytes_threshold:.0f}"
            )
        if buffers_checkpoint >= noise_guard_buffers_checkpoint_threshold:
            reasons.append(
                "buffers_checkpoint_delta="
                f"{buffers_checkpoint:.0f} >= {noise_guard_buffers_checkpoint_threshold:.0f}"
            )
        if buffers_backend >= noise_guard_buffers_backend_threshold:
            reasons.append(
                f"buffers_backend_delta={buffers_backend:.0f} >= {noise_guard_buffers_backend_threshold:.0f}"
            )

        wait_events = pg_noise.get("wait_events_after") or []
        notable_waits = [
            item for item in wait_events
            if int(item.get("count") or 0) >= noise_guard_wait_event_min_count
            and str(item.get("wait_event_type") or "").lower() in {"io", "lwlock"}
        ]
        if notable_waits:
            reasons.append(f"notable_wait_events={notable_waits[:5]}")

        return bool(reasons), reasons

    def _run_pre_benchmark_vm_drop_cache(tag: str) -> None:
        if (
            metrics_source != "vm-runtime"
            and final_eval_runtime_source != "vm-runtime"
        ):
            return
        if (
            not recovery_vm_drop_cache_enabled
            or not _tag_matches_configured(recovery_vm_drop_cache_tags, tag)
        ):
            return
        ssh_cmd = [
            "ssh",
            "-o", "BatchMode=yes",
            "-o", f"ConnectTimeout={max(1, int(vm_rt_connect_timeout))}",
            "-p", str(int(recovery_vm_drop_cache_ssh_port)),
        ]
        if recovery_vm_drop_cache_ssh_identity_file:
            ssh_cmd.extend(["-i", recovery_vm_drop_cache_ssh_identity_file])
        ssh_cmd.extend([
            recovery_vm_drop_cache_ssh_target or vm_rt_ssh_target or vm_rt_host,
            f"bash -lc {shlex.quote(recovery_vm_drop_cache_cmd)}",
        ])
        proc = subprocess.run(
            ssh_cmd,
            check=False,
            capture_output=True,
            text=True,
        )
        if proc.returncode == 0:
            main_logger.log_struct(
                {
                    "event": "pre_benchmark_vm_drop_cache",
                    "tag": tag,
                    "ssh_target": recovery_vm_drop_cache_ssh_target or vm_rt_ssh_target or vm_rt_host,
                    "command": recovery_vm_drop_cache_cmd,
                    "success": True,
                }
            )
            return
        detail = (
            (proc.stderr or "").strip()
            or (proc.stdout or "").strip()
            or f"exit_code={proc.returncode}"
        )
        main_logger.log_struct(
            {
                "event": "pre_benchmark_vm_drop_cache",
                "tag": tag,
                "ssh_target": recovery_vm_drop_cache_ssh_target or vm_rt_ssh_target or vm_rt_host,
                "command": recovery_vm_drop_cache_cmd,
                "success": False,
                "error": detail,
            }
        )
        if recovery_vm_drop_cache_required:
            raise RuntimeError(f"pre-benchmark vm drop cache failed: {detail}")
        print(f"[WARN] Pre-benchmark VM drop cache failed ({tag}): {detail}", flush=True)

    def _run_pre_benchmark_recovery(tag: str) -> None:
        if tag == "baseline" and startup_recovery_state["completed"]:
            main_logger.log_struct(
                {
                    "event": "pre_benchmark_recovery",
                    "tag": tag,
                    "dbname": recovery_target_db,
                    "success": True,
                    "skipped": True,
                    "reason": "startup_recovery_already_completed",
                    "source_tag": startup_recovery_state["source_tag"],
                }
            )
            print(
                "[INFO] Skip baseline pre-benchmark recovery because startup recovery already rebuilt the database.",
                flush=True,
            )
            return
        _run_pre_benchmark_snapshot_restore(tag)
        if pre_benchmark_recovery_enabled and recovery_sql_list:
            try:
                for sql in recovery_sql_list:
                    _ = _psql_query(sql, dbname=recovery_target_db)
                main_logger.log_struct(
                    {
                        "event": "pre_benchmark_recovery",
                        "tag": tag,
                        "dbname": recovery_target_db,
                        "sql_count": len(recovery_sql_list),
                        "success": True,
                    }
                )
            except Exception as exc:
                main_logger.log_struct(
                    {
                        "event": "pre_benchmark_recovery",
                        "tag": tag,
                        "dbname": recovery_target_db,
                        "sql_count": len(recovery_sql_list),
                        "success": False,
                        "error": str(exc),
                    }
                )
                if recovery_required:
                    raise
                print(f"[WARN] Pre-benchmark recovery failed ({tag}): {exc}")
        if (
            recovery_restart_db_enabled
            and _tag_matches_configured(recovery_restart_db_tags, tag)
        ):
            _restart_db_container_after_benchmark(tag, force=True)
        _run_pre_benchmark_vm_drop_cache(tag)

    post_benchmark_cleanup_enabled = _to_bool(
        os.environ.get("POST_BENCHMARK_CLEANUP", cleanup_cfg.get("enabled")),
        True,
    )
    post_benchmark_sql = str(
        os.environ.get("POST_BENCHMARK_SQL", cleanup_cfg.get("sql", "DISCARD ALL;"))
    ).strip()
    post_benchmark_terminate_idle = _to_bool(
        os.environ.get(
            "POST_BENCHMARK_TERMINATE_IDLE",
            cleanup_cfg.get("terminate_idle", False),
        ),
        False,
    )
    cleanup_target_user = str(
        os.environ.get(
            "POST_BENCHMARK_TARGET_USER",
            cleanup_cfg.get("target_user", pg_user),
        )
    )
    cleanup_target_db = str(
        os.environ.get(
            "POST_BENCHMARK_TARGET_DB",
            cleanup_cfg.get("target_db", pg_stat_dbname),
        )
    )
    cleanup_target_app = str(
        os.environ.get(
            "POST_BENCHMARK_TARGET_APP",
            cleanup_cfg.get("target_app", ""),
        )
    ).strip()
    post_benchmark_restart_db = _to_bool(
        os.environ.get(
            "POST_BENCHMARK_RESTART_DB",
            cleanup_cfg.get("restart_db", True),
        ),
        True,
    )
    post_benchmark_restart_required = _to_bool(
        os.environ.get(
            "POST_BENCHMARK_RESTART_REQUIRED",
            cleanup_cfg.get("restart_required", True),
        ),
        True,
    )
    post_benchmark_db_container = str(
        os.environ.get(
            "POST_BENCHMARK_DB_CONTAINER",
            cleanup_cfg.get("db_container", "pg-master"),
        )
    ).strip()
    post_benchmark_restart_container_first = _to_bool(
        os.environ.get(
            "POST_BENCHMARK_RESTART_CONTAINER_FIRST",
            cleanup_cfg.get("restart_container_first", False),
        ),
        False,
    )
    post_benchmark_vm_restart_cmd = str(
        os.environ.get(
            "POST_BENCHMARK_VM_RESTART_CMD",
            cleanup_cfg.get(
                "vm_restart_cmd",
                "/usr/lib/postgresql/17/bin/pg_ctl -D /var/lib/postgresql/17/main -m fast restart",
            ),
        )
    ).strip()
    post_benchmark_vm_restart_ssh_target = str(
        os.environ.get(
            "POST_BENCHMARK_VM_RESTART_SSH_TARGET",
            cleanup_cfg.get("vm_restart_ssh_target", vm_rt_ssh_target or vm_rt_host),
        )
    ).strip()
    post_benchmark_vm_restart_ssh_port = int(
        os.environ.get(
            "POST_BENCHMARK_VM_RESTART_SSH_PORT",
            cleanup_cfg.get("vm_restart_ssh_port", vm_rt_ssh_port),
        )
    )
    post_benchmark_vm_restart_ssh_identity_file = str(
        os.environ.get(
            "POST_BENCHMARK_VM_RESTART_SSH_IDENTITY_FILE",
            cleanup_cfg.get("vm_restart_ssh_identity_file", vm_rt_ssh_identity_file),
        )
    ).strip()
    restart_tags_cfg = cleanup_cfg.get("restart_tags", ["iteration"])
    restart_tags = {
        str(tag).strip() for tag in restart_tags_cfg if str(tag).strip()
    } if isinstance(restart_tags_cfg, list) else {
        part.strip()
        for part in str(restart_tags_cfg).split(",")
        if part.strip()
    }
    if not restart_tags:
        restart_tags = {"iteration"}
    restart_pg_ctl_path = str(
        os.environ.get(
            "POST_BENCHMARK_PG_CTL_PATH",
            cleanup_cfg.get("pg_ctl_path", "/usr/lib/postgresql/17/bin/pg_ctl"),
        )
    ).strip()
    restart_pg_data_dir = str(
        os.environ.get(
            "POST_BENCHMARK_PG_DATA_DIR",
            cleanup_cfg.get("pg_data_dir", "/data"),
        )
    ).strip()
    restart_ready_db = str(
        os.environ.get(
            "POST_BENCHMARK_READY_DB",
            cleanup_cfg.get("ready_db", pg_stat_dbname),
        )
    ).strip()
    restart_ready_host = str(
        os.environ.get(
            "POST_BENCHMARK_READY_HOST",
            cleanup_cfg.get("ready_host", "127.0.0.1"),
        )
    ).strip()
    restart_ready_port = str(
        os.environ.get(
            "POST_BENCHMARK_READY_PORT",
            cleanup_cfg.get("ready_port", pg_port),
        )
    ).strip()
    restart_ready_sql = str(
        os.environ.get(
            "POST_BENCHMARK_READY_SQL",
            cleanup_cfg.get("ready_sql", "SELECT 1;"),
        )
    ).strip()
    restart_wait_timeout_sec = float(
        os.environ.get(
            "POST_BENCHMARK_RESTART_TIMEOUT_SEC",
            cleanup_cfg.get("restart_wait_timeout_sec", 60),
        )
    )
    restart_poll_interval_sec = float(
        os.environ.get(
            "POST_BENCHMARK_RESTART_POLL_INTERVAL_SEC",
            cleanup_cfg.get("restart_poll_interval_sec", 2),
        )
    )

    def _sql_quote(value: str) -> str:
        return value.replace("'", "''")

    def _build_terminate_idle_sql() -> str:
        where_parts = [
            "pid <> pg_backend_pid()",
            "backend_type = 'client backend'",
            "state = 'idle'",
            f"usename = '{_sql_quote(cleanup_target_user)}'",
            f"datname = '{_sql_quote(cleanup_target_db)}'",
        ]
        if cleanup_target_app:
            where_parts.append(
                f"application_name = '{_sql_quote(cleanup_target_app)}'"
            )
        where_sql = " AND ".join(where_parts)
        return (
            "SELECT pg_terminate_backend(pid) "
            "FROM pg_stat_activity "
            f"WHERE {where_sql};"
        )

    def _read_postmaster_start_time(dbname: str) -> Optional[str]:
        try:
            value = _psql_query("SELECT pg_postmaster_start_time();", dbname=dbname).strip()
            return value or None
        except Exception:
            return None

    def _restart_db_container_after_benchmark(tag: str, *, force: bool = False) -> None:
        if not force and (
            not post_benchmark_restart_db
            or not _tag_matches_configured(restart_tags, tag)
        ):
            return
        pre_restart_start_time = _read_postmaster_start_time(restart_ready_db)
        if metrics_source == "vm-runtime" or final_eval_runtime_source == "vm-runtime":
            def _run_vm_ssh(remote_cmd: str) -> subprocess.CompletedProcess:
                ssh_cmd = [
                    "ssh",
                    "-o", "BatchMode=yes",
                    "-o", f"ConnectTimeout={max(1, int(vm_rt_connect_timeout))}",
                    "-o", "ServerAliveInterval=10",
                    "-o", "ServerAliveCountMax=3",
                    "-p", str(int(post_benchmark_vm_restart_ssh_port)),
                ]
                if post_benchmark_vm_restart_ssh_identity_file:
                    ssh_cmd.extend(["-i", post_benchmark_vm_restart_ssh_identity_file])
                ssh_cmd.extend([
                    post_benchmark_vm_restart_ssh_target or vm_rt_ssh_target or vm_rt_host,
                    remote_cmd,
                ])
                return subprocess.run(
                    ssh_cmd,
                    check=False,
                    capture_output=True,
                    text=True,
                    timeout=max(30.0, restart_wait_timeout_sec + 30.0),
                )

            try:
                restart_proc = _run_vm_ssh(f"bash -lc {shlex.quote(post_benchmark_vm_restart_cmd)}")
                if restart_proc.returncode != 0:
                    raise RuntimeError(
                        "failed to restart postgres on vm; "
                        f"stdout={((restart_proc.stdout or '').strip())}; "
                        f"stderr={((restart_proc.stderr or '').strip())}"
                    )

                deadline = time.time() + restart_wait_timeout_sec
                probe_error = ""
                while True:
                    try:
                        _ = _psql_query(restart_ready_sql, dbname=restart_ready_db)
                        break
                    except Exception as exc:
                        probe_error = str(exc)
                    if time.time() >= deadline:
                        raise RuntimeError(
                            "database readiness check timeout after vm postgres restart; "
                            f"last_error={probe_error}"
                        )
                    time.sleep(restart_poll_interval_sec)

                post_restart_start_time = _read_postmaster_start_time(restart_ready_db)
                restart_confirmed = bool(
                    pre_restart_start_time
                    and post_restart_start_time
                    and pre_restart_start_time != post_restart_start_time
                )
                if pre_restart_start_time and post_restart_start_time and not restart_confirmed:
                    raise RuntimeError(
                        "vm postgres restart probe succeeded but postmaster_start_time did not change; "
                        f"before={pre_restart_start_time}, after={post_restart_start_time}"
                    )

                time.sleep(5)
                main_logger.log_struct(
                    {
                        "event": "post_benchmark_restart_db",
                        "tag": tag,
                        "target": "vm",
                        "ssh_target": post_benchmark_vm_restart_ssh_target or vm_rt_ssh_target or vm_rt_host,
                        "restart_cmd": post_benchmark_vm_restart_cmd,
                        "ready_host": restart_ready_host,
                        "ready_port": restart_ready_port,
                        "ready_db": restart_ready_db,
                        "ready_sql": restart_ready_sql,
                        "pre_restart_postmaster_start_time": pre_restart_start_time,
                        "post_restart_postmaster_start_time": post_restart_start_time,
                        "restart_confirmed": restart_confirmed,
                        "success": True,
                    }
                )
                return
            except Exception as exc:
                main_logger.log_struct(
                    {
                        "event": "post_benchmark_restart_db",
                        "tag": tag,
                        "target": "vm",
                        "ssh_target": post_benchmark_vm_restart_ssh_target or vm_rt_ssh_target or vm_rt_host,
                        "restart_cmd": post_benchmark_vm_restart_cmd,
                        "ready_host": restart_ready_host,
                        "ready_port": restart_ready_port,
                        "ready_db": restart_ready_db,
                        "ready_sql": restart_ready_sql,
                        "pre_restart_postmaster_start_time": pre_restart_start_time,
                        "success": False,
                        "error": str(exc),
                    }
                )
                if post_benchmark_restart_required:
                    raise
                print(f"[WARN] Post-benchmark VM DB restart failed ({tag}): {exc}")
                return
        if not post_benchmark_db_container:
            msg = "POST_BENCHMARK_DB_CONTAINER is empty."
            if post_benchmark_restart_required:
                raise RuntimeError(msg)
            print(f"[WARN] {msg}")
            return

        stop_cmd = (
            f'su - postgres -c "{restart_pg_ctl_path} -D {restart_pg_data_dir} -m fast stop"'
        )
        start_cmd = (
            f'su - postgres -c "{restart_pg_ctl_path} -D {restart_pg_data_dir} start"'
        )
        ready_probe_cmd = [
            "docker",
            "exec",
            "-u",
            "postgres",
            post_benchmark_db_container,
            "psql",
            "-h",
            restart_ready_host,
            "-p",
            restart_ready_port,
            "-d",
            restart_ready_db,
            "-Atqc",
            restart_ready_sql,
        ]

        def _run_docker_exec_with_retry(
            cmd: List[str],
            *,
            deadline: float,
        ) -> subprocess.CompletedProcess:
            last_proc: Optional[subprocess.CompletedProcess] = None
            while True:
                proc = subprocess.run(
                    cmd,
                    check=False,
                    capture_output=True,
                    text=True,
                )
                last_proc = proc
                combined = f"{proc.stdout or ''}\n{proc.stderr or ''}".lower()
                retryable = (
                    "oci runtime exec failed" in combined
                    or "error starting setns process" in combined
                    or "container is restarting" in combined
                )
                if not retryable or time.time() >= deadline:
                    return proc
                time.sleep(max(1.0, restart_poll_interval_sec))

        try:
            # Step 1: optionally restart the whole container first.
            if post_benchmark_restart_container_first:
                restart_container_proc = subprocess.run(
                    ["docker", "restart", post_benchmark_db_container],
                    check=False,
                    capture_output=True,
                    text=True,
                )
                if restart_container_proc.returncode != 0:
                    raise RuntimeError(
                        "failed to restart database container; "
                        f"stdout={((restart_container_proc.stdout or '').strip())}; "
                        f"stderr={((restart_container_proc.stderr or '').strip())}"
                    )

            # Step 2: ensure the container is running.
            deadline = time.time() + restart_wait_timeout_sec
            while True:
                container_probe = subprocess.run(
                    ["docker", "inspect", "-f", "{{.State.Running}}", post_benchmark_db_container],
                    check=False,
                    capture_output=True,
                    text=True,
                )
                if (
                    container_probe.returncode == 0
                    and container_probe.stdout.strip() == "true"
                ):
                    break
                if time.time() >= deadline:
                    raise RuntimeError(
                        "database container is not running; "
                        f"stdout={((container_probe.stdout or '').strip())}; "
                        f"stderr={((container_probe.stderr or '').strip())}"
                    )
                time.sleep(restart_poll_interval_sec)

            exec_deadline = time.time() + restart_wait_timeout_sec
            if not post_benchmark_restart_container_first:
                # Step 3: stop PostgreSQL inside the container only when the container
                # itself was not already restarted.
                stop_proc = _run_docker_exec_with_retry(
                    ["docker", "exec", post_benchmark_db_container, "bash", "-lc", stop_cmd],
                    deadline=exec_deadline,
                )
                stop_stderr = (stop_proc.stderr or "").strip().lower()
                stop_stdout = (stop_proc.stdout or "").strip().lower()
                not_running = (
                    "no server running" in stop_stderr
                    or "no server running" in stop_stdout
                    or "is not running" in stop_stderr
                    or "is not running" in stop_stdout
                    or "no such process" in stop_stderr
                    or "no such process" in stop_stdout
                )
                if stop_proc.returncode != 0 and not not_running:
                    raise RuntimeError(
                        "failed to stop postgres inside container; "
                        f"stdout={((stop_proc.stdout or '').strip())}; "
                        f"stderr={((stop_proc.stderr or '').strip())}"
                    )

            # Step 4: start PostgreSQL inside the container.
            start_proc = _run_docker_exec_with_retry(
                ["docker", "exec", post_benchmark_db_container, "bash", "-lc", start_cmd],
                deadline=exec_deadline,
            )
            start_stderr = (start_proc.stderr or "").strip().lower()
            start_stdout = (start_proc.stdout or "").strip().lower()
            already_running = (
                "already running" in start_stderr
                or "already running" in start_stdout
            )
            start_timed_out_but_maybe_ready = (
                "server did not start in time" in start_stderr
                or "server did not start in time" in start_stdout
            )
            if (
                start_proc.returncode != 0
                and not already_running
                and not start_timed_out_but_maybe_ready
            ):
                raise RuntimeError(
                    "failed to start postgres inside container; "
                    f"stdout={((start_proc.stdout or '').strip())}; "
                    f"stderr={((start_proc.stderr or '').strip())}"
                )

            deadline = time.time() + restart_wait_timeout_sec
            while True:
                probe = _run_docker_exec_with_retry(
                    ready_probe_cmd,
                    deadline=deadline,
                )
                if probe.returncode == 0:
                    break
                if time.time() >= deadline:
                    raise RuntimeError(
                        "database readiness check timeout after postgres restart; "
                        f"stderr={((probe.stderr or '').strip())}"
                    )
                time.sleep(restart_poll_interval_sec)

            post_restart_start_time = _read_postmaster_start_time(restart_ready_db)
            restart_confirmed = bool(
                pre_restart_start_time
                and post_restart_start_time
                and pre_restart_start_time != post_restart_start_time
            )
            if pre_restart_start_time and post_restart_start_time and not restart_confirmed:
                raise RuntimeError(
                    "container postgres restart probe succeeded but postmaster_start_time did not change; "
                    f"before={pre_restart_start_time}, after={post_restart_start_time}"
                )

            # Extra: wait for PG to exit recovery mode and be fully ready
            bg_deadline = time.time() + restart_wait_timeout_sec
            while True:
                bg_probe = _run_docker_exec_with_retry(
                    [
                        "docker", "exec", "-u", "postgres",
                        post_benchmark_db_container,
                        "psql",
                        "-h", restart_ready_host,
                        "-p", restart_ready_port,
                        "-d", restart_ready_db, "-Atqc",
                        "SELECT pg_is_in_recovery();",
                    ],
                    deadline=bg_deadline,
                )
                if bg_probe.returncode == 0 and bg_probe.stdout.strip() == "f":
                    break
                if time.time() >= bg_deadline:
                    print("[WARN] PG still in recovery mode, proceeding anyway")
                    break
                time.sleep(restart_poll_interval_sec)
            # Give PG a few more seconds to stabilize after restart
            time.sleep(5)

            main_logger.log_struct(
                {
                    "event": "post_benchmark_restart_db",
                    "tag": tag,
                    "container": post_benchmark_db_container,
                    "restart_container_first": post_benchmark_restart_container_first,
                    "restart_cmd": start_cmd,
                    "ready_host": restart_ready_host,
                    "ready_port": restart_ready_port,
                    "ready_db": restart_ready_db,
                    "ready_sql": restart_ready_sql,
                    "pre_restart_postmaster_start_time": pre_restart_start_time,
                    "post_restart_postmaster_start_time": post_restart_start_time,
                    "restart_confirmed": restart_confirmed,
                    "success": True,
                }
            )
        except Exception as exc:
            main_logger.log_struct(
                {
                    "event": "post_benchmark_restart_db",
                    "tag": tag,
                    "container": post_benchmark_db_container,
                    "restart_container_first": post_benchmark_restart_container_first,
                    "restart_cmd": start_cmd,
                    "ready_host": restart_ready_host,
                    "ready_port": restart_ready_port,
                    "ready_db": restart_ready_db,
                    "ready_sql": restart_ready_sql,
                    "pre_restart_postmaster_start_time": pre_restart_start_time,
                    "success": False,
                    "error": str(exc),
                }
            )
            if post_benchmark_restart_required:
                raise
            print(f"[WARN] Post-benchmark DB restart failed ({tag}): {exc}")

    def _ensure_database_ready(tag: str = "startup") -> None:
        try:
            _ = _psql_query(restart_ready_sql, dbname=restart_ready_db)
            main_logger.log_struct(
                {
                    "event": "database_ready_check",
                    "tag": tag,
                    "ready_db": restart_ready_db,
                    "ready_sql": restart_ready_sql,
                    "success": True,
                    "action": "noop",
                }
            )
            return
        except Exception as exc:
            main_logger.log_struct(
                {
                    "event": "database_ready_check",
                    "tag": tag,
                    "ready_db": restart_ready_db,
                    "ready_sql": restart_ready_sql,
                    "success": False,
                    "action": "restart_attempt",
                    "error": str(exc),
                }
            )
            print(
                f"[WARN] Database is not reachable before {tag}; attempting restart/start. detail={exc}",
                flush=True,
            )

        if (
            tag == "startup"
            and pre_benchmark_recovery_enabled
            and recovery_snapshot_enabled
        ):
            print(
                "[WARN] Database is unreachable at startup; attempting pre-benchmark recovery before restart.",
                flush=True,
            )
            try:
                _run_pre_benchmark_recovery("baseline")
                _ = _psql_query(restart_ready_sql, dbname=restart_ready_db)
                startup_recovery_state["completed"] = True
                startup_recovery_state["source_tag"] = "baseline"
                main_logger.log_struct(
                    {
                        "event": "database_ready_check",
                        "tag": tag,
                        "ready_db": restart_ready_db,
                        "ready_sql": restart_ready_sql,
                        "success": True,
                        "action": "startup_recovery_succeeded",
                    }
                )
                return
            except Exception as recovery_exc:
                main_logger.log_struct(
                    {
                        "event": "database_ready_check",
                        "tag": tag,
                        "ready_db": restart_ready_db,
                        "ready_sql": restart_ready_sql,
                        "success": False,
                        "action": "startup_recovery_failed",
                        "error": str(recovery_exc),
                    }
                )
                print(
                    f"[WARN] Startup pre-benchmark recovery failed; falling back to restart/start. detail={recovery_exc}",
                    flush=True,
                )

        if not post_benchmark_restart_db:
            raise RuntimeError(
                "Database is not reachable and automatic restart is disabled. "
                f"db={restart_ready_db} sql={restart_ready_sql!r}"
            )

        _restart_db_container_after_benchmark(tag, force=True)

        try:
            _ = _psql_query(restart_ready_sql, dbname=restart_ready_db)
        except Exception as exc:
            raise RuntimeError(
                "Database is still not reachable after automatic restart/start attempt. "
                f"db={restart_ready_db} sql={restart_ready_sql!r} detail={exc}"
            ) from exc

        main_logger.log_struct(
            {
                "event": "database_ready_check",
                "tag": tag,
                "ready_db": restart_ready_db,
                "ready_sql": restart_ready_sql,
                "success": True,
                "action": "restart_succeeded",
            }
        )

    def _run_post_benchmark_cleanup(tag: str) -> None:
        if post_benchmark_cleanup_enabled and post_benchmark_sql:
            try:
                _ = _psql_query(post_benchmark_sql, dbname=pg_stat_dbname)
                main_logger.log_struct(
                    {
                        "event": "post_benchmark_cleanup",
                        "tag": tag,
                        "dbname": pg_stat_dbname,
                        "sql": post_benchmark_sql,
                        "success": True,
                    }
                )
            except Exception as exc:
                print(f"[WARN] Post-benchmark cleanup failed ({tag}): {exc}")
                main_logger.log_struct(
                    {
                        "event": "post_benchmark_cleanup",
                        "tag": tag,
                        "dbname": pg_stat_dbname,
                        "sql": post_benchmark_sql,
                        "success": False,
                        "error": str(exc),
                    }
                )

        if post_benchmark_cleanup_enabled and post_benchmark_terminate_idle:
            terminate_sql = _build_terminate_idle_sql()
            try:
                out = _psql_query(terminate_sql, dbname=pg_stat_dbname)
                terminated_cnt = len([line for line in out.splitlines() if line.strip() == "t"])
                main_logger.log_struct(
                    {
                        "event": "post_benchmark_terminate_idle",
                        "tag": tag,
                        "dbname": pg_stat_dbname,
                        "target_user": cleanup_target_user,
                        "target_db": cleanup_target_db,
                        "target_app": cleanup_target_app if cleanup_target_app else None,
                        "terminated_count": terminated_cnt,
                        "success": True,
                    }
                )
            except Exception as exc:
                print(f"[WARN] Post-benchmark terminate-idle failed ({tag}): {exc}")
                main_logger.log_struct(
                    {
                        "event": "post_benchmark_terminate_idle",
                        "tag": tag,
                        "dbname": pg_stat_dbname,
                        "target_user": cleanup_target_user,
                        "target_db": cleanup_target_db,
                        "target_app": cleanup_target_app if cleanup_target_app else None,
                        "success": False,
                        "error": str(exc),
                    }
                )

        _restart_db_container_after_benchmark(tag)

    _run_external_replay_safe_guard("startup")
    _cleanup_stale_local_processes()
    _ensure_database_ready("startup")
    apply_params_via_alter_system(_with_fixed_params(p_real))

    def _run_warmup_command(command: str, timeout_sec: float) -> Dict[str, Any]:
        proc = subprocess.Popen(
            command,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            start_new_session=True,
            text=True,
        )
        output_lines: List[str] = []

        def _process_group_pids(pgid: int) -> List[int]:
            try:
                ps_proc = subprocess.run(
                    ["ps", "-eo", "pid=,pgid="],
                    text=True,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    check=False,
                )
            except Exception:
                return []
            pids: List[int] = []
            for row in (ps_proc.stdout or "").splitlines():
                parts = row.split()
                if len(parts) < 2:
                    continue
                try:
                    pid_value = int(parts[0])
                    pgid_value = int(parts[1])
                except ValueError:
                    continue
                if pgid_value == pgid:
                    pids.append(pid_value)
            return pids

        try:
            stdout, _ = proc.communicate(timeout=timeout_sec if timeout_sec > 0 else None)
            if stdout:
                output_lines.extend(stdout.splitlines())
                print(stdout, end="" if stdout.endswith("\n") else "\n", flush=True)
            return {
                "success": proc.returncode == 0,
                "timed_out": False,
                "returncode": proc.returncode,
                "output_tail": output_lines[-20:],
            }
        except subprocess.TimeoutExpired:
            remaining_after_term: List[int] = []
            remaining_after_kill: List[int] = []
            stale_cleanup_after_timeout = False
            try:
                os.killpg(proc.pid, signal.SIGTERM)
                stdout, _ = proc.communicate(timeout=10)
            except subprocess.TimeoutExpired:
                remaining_after_term = _process_group_pids(proc.pid)
                os.killpg(proc.pid, signal.SIGKILL)
                stdout, _ = proc.communicate()
            if stdout:
                output_lines.extend(stdout.splitlines())
                print(stdout, end="" if stdout.endswith("\n") else "\n", flush=True)
            remaining_after_kill = [
                pid for pid in _process_group_pids(proc.pid) if pid != os.getpid()
            ]
            for pid in remaining_after_kill:
                try:
                    os.kill(pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                except Exception:
                    pass
            if _to_bool(
                (cfg.get("pre_optimizer_process_cleanup") or {}).get(
                    "after_warmup_timeout",
                    True,
                ),
                True,
            ):
                _cleanup_stale_local_processes()
                stale_cleanup_after_timeout = True
            return {
                "success": True,
                "timed_out": True,
                "timeout_sec": timeout_sec,
                "returncode": proc.returncode,
                "remaining_pids_after_term": remaining_after_term,
                "remaining_pids_after_group_kill": remaining_after_kill,
                "stale_cleanup_after_timeout": stale_cleanup_after_timeout,
                "output_tail": output_lines[-20:],
            }

    def _wait_for_validation_warmup_connection_drain(tag: str) -> Dict[str, Any]:
        if (
            validation_warmup_drain_timeout_sec <= 0.0
            or not validation_warmup_drain_application_name
        ):
            return {
                "passed": True,
                "enabled": False,
                "reason": "disabled",
            }
        deadline = time.monotonic() + validation_warmup_drain_timeout_sec
        last_count: Optional[int] = None
        last_error = ""
        started = time.monotonic()
        print(
            f"[{tag}] waiting for validation warmup JDBC sessions to drain ...",
            flush=True,
        )
        while True:
            try:
                raw = _psql_query(
                    "SELECT count(*) FROM pg_stat_activity "
                    f"WHERE datname = '{_sql_quote(pg_stat_dbname)}' "
                    "AND pid <> pg_backend_pid() "
                    "AND application_name = "
                    f"'{_sql_quote(validation_warmup_drain_application_name)}';",
                    dbname=pg_stat_dbname,
                ).strip()
                value = _to_float_or_none(raw)
                if value is None:
                    raise RuntimeError(f"invalid connection count: {raw!r}")
                last_count = max(0, int(value))
                last_error = ""
                if last_count <= validation_warmup_drain_max_app_connections:
                    result = {
                        "passed": True,
                        "enabled": True,
                        "application_name": validation_warmup_drain_application_name,
                        "connection_count": last_count,
                        "max_allowed": validation_warmup_drain_max_app_connections,
                        "elapsed_sec": time.monotonic() - started,
                    }
                    main_logger.log_struct(
                        {
                            "event": "validation_warmup_connection_drain",
                            "tag": tag,
                            **result,
                        }
                    )
                    print(
                        f"[{tag}] validation warmup JDBC sessions drained: "
                        f"count={last_count}",
                        flush=True,
                    )
                    return result
            except Exception as exc:
                last_error = str(exc)
            if time.monotonic() >= deadline:
                result = {
                    "passed": False,
                    "enabled": True,
                    "application_name": validation_warmup_drain_application_name,
                    "connection_count": last_count,
                    "max_allowed": validation_warmup_drain_max_app_connections,
                    "elapsed_sec": time.monotonic() - started,
                    "error": last_error or "connection drain timed out",
                }
                main_logger.log_struct(
                    {
                        "event": "validation_warmup_connection_drain",
                        "tag": tag,
                        **result,
                    }
                )
                raise RuntimeError(
                    "validation warmup JDBC sessions did not drain before measured "
                    f"workload: {result}"
                )
            time.sleep(validation_warmup_drain_poll_sec)

    def _run_validation_warmup(tag: str, params: Dict[str, float]) -> None:
        if not validation_warmup_enabled:
            return
        if not validation_warmup_cmd.strip():
            detail = "validation warmup is enabled but benchmark.validation_warmup_cmd is empty"
            main_logger.log_struct(
                {
                    "event": "validation_warmup",
                    "tag": tag,
                    "success": False,
                    "error": detail,
                }
            )
            if validation_warmup_required:
                raise RuntimeError(detail)
            print(f"[WARN] {detail}", flush=True)
            return

        print(f"\n[{tag}] validation warmup starts before measured workload ...", flush=True)
        warmup_start_ts = time.time()
        main_logger.log_struct(
            {
                "event": "validation_warmup_start",
                "tag": tag,
                "start_ts": warmup_start_ts,
                "timeout_sec": validation_warmup_timeout_sec,
                "command": validation_warmup_cmd,
                "params": copy.deepcopy(params),
                "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
            }
        )
        warmup_result: Dict[str, Any] = {}
        drain_error = ""
        try:
            warmup_result = _run_warmup_command(
                validation_warmup_cmd,
                validation_warmup_timeout_sec,
            )
            success = bool(warmup_result.get("success"))
        except Exception as exc:
            success = False
            warmup_result = {"success": False, "error": str(exc)}
        if success:
            try:
                warmup_result["connection_drain"] = (
                    _wait_for_validation_warmup_connection_drain(tag)
                )
            except Exception as exc:
                success = False
                drain_error = str(exc)
                warmup_result["connection_drain"] = {
                    "passed": False,
                    "error": drain_error,
                }
        warmup_end_ts = time.time()
        main_logger.log_struct(
            {
                "event": "validation_warmup",
                "tag": tag,
                "success": success,
                "start_ts": warmup_start_ts,
                "end_ts": warmup_end_ts,
                "duration_s": warmup_end_ts - warmup_start_ts,
                "timeout_sec": validation_warmup_timeout_sec,
                "command": validation_warmup_cmd,
                "result": warmup_result,
                "params": copy.deepcopy(params),
            }
        )
        if success:
            print(f"[{tag}] validation warmup finished.", flush=True)
            return
        detail = warmup_result.get("error") or warmup_result.get("output_tail") or "unknown error"
        if drain_error:
            raise RuntimeError(
                f"validation warmup connection drain failed before {tag}: {drain_error}"
            )
        if validation_warmup_required:
            raise RuntimeError(f"validation warmup failed before {tag}: {detail}")
        print(f"[WARN] Validation warmup failed before {tag}: {detail}", flush=True)

    if warmup_enabled:
        print("\nWarm up ...")
        print("p_real...")
        if warmup_timeout_sec > 0:
            print(f"Warm up : {warmup_timeout_sec:.0f}s", flush=True)
        warmup_start_ts = time.time()

        main_logger.log_struct(
            {
                "event": "warmup_start",
                "timestamp": time.strftime(
                    "%Y-%m-%d %H:%M:%S", time.localtime(warmup_start_ts)
                ),
            }
        )

        warmup_result: Dict[str, Any] = {}
        try:
            _run_pre_benchmark_recovery("warmup")
            warmup_result = _run_warmup_command(warmup_cmd, warmup_timeout_sec)
            warmup_success = bool(warmup_result.get("success"))
        except subprocess.CalledProcessError as e:
            print(f"Warmup : {e}")
            warmup_success = False
            warmup_result = {"success": False, "error": str(e)}
        except Exception as e:
            print(f"Warmup : {e}")
            warmup_success = False
            warmup_result = {"success": False, "error": str(e)}
        finally:
            _run_post_benchmark_cleanup("warmup")

        warmup_end_ts = time.time()
        print("Warm up ")

        main_logger.log_struct(
            {
                "event": "warmup_end",
                "success": warmup_success,
                "start_time": time.strftime(
                    "%Y-%m-%d %H:%M:%S", time.localtime(warmup_start_ts)
                ),
                "end_time": time.strftime(
                    "%Y-%m-%d %H:%M:%S", time.localtime(warmup_end_ts)
                ),
                "duration_seconds": warmup_end_ts - warmup_start_ts,
                "timeout_sec": warmup_timeout_sec,
                "timed_out": bool(warmup_result.get("timed_out")),
                "command": warmup_cmd,
                "result": warmup_result,
            }
        )

        if not warmup_success:
            exit(1)
    else:
        main_logger.log_struct(
            {
                "event": "warmup_skipped",
                "reason": "benchmark.warmup_enabled=false",
                "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
            }
        )

    def _pgss_columns(*, dbname: str) -> List[str]:
        out = _psql_query(
            "SELECT attname "
            "FROM pg_attribute "
            "WHERE attrelid = 'pg_stat_statements'::regclass "
            "AND attnum > 0 AND NOT attisdropped "
            "ORDER BY attnum;",
            dbname=dbname,
        )
        return [line.strip() for line in out.splitlines() if line.strip()]

    def _fetch_top_slowest_sql(*, dbname: str, limit: Optional[int] = 20) -> List[Dict[str, Any]]:
        cols = set(_pgss_columns(dbname=dbname))
        total_col = "total_exec_time" if "total_exec_time" in cols else "total_time"
        mean_col = "mean_exec_time" if "mean_exec_time" in cols else "mean_time"
        queryid_col = "queryid" if "queryid" in cols else None
        rows_col = "rows" if "rows" in cols else None

        select_cols = []
        if queryid_col:
            select_cols.append(queryid_col)
        select_cols.extend(["calls", total_col, mean_col])
        if rows_col:
            select_cols.append(rows_col)
        # Make output TSV-safe.
        select_cols.append(r"replace(replace(query, E'\t', ' '), E'\n', ' ') AS query")

        filter_clauses = [
            "dbid = (SELECT oid FROM pg_database WHERE datname = current_database())",
            "query NOT ILIKE 'SELECT attname FROM pg_attribute%'",
            "query NOT ILIKE 'SELECT pg_is_in_recovery()%'",
            "query NOT ILIKE 'SELECT $1%'",
            "query NOT ILIKE 'EXPLAIN (FORMAT JSON%'",
            "query NOT ILIKE 'DISCARD ALL%'",
            "query NOT ILIKE 'SELECT pg_stat_statements_reset()%'",
            "query NOT ILIKE '%pg_catalog%'",
            "query NOT ILIKE '%pg_stat_statements%'",
            "query NOT ILIKE '%pg_stat_activity%'",
        ]

        limit_clause = ""
        if limit is not None and int(limit) > 0:
            limit_clause = f" LIMIT {int(limit)}"

        sql = (
            "SELECT "
            + ", ".join(select_cols)
            + " FROM pg_stat_statements "
            "WHERE " + " AND ".join(filter_clauses) + " "
            f"ORDER BY {total_col} DESC "
            f"{limit_clause};"
        )
        out = _psql_query(sql, dbname=dbname)
        results: List[Dict[str, Any]] = []
        for line in out.splitlines():
            parts = line.split("\t")
            # Build dict by column order.
            idx = 0
            item: Dict[str, Any] = {}
            if queryid_col:
                item["queryid"] = parts[idx]
                idx += 1
            item["calls"] = float(parts[idx]); idx += 1
            item["total_time_ms"] = float(parts[idx]); idx += 1
            item["mean_time_ms"] = float(parts[idx]); idx += 1
            if rows_col:
                item["rows"] = float(parts[idx]); idx += 1
            item["query"] = parts[idx] if idx < len(parts) else ""
            results.append(item)
        return results

    def _read_database_size_bytes(*, dbname: str) -> float:
        out = _psql_query(
            f"SELECT pg_database_size('{dbname}');",
            dbname=dbname,
        )
        return float(out.strip() or 0.0)

    def _read_cache_hit_rate(*, dbname: str) -> float:
        out = _psql_query(
            "SELECT CASE "
            "WHEN (blks_hit + blks_read) > 0 "
            "THEN blks_hit::float / (blks_hit + blks_read) "
            "ELSE 0 END "
            "FROM pg_stat_database "
            "WHERE datname = current_database();",
            dbname=dbname,
        )
        return float(out.strip() or 0.0)

    def _read_active_session_count(*, dbname: str) -> float:
        out = _psql_query(
            "SELECT count(*) "
            "FROM pg_stat_activity "
            "WHERE datname = current_database() "
            "AND state = 'active' "
            "AND pid <> pg_backend_pid();",
            dbname=dbname,
        )
        return float(out.strip() or 0.0)

    def _extract_hybench_runtime_config(workload_cmd_text: str) -> Dict[str, Any]:
        result: Dict[str, Any] = {}
        command_text = str(workload_cmd_text or "").strip()
        if not command_text:
            return result
        base_dir = os.getcwd()
        cd_match = re.search(r"cd\s+([^\n&;]+?)\s*&&", command_text)
        if cd_match:
            base_dir = os.path.abspath(os.path.expanduser(cd_match.group(1).strip()))
        tail = command_text.split("&&")[-1].strip()
        try:
            tokens = shlex.split(tail)
        except Exception:
            tokens = tail.split()
        mode = None
        props_path = None
        for idx, token in enumerate(tokens):
            if token == "-t" and idx + 1 < len(tokens):
                mode = tokens[idx + 1]
            if token == "-c" and idx + 1 < len(tokens):
                props_token = tokens[idx + 1]
                props_path = (
                    props_token
                    if os.path.isabs(props_token)
                    else os.path.abspath(os.path.join(base_dir, props_token))
                )
        result["mode"] = mode
        result["props_path"] = props_path
        if not props_path or not os.path.exists(props_path):
            return result

        props: Dict[str, str] = {}
        try:
            with open(props_path, "r", encoding="utf-8") as handle:
                for raw_line in handle:
                    line = raw_line.strip()
                    if not line or line.startswith("#") or "=" not in line:
                        continue
                    key, value = line.split("=", 1)
                    props[key.strip()] = value.strip()
        except Exception as exc:
            result["props_error"] = str(exc)
            return result

        def prop_int(key: str, default: int = 0) -> int:
            try:
                return int(float(props.get(key, default)))
            except Exception:
                return default

        configured_concurrency = None
        if mode == "runxp":
            configured_concurrency = prop_int("xtpclient") + prop_int("xapclient")
        elif mode == "runtp":
            configured_concurrency = prop_int("tpclient")
        elif mode == "runap":
            configured_concurrency = prop_int("apclient")
        elif mode == "run":
            configured_concurrency = prop_int("tpclient") + prop_int("apclient")

        result["configured_concurrency"] = configured_concurrency
        result["props"] = {
            "tpclient": prop_int("tpclient"),
            "apclient": prop_int("apclient"),
            "xtpclient": prop_int("xtpclient"),
            "xapclient": prop_int("xapclient"),
            "apRunMins": prop_int("apRunMins"),
            "tpRunMins": prop_int("tpRunMins"),
            "xpRunMins": prop_int("xpRunMins"),
        }
        return result

    def _db_view_monitor_has_pg_stat_statements() -> bool:
        sql = """
            SELECT EXISTS (
                SELECT 1
                FROM pg_catalog.pg_class c
                JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
                WHERE c.relname = 'pg_stat_statements'
                  AND n.nspname NOT IN ('pg_catalog', 'information_schema')
            );
        """
        try:
            return _psql_query(sql, dbname=pg_stat_dbname).strip().lower() in {"t", "true", "1"}
        except Exception:
            return False

    db_view_monitor_include_statements = _db_view_monitor_has_pg_stat_statements()

    def _read_db_view_monitor_snapshot() -> Dict[str, Any]:
        if db_view_monitor_include_statements:
            statements_expr = """
                (
                    SELECT COALESCE(SUM(calls), 0)::bigint
                    FROM pg_stat_statements
                    WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())
                      AND query NOT ILIKE '%pg_stat_statements%'
                      AND query NOT ILIKE '%pg_stat_database%'
                ) AS statements_calls
            """
        else:
            statements_expr = "NULL::bigint AS statements_calls"

        sql = f"""
            SELECT
                EXTRACT(EPOCH FROM clock_timestamp())::float8 AS ts,
                d.xact_commit,
                d.xact_rollback,
                d.tup_returned,
                d.tup_fetched,
                d.tup_inserted,
                d.tup_updated,
                d.tup_deleted,
                d.blks_read,
                d.blks_hit,
                {statements_expr},
                (
                    SELECT COUNT(*)::bigint
                    FROM pg_stat_activity
                    WHERE datname = current_database()
                      AND state = 'active'
                      AND pid <> pg_backend_pid()
                ) AS active_sessions
            FROM pg_stat_database d
            WHERE d.datname = current_database();
        """
        raw = _psql_query(sql, dbname=pg_stat_dbname)
        parts = raw.split("\t")
        if len(parts) != 12:
            raise RuntimeError(f"unexpected db monitor snapshot column count={len(parts)} raw={raw!r}")
        return {
            "timestamp": float(parts[0]),
            "xact_commit": int(parts[1]),
            "xact_rollback": int(parts[2]),
            "tup_returned": int(parts[3]),
            "tup_fetched": int(parts[4]),
            "tup_inserted": int(parts[5]),
            "tup_updated": int(parts[6]),
            "tup_deleted": int(parts[7]),
            "blks_read": int(parts[8]),
            "blks_hit": int(parts[9]),
            "statements_calls": int(parts[10]) if parts[10] else None,
            "active_sessions": int(parts[11]),
        }

    def _rate(new_value: Optional[int], old_value: Optional[int], elapsed: float) -> Optional[float]:
        if new_value is None or old_value is None or elapsed <= 0:
            return None
        return max(0.0, float(new_value - old_value) / elapsed)

    def _db_view_monitor_row(label: str, prev: Dict[str, Any], cur: Dict[str, Any]) -> Dict[str, Any]:
        elapsed = max(1e-6, float(cur["timestamp"]) - float(prev["timestamp"]))
        prev_xact_total = int(prev["xact_commit"]) + int(prev["xact_rollback"])
        cur_xact_total = int(cur["xact_commit"]) + int(cur["xact_rollback"])
        prev_tuple_read = int(prev["tup_returned"]) + int(prev["tup_fetched"])
        cur_tuple_read = int(cur["tup_returned"]) + int(cur["tup_fetched"])
        prev_tuple_write = int(prev["tup_inserted"]) + int(prev["tup_updated"]) + int(prev["tup_deleted"])
        cur_tuple_write = int(cur["tup_inserted"]) + int(cur["tup_updated"]) + int(cur["tup_deleted"])
        return {
            "label": label,
            "time": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(float(cur["timestamp"]))),
            "elapsed_s": elapsed,
            "qps_statements": _rate(cur.get("statements_calls"), prev.get("statements_calls"), elapsed),
            "xact_tps": _rate(cur_xact_total, prev_xact_total, elapsed),
            "commit_tps": _rate(int(cur["xact_commit"]), int(prev["xact_commit"]), elapsed),
            "rollback_tps": _rate(int(cur["xact_rollback"]), int(prev["xact_rollback"]), elapsed),
            "tuple_read_ps": _rate(cur_tuple_read, prev_tuple_read, elapsed),
            "tuple_write_ps": _rate(cur_tuple_write, prev_tuple_write, elapsed),
            "block_read_ps": _rate(int(cur["blks_read"]), int(prev["blks_read"]), elapsed),
            "block_hit_ps": _rate(int(cur["blks_hit"]), int(prev["blks_hit"]), elapsed),
            "active_sessions": int(cur["active_sessions"]),
            "xact_total": cur_xact_total,
            "statements_calls": cur.get("statements_calls"),
        }

    def _write_db_view_monitor_rows(rows: List[Dict[str, Any]]) -> None:
        if not rows:
            return
        fields = [
            "label",
            "time",
            "elapsed_s",
            "qps_statements",
            "xact_tps",
            "commit_tps",
            "rollback_tps",
            "tuple_read_ps",
            "tuple_write_ps",
            "block_read_ps",
            "block_hit_ps",
            "active_sessions",
            "xact_total",
            "statements_calls",
        ]
        with db_monitor_csv_lock:
            os.makedirs(os.path.dirname(db_monitor_csv_path) or ".", exist_ok=True)
            with open(db_monitor_csv_path, "a", encoding="utf-8", newline="") as fp:
                writer = csv.DictWriter(fp, fieldnames=fields)
                if not db_monitor_csv_header_written["value"]:
                    writer.writeheader()
                    db_monitor_csv_header_written["value"] = True
                for row in rows:
                    writer.writerow(row)

    def _summarize_db_view_monitor_rows(rows: List[Dict[str, Any]]) -> Dict[str, Any]:
        summary: Dict[str, Any] = {
            "csv_path": db_monitor_csv_path,
            "sample_count": len(rows),
            "pg_stat_statements": db_view_monitor_include_statements,
        }
        key_map = {
            "db_qps": "qps_statements",
            "db_xact_tps": "xact_tps",
            "db_commit_tps": "commit_tps",
            "db_rollback_tps": "rollback_tps",
            "db_active_sessions": "active_sessions",
        }
        for out_key, row_key in key_map.items():
            values = [
                float(row[row_key])
                for row in rows
                if row.get(row_key) is not None
            ]
            summary[out_key] = (sum(values) / len(values)) if values else None
        return summary

    def _attach_db_view_monitor_metrics(
        validation: Dict[str, Any],
        db_view_monitor: Dict[str, Any],
    ) -> None:
        """Attach database-side QPS/TPS monitor summary to a validation record."""
        validation["db_view_monitor"] = db_view_monitor
        for key in [
            "db_qps",
            "db_xact_tps",
            "db_commit_tps",
            "db_rollback_tps",
            "db_active_sessions",
        ]:
            validation[key] = db_view_monitor.get(key)
        # Formal outer acceptance always uses database-side statement QPS from
        # pg_stat_statements.  The source is explicit because remote fresh-point
        # lanes monitor a separate control DB, while local lanes may monitor the
        # actual workload endpoint.  Workload QPS/TPS is never a substitute.
        if formal_pg_resource_enabled:
            benchmark_metrics = dict(validation.get("benchmark") or {})
            formal_db_qps, formal_db_qps_source = _resolve_formal_db_qps(
                source=formal_pg_resource_cfg.get("db_qps_source"),
                benchmark_metrics=benchmark_metrics,
                db_view_monitor=db_view_monitor,
            )
            validation["db_qps"] = formal_db_qps
            validation["formal_qps"] = formal_db_qps
            validation["db_qps_source"] = formal_db_qps_source
            validation["formal_qps_source"] = formal_db_qps_source

    def _run_with_db_view_monitor(label: str, func: Callable[[], Any]) -> Tuple[Any, Dict[str, Any]]:
        rows: List[Dict[str, Any]] = []
        errors: List[str] = []
        stop_event = threading.Event()
        interval_s = 1.0

        def sample_loop() -> None:
            try:
                prev = _read_db_view_monitor_snapshot()
            except Exception as exc:
                errors.append(str(exc))
                return
            while not stop_event.wait(interval_s):
                try:
                    cur = _read_db_view_monitor_snapshot()
                    row = _db_view_monitor_row(label, prev, cur)
                    rows.append(row)
                    prev = cur
                except Exception as exc:
                    if len(errors) < 5:
                        errors.append(str(exc))

        start_ts = time.time()
        thread = threading.Thread(target=sample_loop, daemon=True)
        thread.start()
        result: Any = None
        error: Optional[BaseException] = None
        summary: Dict[str, Any] = {}
        try:
            result = func()
        except BaseException as exc:
            error = exc
        finally:
            end_ts = time.time()
            stop_event.set()
            thread.join(timeout=max(2.0, interval_s * 2.0))
            try:
                _write_db_view_monitor_rows(rows)
            except Exception as exc:
                if len(errors) < 5:
                    errors.append(f"csv_write_error: {exc}")
            summary = _summarize_db_view_monitor_rows(rows)
            summary.update(
                {
                    "event": "db_view_monitor_summary",
                    "label": label,
                    "window": [start_ts, end_ts],
                    "errors": errors,
                }
            )
            main_logger.log_struct(summary)
            # Store for callers that need to attach it to iteration metadata.
            _run_with_db_view_monitor.last_summary = summary
        if error is not None:
            raise error
        return result, summary

    _run_with_db_view_monitor.last_summary = {}

    def _run_workload_with_pg_concurrency_sampling(
        *,
        dbname: Optional[str],
        command: str,
        sample_interval_s: float = 1.0,
    ) -> Dict[str, Any]:
        samples: List[float] = []
        errors: List[str] = []
        workload_output_lines: List[str] = []
        stop_event = threading.Event()

        def sample_loop() -> None:
            while not stop_event.is_set():
                try:
                    samples.append(_read_active_session_count(dbname=dbname))
                except Exception as exc:
                    if len(errors) < 5:
                        errors.append(str(exc))
                stop_event.wait(sample_interval_s)

        start_ts = time.time()
        sampler: Optional[threading.Thread] = None
        if dbname:
            sampler = threading.Thread(target=sample_loop, daemon=True)
            sampler.start()
        try:
            proc = subprocess.Popen(
                command,
                shell=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
            )
            while True:
                raw = proc.stdout.readline() if proc.stdout is not None else b""
                if raw:
                    line = raw.decode("utf-8", errors="replace").rstrip("\n")
                    workload_output_lines.append(line)
                    print(line, flush=True)
                    continue
                if proc.poll() is not None:
                    remaining = proc.stdout.read() if proc.stdout is not None else b""
                    if remaining:
                        for line in remaining.decode("utf-8", errors="replace").splitlines():
                            workload_output_lines.append(line)
                            print(line, flush=True)
                    ret = proc.wait()
                    if ret != 0:
                        raise subprocess.CalledProcessError(ret, command)
                    break
                time.sleep(0.1)
        finally:
            end_ts = time.time()
            stop_event.set()
            if sampler is not None:
                sampler.join(timeout=max(1.0, sample_interval_s * 2.0))

        concurrency_stats = None
        if samples:
            sorted_samples = sorted(samples)
            p99_idx = min(int(len(sorted_samples) * 0.99), len(sorted_samples) - 1)
            concurrency_stats = {
                "min": float(sorted_samples[0]),
                "max": float(sorted_samples[-1]),
                "avg": float(sum(sorted_samples) / len(sorted_samples)),
                "p99": float(sorted_samples[p99_idx]),
                "samples": len(samples),
                "sample_interval_s": sample_interval_s,
                "source": "pg_stat_activity",
            }
        benchmark_parsed = parse_hybench_benchmark_output(workload_output_lines)
        return {
            "start_ts": start_ts,
            "end_ts": end_ts,
            "concurrency": concurrency_stats,
            "errors": errors,
            "benchmark": benchmark_parsed.get("benchmark") or {},
            "benchmark_latency": benchmark_parsed.get("benchmark_latency") or {},
            "workload_output": benchmark_parsed.get("workload_output") or "",
        }

    def _run_workload_with_pg_concurrency_sampling_and_runtime_monitor(
        *,
        dbname: str,
        command: str,
        container_name: str,
        interval_s: float,
        warmup_s: float,
        memory_mode: str,
        sample_interval_s: float = 1.0,
    ) -> Dict[str, Any]:
        samples: List[float] = []
        errors: List[str] = []
        stop_event = threading.Event()

        def sample_loop() -> None:
            while not stop_event.is_set():
                try:
                    samples.append(_read_active_session_count(dbname=dbname))
                except Exception as exc:
                    if len(errors) < 5:
                        errors.append(str(exc))
                stop_event.wait(sample_interval_s)

        start_ts = time.time()
        sampler = threading.Thread(target=sample_loop, daemon=True)
        sampler.start()
        resource_avg: Dict[str, float] = {}
        resource_stats: Dict[str, Any] = {}
        try:
            resource_avg, resource_stats = monitor_resources_from_docker_runtime_workload(
                workload_cmd=command,
                container_name=container_name,
                interval_s=interval_s,
                warmup_s=warmup_s,
                memory_mode=memory_mode,
                io_scope=docker_rt_io_scope,
            )
        finally:
            end_ts = time.time()
            stop_event.set()
            sampler.join(timeout=max(1.0, sample_interval_s * 2.0))

        concurrency_stats = None
        if samples:
            sorted_samples = sorted(samples)
            p99_idx = min(int(len(sorted_samples) * 0.99), len(sorted_samples) - 1)
            concurrency_stats = {
                "min": float(sorted_samples[0]),
                "max": float(sorted_samples[-1]),
                "avg": float(sum(sorted_samples) / len(sorted_samples)),
                "p99": float(sorted_samples[p99_idx]),
                "samples": len(samples),
                "sample_interval_s": sample_interval_s,
                "source": "pg_stat_activity",
            }
        return {
            "start_ts": start_ts,
            "end_ts": end_ts,
            "concurrency": concurrency_stats,
            "errors": errors,
            "resource_avg": resource_avg,
            "resource_stats": resource_stats,
            "benchmark": dict(resource_stats.get("benchmark") or {}),
            "benchmark_latency": dict(resource_stats.get("benchmark_latency") or {}),
            "workload_output": str(resource_stats.get("workload_output") or ""),
        }

    def _collect_plan_estimator_workload_profile(
        *,
        dbname: str,
        start_ts: float,
        end_ts: float,
        all_sql: List[Dict[str, Any]],
        sampled_concurrency: Optional[Dict[str, Any]] = None,
        hybench_runtime: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        elapsed_s = max(1e-6, end_ts - start_ts)
        total_exec_time_ms = sum(
            max(0.0, float(item.get("total_time_ms") or 0.0))
            for item in all_sql
        )
        concurrency_estimate = total_exec_time_ms / (elapsed_s * 1000.0)
        profile: Dict[str, Any] = {
            "window": [start_ts, end_ts],
            "elapsed_seconds": elapsed_s,
            "sql_count": len(all_sql),
            "workload_cmd": workload_cmd,
            "concurrency": {
                "avg_estimated": concurrency_estimate,
                "source": "pg_stat_statements_total_time_over_wall_time",
            },
            "database_size_bytes": None,
            "cache_hit_rate": None,
        }
        if sampled_concurrency:
            profile["concurrency"] = {
                "avg": sampled_concurrency.get("avg"),
                "p99": sampled_concurrency.get("p99"),
                "max": sampled_concurrency.get("max"),
                "avg_estimated": concurrency_estimate,
                "samples": sampled_concurrency.get("samples"),
                "sample_interval_s": sampled_concurrency.get("sample_interval_s"),
                "source": str(sampled_concurrency.get("source") or "pg_stat_activity"),
            }
        if hybench_runtime:
            profile["hybench_runtime"] = hybench_runtime
            if hybench_runtime.get("mode"):
                profile["hybench_mode"] = hybench_runtime.get("mode")
            configured_concurrency = hybench_runtime.get("configured_concurrency")
            if configured_concurrency not in (None, ""):
                profile["concurrency"]["configured"] = configured_concurrency
        try:
            profile["database_size_bytes"] = _read_database_size_bytes(dbname=dbname)
        except Exception as exc:
            profile["database_size_error"] = str(exc)
        try:
            profile["cache_hit_rate"] = _read_cache_hit_rate(dbname=dbname)
        except Exception as exc:
            profile["cache_hit_rate_error"] = str(exc)
        if concurrency_promql:
            try:
                _prom_avg, prom_stats = monitor_resources_from_prometheus(
                    prom_url=prom_url,
                    start_ts=start_ts,
                    end_ts=end_ts,
                    step=prom_step,
                    concurrency_promql=concurrency_promql,
                )
                if prom_stats.get("concurrency"):
                    prom_concurrency = prom_stats.get("concurrency") or {}
                    profile["concurrency"] = {
                        "avg": prom_concurrency.get("avg"),
                        "p99": prom_concurrency.get("p99"),
                        "max": prom_concurrency.get("max"),
                        "avg_estimated": concurrency_estimate,
                        "configured": (hybench_runtime or {}).get("configured_concurrency"),
                        "sampled_avg": (sampled_concurrency or {}).get("avg"),
                        "sampled_p99": (sampled_concurrency or {}).get("p99"),
                        "sampled_max": (sampled_concurrency or {}).get("max"),
                        "source": "prometheus",
                    }
            except Exception as exc:
                profile["concurrency_prometheus_error"] = str(exc)
        return profile

    def _compact_plan_estimator_workload_profile(profile: Dict[str, Any]) -> Dict[str, Any]:
        """Keep per-candidate JSONL compact while preserving audit-critical context."""
        if not isinstance(profile, dict):
            return {}
        keys = [
            "window",
            "elapsed_seconds",
            "sql_count",
            "concurrency",
            "database_size_bytes",
            "cache_hit_rate",
            "hybench_mode",
            "benchmark",
            "benchmark_latency",
            "runtime_resource_raw",
            "baseline_runtime_memory_bytes",
            "resource_model_retraining",
        ]
        compact = {key: profile.get(key) for key in keys if key in profile}
        runtime_stats = profile.get("runtime_resource_stats")
        if isinstance(runtime_stats, dict):
            compact["runtime_resource_stats"] = {
                key: runtime_stats.get(key)
                for key in [
                    "cpu",
                    "memory",
                    "io",
                    "io_read",
                    "io_write",
                    "memory_source",
                    "io_source",
                    "stable_sample_count",
                ]
                if key in runtime_stats
            }
        hybench_runtime = profile.get("hybench_runtime")
        if isinstance(hybench_runtime, dict):
            compact["hybench_runtime"] = {
                key: hybench_runtime.get(key)
                for key in ["mode", "configured_concurrency", "props"]
                if key in hybench_runtime
            }
        return compact

    formal_pg_resource_cfg = cfg.get("formal_pg_resource_semantics") or {}
    formal_pg_resource_enabled = bool(
        isinstance(formal_pg_resource_cfg, dict)
        and formal_pg_resource_cfg.get("enabled") is True
    )
    if formal_pg_resource_enabled:
        configured_semantics = str(formal_pg_resource_cfg.get("semantics") or "")
        if configured_semantics != FORMAL_PG_RESOURCE_SEMANTICS_NAME:
            raise RuntimeError(
                "formal_pg_resource_semantics.semantics must equal "
                f"{FORMAL_PG_RESOURCE_SEMANTICS_NAME!r}"
            )

    def _normalize_runtime_resource_avg(
        resource_avg_raw: Dict[str, float],
        resource_stats_raw: Dict[str, Any],
    ) -> Tuple[Dict[str, float], Dict[str, float]]:
        if formal_pg_resource_enabled:
            formal_resource = resource_stats_raw.get("formal_pg_resource")
            if not isinstance(formal_resource, dict) or not formal_resource:
                raise RuntimeError(
                    "formal PostgreSQL runtime resource evidence is missing; "
                    "legacy read+write IO normalization is forbidden for this campaign"
                )
            return normalize_formal_pg_runtime_resource(formal_resource, capability)
        io_read_mb_s = float(((resource_stats_raw.get("io_read") or {}).get("avg", 0.0) or 0.0)) / (1024 ** 2)
        io_write_mb_s = float(((resource_stats_raw.get("io_write") or {}).get("avg", 0.0) or 0.0)) / (1024 ** 2)
        io_sum_mb_s = io_read_mb_s + io_write_mb_s
        io_mb_s = (
            float(((resource_stats_raw.get("io") or {}).get("avg", 0.0) or 0.0)) / (1024 ** 2)
            if isinstance(resource_stats_raw.get("io"), dict)
            else float(resource_avg_raw.get("io", 0.0) or 0.0) / (1024 ** 2)
        )
        if io_sum_mb_s > 0.0 and (io_mb_s <= 0.0 or io_mb_s < io_sum_mb_s * 0.5):
            io_mb_s = io_sum_mb_s
        normalized_runtime = {
            "cpu": float(resource_avg_raw.get("cpu", 0.0) or 0.0),
            "memory": float(resource_avg_raw.get("memory", 0.0) or 0.0) / (1024 ** 3),
            "io": io_mb_s,
            "io_read": io_read_mb_s,
            "io_write": io_write_mb_s,
        }
        runtime_utilization = {}
        for key, cap_val in capability.items():
            value = normalized_runtime.get(key, 0.0)
            runtime_utilization[key] = (value / cap_val * 100.0) if cap_val not in (None, 0) else 0.0
        return normalized_runtime, runtime_utilization

    def _to_float_or_none(value: Any) -> Optional[float]:
        try:
            if value in (None, ""):
                return None
            return float(value)
        except (TypeError, ValueError):
            return None

    baseline_correction_cfg = (plan_estimator_cfg.get("baseline_correction") or {})
    baseline_correction_enabled = (
        metrics_source == "plan-estimator"
        and plan_estimator_bootstrap_once
        and _to_bool(baseline_correction_cfg.get("enabled", True), True)
    )
    baseline_correction_target_log10_error = max(
        0.0,
        float(
            _to_float_or_none(
                baseline_correction_cfg.get(
                    "target_log10_error",
                    baseline_correction_cfg.get("target_error", 1.0),
                )
            ) or 1.0
        ),
    )
    baseline_correction_max_rounds = max(
        1,
        _to_int(baseline_correction_cfg.get("max_rounds", 5), 5),
    )
    baseline_correction_learning_rate = min(
        1.0,
        max(
            0.0,
            float(_to_float_or_none(baseline_correction_cfg.get("learning_rate")) or 1.0),
        ),
    )
    baseline_correction_signal_floor = max(
        1e-12,
        float(_to_float_or_none(baseline_correction_cfg.get("signal_floor")) or 0.001),
    )
    baseline_correction_max_scale = max(
        1.0,
        float(_to_float_or_none(baseline_correction_cfg.get("max_scale")) or 1000.0),
    )
    baseline_correction_resources_cfg = baseline_correction_cfg.get("resources") or list(capability.keys())
    baseline_correction_resources = [
        str(item)
        for item in baseline_correction_resources_cfg
        if str(item) in capability
    ] or list(capability.keys())
    baseline_correction_state: Dict[str, Any] = {
        "enabled": baseline_correction_enabled,
        "completed": False,
        "success": False,
        "round_count": 0,
        "target_log10_error": baseline_correction_target_log10_error,
        "max_rounds": baseline_correction_max_rounds,
        "learning_rate": baseline_correction_learning_rate,
        "signal_floor": baseline_correction_signal_floor,
        "resources": list(baseline_correction_resources),
        "scales": {key: 1.0 for key in baseline_correction_resources},
        "history": [],
        "last_max_log10_error": None,
        "actual_baseline": {},
        "skip_reason": None,
        "exempt_resources": [],
        "exemption_source": None,
    }

    def _print_top_sql(title: str, items: List[Dict[str, Any]], limit: int = 10) -> None:
        lines = []
        lines.append("=" * 90)
        lines.append(f"  {title}")
        lines.append("=" * 90)
        lines.append(f"  {'#':<3} {'Calls':>10} {'Mean ms':>12} {'Total ms':>12}  Query")
        lines.append(f"  {'-'*3} {'-'*10} {'-'*12} {'-'*12}  {'-'*40}")
        for idx, item in enumerate(items[: max(0, int(limit))], start=1):
            query = str(item.get("query") or "").strip().replace("\n", " ")
            if len(query) > 80:
                query = query[:77] + "..."
            calls = float(item.get("calls") or 0.0)
            mean_ms = float(item.get("mean_time_ms") or 0.0)
            total_ms = float(item.get("total_time_ms") or 0.0)
            lines.append(
                f"  {idx:<3} {calls:>10.0f} {mean_ms:>12.2f} {total_ms:>12.2f}  {query}"
            )
        if not items:
            lines.append("  (empty)")
        lines.append("=" * 90)
        print("\n" + "\n".join(lines) + "\n")

    def _normalize_estimated_resource(
        resource_avg_raw: Dict[str, float],
        resource_stats_raw: Dict[str, Any],
    ) -> Dict[str, float]:
        mem_source = ((resource_stats_raw.get("memory_source", {}) or {}).get("value"))
        estimator_units = str(mem_source or "").strip().lower() == "plan-estimator"
        if estimator_units:
            io_read_mb_s = float(((resource_stats_raw.get("io_read") or {}).get("avg", 0.0) or 0.0))
            io_write_mb_s = float(((resource_stats_raw.get("io_write") or {}).get("avg", 0.0) or 0.0))
        else:
            io_read_mb_s = float(((resource_stats_raw.get("io_read") or {}).get("avg", 0.0) or 0.0)) / (1024 ** 2)
            io_write_mb_s = float(((resource_stats_raw.get("io_write") or {}).get("avg", 0.0) or 0.0)) / (1024 ** 2)
        io_sum_mb_s = io_read_mb_s + io_write_mb_s
        if estimator_units:
            io_mb_s = (
                float(((resource_stats_raw.get("io") or {}).get("avg", 0.0) or 0.0))
                if isinstance(resource_stats_raw.get("io"), dict)
                else float(resource_avg_raw.get("io", 0.0) or 0.0)
            )
            memory_gb = float(resource_avg_raw.get("memory", 0.0) or 0.0)
        else:
            io_mb_s = (
                float(((resource_stats_raw.get("io") or {}).get("avg", 0.0) or 0.0)) / (1024 ** 2)
                if isinstance(resource_stats_raw.get("io"), dict)
                else float(resource_avg_raw.get("io", 0.0) or 0.0) / (1024 ** 2)
            )
            memory_gb = float(resource_avg_raw.get("memory", 0.0) or 0.0) / (1024 ** 3)
        if io_sum_mb_s > 0.0 and (io_mb_s <= 0.0 or io_mb_s < io_sum_mb_s * 0.5):
            io_mb_s = io_sum_mb_s
        return {
            "cpu": float(resource_avg_raw.get("cpu", 0.0) or 0.0),
            "memory": memory_gb,
            "io": io_mb_s,
            "io_read": io_read_mb_s,
            "io_write": io_write_mb_s,
        }

    def _apply_baseline_correction_to_normalized(
        normalized_resource: Dict[str, float]
    ) -> Dict[str, float]:
        return apply_baseline_correction_scales(
            normalized_resource,
            scales=baseline_correction_state.get("scales") or {},
            exempt_resources=baseline_correction_state.get("exempt_resources") or [],
        )

    def _should_apply_baseline_correction(
        label: Optional[str],
        params: Optional[Dict[str, float]] = None,
    ) -> bool:
        """Only estimator-driven middle iterations should receive estimator calibration scales."""
        if not baseline_correction_state.get("enabled"):
            return False
        normalized_label = str(label or "").strip().lower()
        if normalized_label.startswith("p_real") and params == p_real:
            return False
        if normalized_label.startswith("final") or normalized_label.startswith("validation"):
            return False
        return True

    def _compare_degraded_sql(
        baseline: List[Dict[str, Any]],
        final: List[Dict[str, Any]],
        *,
        threshold_pct: float = 10.0,
    ) -> Dict[str, Any]:
        def key_of(item: Dict[str, Any]) -> str:
            query_key = _normalize_plan_query_text(item.get("query"))
            if query_key:
                return f"query:{query_key}"
            if "queryid" in item and item["queryid"] not in (None, ""):
                return f"queryid:{item['queryid']}"
            return "query:"

        baseline_map = {key_of(x): x for x in baseline}
        final_map = {key_of(x): x for x in final}

        degraded: List[Dict[str, Any]] = []
        for key, base in baseline_map.items():
            fin = final_map.get(key)
            if not fin:
                continue
            base_mean = float(base.get("mean_time_ms") or 0.0)
            fin_mean = float(fin.get("mean_time_ms") or 0.0)
            if base_mean <= 0:
                continue
            pct = (fin_mean / base_mean - 1.0) * 100.0
            if pct > threshold_pct:
                degraded.append(
                    {
                        "key": key,
                        "baseline_queryid": base.get("queryid"),
                        "final_queryid": fin.get("queryid"),
                        "query": base.get("query"),
                        "baseline_mean_ms": base_mean,
                        "final_mean_ms": fin_mean,
                        "degradation_pct": pct,
                        "baseline_calls": base.get("calls"),
                        "final_calls": fin.get("calls"),
                    }
                )
        degraded.sort(key=lambda x: x["degradation_pct"], reverse=True)

        # Queries that did not appear in baseline capture but show up in final top list.
        # We cannot compute a baseline-relative slowdown for these (unknown baseline mean),
        # so we report them separately for manual inspection.
        new_in_final_top: List[Dict[str, Any]] = []
        for key, fin in final_map.items():
            if key in baseline_map:
                continue
            new_in_final_top.append(
                {
                    "key": key,
                    "queryid": fin.get("queryid"),
                    "query": fin.get("query"),
                    "final_mean_ms": float(fin.get("mean_time_ms") or 0.0),
                    "final_total_ms": float(fin.get("total_time_ms") or 0.0),
                    "final_calls": fin.get("calls"),
                }
            )
        new_in_final_top.sort(key=lambda x: x["final_total_ms"], reverse=True)

        disappeared_from_final_top: List[Dict[str, Any]] = []
        for key, base in baseline_map.items():
            if key in final_map:
                continue
            disappeared_from_final_top.append(
                {
                    "key": key,
                    "queryid": base.get("queryid"),
                    "query": base.get("query"),
                    "baseline_mean_ms": float(base.get("mean_time_ms") or 0.0),
                    "baseline_total_ms": float(base.get("total_time_ms") or 0.0),
                    "baseline_calls": base.get("calls"),
                }
            )
        disappeared_from_final_top.sort(
            key=lambda x: x["baseline_total_ms"], reverse=True
        )

        summary = {
            "degraded_count": len(degraded),
            "max_degradation_pct": degraded[0]["degradation_pct"] if degraded else None,
            "avg_degradation_pct": (
                sum(x["degradation_pct"] for x in degraded) / len(degraded)
                if degraded
                else None
            ),
            "threshold_pct": threshold_pct,
            "match_key": "normalized_sql_text",
            "degraded_sql": degraded,
            "new_in_final_top_count": len(new_in_final_top),
            "new_in_final_top": new_in_final_top,
            "disappeared_from_final_top_count": len(disappeared_from_final_top),
            "disappeared_from_final_top": disappeared_from_final_top,
        }
        return summary

    baseline_top_sql: List[Dict[str, Any]] = []
    baseline_all_sql: List[Dict[str, Any]] = []
    collected_replay_sql: List[Dict[str, Any]] = []
    collected_sql_summary: Dict[str, Any] = {}
    plan_estimator_workload_profile: Dict[str, Any] = {}
    baseline_benchmark: Dict[str, Any] = {}
    baseline_benchmark_latency: Dict[str, Any] = {}
    baseline_runtime_resource_avg: Dict[str, float] = {}
    baseline_runtime_resource_stats: Dict[str, Any] = {}
    baseline_runtime_normalized: Dict[str, float] = {}
    baseline_runtime_util: Dict[str, float] = {}
    baseline_db_view_summary: Dict[str, Any] = {}
    baseline_qps: Optional[float] = None
    baseline_tps: Optional[float] = None
    baseline_p90: Optional[float] = None
    baseline_p95: Optional[float] = None
    baseline_p99: Optional[float] = None
    baseline_strong_gate_failure: Optional[RuntimeError] = None
    hybench_runtime_cfg = _extract_hybench_runtime_config(workload_cmd)
    tracked_plan_queries: List[Dict[str, Any]] = []
    tracked_plan_change_keys: Set[str] = set()
    baseline_plan_samples: List[Dict[str, Any]] = []
    previous_iteration_plan_samples: List[Dict[str, Any]] = []
    if (
        metrics_source == "plan-estimator"
        and auto_explain_enabled
        and auto_explain_collect_sql_before_baseline
    ):
        print(f"\n[SQL Collect] run workload once with auto_explain on db={pg_stat_dbname} ...")
        sql_collect_start_ts = time.time()
        try:
            _run_external_replay_safe_guard("before_sql_collect")
            _run_pre_benchmark_recovery("sql_collect")
            _configure_auto_explain("sql_collect")
            _set_auto_explain_collection_enabled(True, "sql_collect")
            subprocess.run(workload_cmd, shell=True, check=True)
        finally:
            sql_collect_end_ts = time.time()
            collected_sql_summary = _collect_auto_explain_events(
                tag="sql_collect",
                start_ts=sql_collect_start_ts,
                end_ts=sql_collect_end_ts,
            )
            collected_replay_sql = list(collected_sql_summary.get("replay_queries") or [])
            if auto_explain_disable_after_collect:
                _set_auto_explain_collection_enabled(False, "sql_collect_complete")
            _run_post_benchmark_cleanup("sql_collect")
        main_logger.log_struct(
            {
                "event": "sql_collect_summary",
                "dbname": pg_stat_dbname,
                "window": [sql_collect_start_ts, sql_collect_end_ts],
                "sql_event_count": collected_sql_summary.get("sql_event_count"),
                "distinct_sql_fingerprint_count": collected_sql_summary.get("distinct_sql_fingerprint_count"),
                "distinct_sql_text_count": collected_sql_summary.get("distinct_sql_text_count"),
                "replay_sql_count": len(collected_replay_sql),
                "replay_queries_file": collected_sql_summary.get("replay_queries_file"),
                "top_sql_by_count": collected_sql_summary.get("top_sql_by_count"),
            }
        )
    def _reset_pg_stat_statements_for_workload(label: str, metadata: Optional[Dict[str, Any]] = None) -> None:
        """Reset pg_stat_statements after recovery, immediately before workload measurement."""
        print(f"\n[{label}] pg_stat_statements_reset() on db={pg_stat_dbname} ...", flush=True)
        try:
            _ = _psql_query("SELECT pg_stat_statements_reset();", dbname=pg_stat_dbname)
            if metadata is not None:
                metadata["pg_stat_statements_reset"] = {"success": True, "timing": "after-recovery"}
        except Exception as exc:
            if metadata is not None:
                metadata["pg_stat_statements_reset"] = {
                    "success": False,
                    "timing": "after-recovery",
                    "error": str(exc),
                }
            print(f"[WARN] pg_stat_statements_reset unavailable during {label}: {exc}", flush=True)
            main_logger.log_struct(
                {
                    "event": f"{label.lower().replace(' ', '_')}_pg_stat_statements_reset_error",
                    "dbname": pg_stat_dbname,
                    "error": str(exc),
                }
            )

    startup_baseline_reuse_cfg = (
        cfg.get("startup_baseline_reuse")
        if isinstance(cfg.get("startup_baseline_reuse"), dict)
        else {}
    )
    startup_baseline_reuse_enabled = _to_bool(
        startup_baseline_reuse_cfg.get("enabled", False),
        False,
    )
    partial_startup_resume_checkpoint: Optional[Dict[str, Any]] = None
    early_formal_protocol = (
        cfg.get("formal_outer_protocol")
        if isinstance(cfg.get("formal_outer_protocol"), dict)
        else {}
    )
    early_resume_path_raw = str(
        early_formal_protocol.get("formal_search_resume_checkpoint_path") or ""
    ).strip()
    if early_resume_path_raw:
        early_resume_path = Path(early_resume_path_raw).resolve()
        expected_early_resume_sha = str(
            early_formal_protocol.get("formal_search_resume_checkpoint_sha256")
            or ""
        ).strip()
        if not early_resume_path.is_file():
            raise RuntimeError(
                f"partial startup resume checkpoint is missing: {early_resume_path}"
            )
        actual_early_resume_sha = hashlib.sha256(
            early_resume_path.read_bytes()
        ).hexdigest()
        if actual_early_resume_sha != expected_early_resume_sha:
            raise RuntimeError(
                "partial startup resume checkpoint SHA mismatch: "
                f"{actual_early_resume_sha} != {expected_early_resume_sha}"
            )
        early_resume_checkpoint = json.loads(
            early_resume_path.read_text(encoding="utf-8")
        )
        if (
            early_resume_checkpoint.get("schema_version") == 1
            and early_resume_checkpoint.get("kind")
            == "gradient_partial_round_resume_checkpoint_v1"
        ):
            if (
                (early_resume_checkpoint.get("resume_contract") or {}).get(
                    "do_not_rerun_r0"
                )
                is not True
            ):
                raise RuntimeError("partial resume does not forbid R0 rerun")
            baseline_evidence_path = Path(
                str(early_resume_checkpoint.get("baseline_evidence_path") or "")
            ).resolve()
            baseline_evidence_sha = str(
                early_resume_checkpoint.get("baseline_evidence_sha256") or ""
            )
            if (
                not baseline_evidence_path.is_file()
                or hashlib.sha256(baseline_evidence_path.read_bytes()).hexdigest()
                != baseline_evidence_sha
            ):
                raise RuntimeError(
                    "partial resume baseline evidence is missing or has a SHA mismatch"
                )
            baseline_validation = early_resume_checkpoint.get(
                "baseline_validation"
            ) or {}
            baseline_protocol = (
                baseline_validation.get("candidate_measurement_protocol") or {}
            )
            if (
                not isinstance(baseline_validation, dict)
                or not baseline_validation
                or baseline_protocol.get("correctness_passed") is not True
                or baseline_protocol.get("stable") is not True
                or _to_float_or_none(
                    baseline_validation.get("db_qps")
                    or baseline_validation.get("formal_qps")
                )
                is None
            ):
                raise RuntimeError(
                    "partial resume baseline validation is incomplete or invalid"
                )
            partial_startup_resume_checkpoint = early_resume_checkpoint
            startup_baseline_reuse_enabled = True

    def _load_reusable_startup_baseline() -> Dict[str, Any]:
        if partial_startup_resume_checkpoint is not None:
            checkpoint = partial_startup_resume_checkpoint
            validation = copy.deepcopy(checkpoint.get("baseline_validation") or {})
            resource_avg = copy.deepcopy(validation.get("resource_raw") or {})
            resource_stats = copy.deepcopy(validation.get("resource_stats") or {})
            benchmark = copy.deepcopy(validation.get("benchmark") or {})
            benchmark_latency = copy.deepcopy(
                validation.get("benchmark_latency") or {}
            )
            formal_qps = _to_float_or_none(
                validation.get("db_qps") or validation.get("formal_qps")
            )
            if not resource_avg or not resource_stats or formal_qps is None:
                raise RuntimeError(
                    "partial resume baseline lacks resource or DB-QPS evidence"
                )
            benchmark.setdefault("db_qps", float(formal_qps))
            benchmark.setdefault("formal_qps", float(formal_qps))
            benchmark.setdefault("db_qps_source", "formal_benchmark_db_qps")
            benchmark.setdefault("formal_qps_source", "formal_benchmark_db_qps")
            resource_stats["benchmark"] = benchmark
            resource_stats["benchmark_latency"] = benchmark_latency
            resource_stats["candidate_measurement_protocol"] = copy.deepcopy(
                validation.get("candidate_measurement_protocol") or {}
            )
            resource_stats["formal_qps"] = float(formal_qps)
            resource_stats["formal_qps_source"] = "formal_benchmark_db_qps"
            resource_stats["workload_output"] = (
                "reused sealed partial-round baseline; no R0 replay"
            )
            return {
                "result_path": str(checkpoint.get("baseline_evidence_path") or ""),
                "result_sha256": str(
                    checkpoint.get("baseline_evidence_sha256") or ""
                ),
                "evidence_path": str(
                    checkpoint.get("baseline_evidence_path") or ""
                ),
                "evidence_sha256": str(
                    checkpoint.get("baseline_evidence_sha256") or ""
                ),
                "resource_avg": resource_avg,
                "resource_stats": resource_stats,
                "formal_qps": float(formal_qps),
                "formal_qps_source": "formal_benchmark_db_qps",
            }
        result_path = Path(
            str(startup_baseline_reuse_cfg.get("point_result_path") or "")
        )
        evidence_path = Path(
            str(startup_baseline_reuse_cfg.get("reclassification_evidence_path") or "")
        )
        expected_result_sha = str(
            startup_baseline_reuse_cfg.get("point_result_sha256") or ""
        )
        expected_evidence_sha = str(
            startup_baseline_reuse_cfg.get("reclassification_evidence_sha256") or ""
        )

        def _exact_sha256(path: Path, expected: str, label: str) -> None:
            if not path.is_file():
                raise RuntimeError(f"reusable startup baseline is missing {label}: {path}")
            actual = hashlib.sha256(path.read_bytes()).hexdigest()
            if not expected or actual != expected:
                raise RuntimeError(
                    f"reusable startup baseline {label} SHA mismatch: {actual} != {expected}"
                )

        _exact_sha256(result_path, expected_result_sha, "point result")
        _exact_sha256(evidence_path, expected_evidence_sha, "reclassification evidence")
        result = json.loads(result_path.read_text(encoding="utf-8"))
        evidence = json.loads(evidence_path.read_text(encoding="utf-8"))
        measurement = result.get("measurement") or {}
        if (
            result.get("status") != "complete"
            or result.get("point_id") != evidence.get("point_id")
            or evidence.get("classification") != "formal_startup_baseline"
            or evidence.get("point_result_sha256") != expected_result_sha
            or evidence.get("candidate_replay_budget_after") != 0
            or evidence.get("accepted_budget_after") != 0
            or evidence.get("startup_baseline_count_after") != 1
            or measurement.get("correctness_passed") is not True
            or (measurement.get("resource_stability") or {}).get("passed") is not True
            or result.get("oom_killed") is not False
            or int(result.get("database_restart_count") or 0) != 0
        ):
            raise RuntimeError("reusable startup baseline failed formal validity checks")
        result_params = result.get("cost_parameters") or {}
        if set(result_params) != set(p_real) or any(
            float(result_params[name]) != float(p_real[name]) for name in p_real
        ):
            raise RuntimeError("reusable startup baseline is not the exact p_real vector")
        protocol = cfg.get("formal_outer_protocol") or {}
        expected_global_replays = int(
            protocol.get(
                "global_replay_ordinal_at_binding",
                protocol.get("global_replay_count_start", 15),
            )
        )
        expected_search_replays = int(
            protocol.get("formal_search_replay_count_start", 0)
        )
        expected_accepted = int(
            protocol.get("formal_search_accepted_count_start", 0)
        )
        expected_startup_baselines = int(
            startup_baseline_reuse_cfg.get("startup_baseline_count_before_restart", 1)
        )
        counter_expectations = (
            (
                protocol.get("global_replay_counter_path"),
                expected_global_replays,
                "global",
            ),
            (
                protocol.get("formal_search_replay_counter_path"),
                expected_search_replays,
                "candidate replay",
            ),
            (
                protocol.get("formal_search_accepted_counter_path"),
                expected_accepted,
                "accepted",
            ),
            (
                protocol.get("formal_startup_baseline_counter_path"),
                expected_startup_baselines,
                "startup baseline",
            ),
        )
        for raw_path, expected, label in counter_expectations:
            counter_path = Path(str(raw_path or ""))
            if (
                not counter_path.is_file()
                or int(counter_path.read_text(encoding="utf-8").strip()) != expected
            ):
                raise RuntimeError(
                    f"reusable startup baseline {label} counter is not {expected}"
                )
        derived_path = Path(str(measurement.get("derived_resource_samples_path") or ""))
        _exact_sha256(
            derived_path,
            str(measurement.get("derived_resource_samples_sha256") or ""),
            "derived resource samples",
        )
        derived_rows = [
            json.loads(line)
            for line in derived_path.read_text(encoding="utf-8").splitlines()
            if line.strip()
        ]
        normalized_samples = normalize_derived_resource_samples(derived_rows)
        formal_resource = summarize_resource_samples(
            normalized_samples,
            measurement.get("resource_denominators") or {},
        )
        aggregate = formal_resource["aggregate"]
        formal_db_qps = _to_float_or_none(measurement.get("db_qps"))
        expected_db_qps_source = str(
            startup_baseline_reuse_cfg.get("db_qps_source")
            or (
                (final_eval_cfg.get("feedback_loop") or {}).get(
                    "db_qps_source"
                )
            )
            or ""
        )
        if expected_db_qps_source != "formal_benchmark_db_qps":
            raise RuntimeError(
                "reusable startup baseline db_qps_source must be "
                "formal_benchmark_db_qps"
            )
        if formal_db_qps is None or formal_db_qps <= 0.0:
            raise RuntimeError(
                "reusable startup baseline lacks positive formal measurement.db_qps"
            )
        db_qps_evidence_path_raw = str(
            measurement.get("db_qps_evidence_path") or ""
        )
        db_qps_evidence_sha256 = str(
            measurement.get("db_qps_evidence_sha256") or ""
        )
        if db_qps_evidence_path_raw or db_qps_evidence_sha256:
            db_qps_evidence_path = Path(db_qps_evidence_path_raw)
            _exact_sha256(
                db_qps_evidence_path,
                db_qps_evidence_sha256,
                "formal DB QPS evidence",
            )
        latency = measurement.get("latency_ms") or {}
        benchmark = {
            "ap_qps": float(measurement["qps"]),
            "client_completion_qps": float(measurement["qps"]),
            "db_qps": formal_db_qps,
            "formal_qps": formal_db_qps,
            "formal_qps_source": expected_db_qps_source,
            "db_qps_source": expected_db_qps_source,
            "db_qps_evidence_path": db_qps_evidence_path_raw or None,
            "db_qps_evidence_sha256": db_qps_evidence_sha256 or None,
            "query_count": int(measurement["query_count"]),
            "latency_p90": latency.get("p90"),
            "latency_p95": latency.get("p95"),
            "latency_p99": latency.get("p99"),
        }
        benchmark_latency = {
            "all_p90_avg": latency.get("p90"),
            "all_p95_avg": latency.get("p95"),
            "all_p99_avg": latency.get("p99"),
        }
        return {
            "result_path": str(result_path),
            "result_sha256": expected_result_sha,
            "evidence_path": str(evidence_path),
            "evidence_sha256": expected_evidence_sha,
            "resource_avg": {
                "cpu": float(aggregate["cpu_utilization"]) * float(capability["cpu"]),
                "memory": float(aggregate["memory_working_set_bytes"]),
                "io": float(aggregate["total_bps"]),
            },
            "resource_stats": {
                "formal_pg_resource": formal_resource,
                "benchmark": benchmark,
                "benchmark_latency": benchmark_latency,
                "candidate_measurement_protocol": {
                    "point_id": result["point_id"],
                    "correctness_passed": True,
                    "stable": True,
                    "effective_measurement_seconds": measurement.get(
                        "effective_measurement_seconds"
                    ),
                    "error_rate": measurement.get("error_rate"),
                    "oom_killed": False,
                    "database_restart_count": 0,
                },
                "formal_qps": formal_db_qps,
                "formal_qps_source": expected_db_qps_source,
                "workload_output": "reused immutable formal startup baseline",
            },
            "formal_qps": formal_db_qps,
            "formal_qps_source": expected_db_qps_source,
        }

    try:
        baseline_start_ts = time.time()
        baseline_sampled_concurrency: Dict[str, Any] = {}
        try:
            if partial_startup_resume_checkpoint is None:
                _run_external_replay_safe_guard("before_baseline")
                _run_pre_benchmark_recovery("baseline")
                apply_params_via_alter_system(_with_fixed_params(p_real))
                _run_validation_warmup("baseline", p_real)
                _run_external_replay_safe_guard("before_baseline_measurement")
            if startup_baseline_reuse_enabled:
                reused_baseline = _load_reusable_startup_baseline()
                baseline_runtime_resource_avg = copy.deepcopy(
                    reused_baseline["resource_avg"]
                )
                baseline_runtime_resource_stats = copy.deepcopy(
                    reused_baseline["resource_stats"]
                )
                baseline_db_view_summary = {
                    "source": "reused_immutable_formal_startup_baseline",
                    "sample_count": 0,
                    "db_qps": float(reused_baseline["formal_qps"]),
                    "formal_qps": float(reused_baseline["formal_qps"]),
                    "db_qps_source": reused_baseline["formal_qps_source"],
                    "formal_qps_source": reused_baseline["formal_qps_source"],
                }
                baseline_run = {
                    "start_ts": baseline_start_ts,
                    "end_ts": time.time(),
                    "benchmark": copy.deepcopy(
                        baseline_runtime_resource_stats["benchmark"]
                    ),
                    "benchmark_latency": copy.deepcopy(
                        baseline_runtime_resource_stats["benchmark_latency"]
                    ),
                    "workload_output": baseline_runtime_resource_stats[
                        "workload_output"
                    ],
                    "db_view_monitor": copy.deepcopy(baseline_db_view_summary),
                    "resource_avg": copy.deepcopy(baseline_runtime_resource_avg),
                    "resource_stats": copy.deepcopy(baseline_runtime_resource_stats),
                    "startup_baseline_reuse": copy.deepcopy(reused_baseline),
                }
                baseline_benchmark = copy.deepcopy(baseline_run["benchmark"])
                baseline_benchmark_latency = copy.deepcopy(
                    baseline_run["benchmark_latency"]
                )
                main_logger.log_struct(
                    {
                        "event": "startup_baseline_reused",
                        "point_result_path": reused_baseline["result_path"],
                        "point_result_sha256": reused_baseline["result_sha256"],
                        "reclassification_evidence_path": reused_baseline[
                            "evidence_path"
                        ],
                        "reclassification_evidence_sha256": reused_baseline[
                            "evidence_sha256"
                        ],
                        "candidate_replay_budget_consumed": False,
                    }
                )
                print(
                    "[Baseline] Reusing immutable formal startup baseline; "
                    "candidate replay budget remains zero.",
                    flush=True,
                )
            else:
                _reset_pg_stat_statements_for_workload("Baseline")
            if (
                not startup_baseline_reuse_enabled
                and metrics_source == "plan-estimator"
                and plan_estimator_bootstrap_once
            ):
                baseline_monitor_start = time.time()
                bootstrap_runtime_source = _plan_estimator_bootstrap_runtime_source(
                    final_eval_runtime_source
                )
                monitor_result, baseline_db_view_summary = _run_with_db_view_monitor(
                    "baseline",
                    lambda: _dispatch_plan_estimator_bootstrap_monitor(
                        bootstrap_runtime_source,
                        docker_monitor=lambda: monitor_resources_from_docker_runtime_workload(
                            workload_cmd=baseline_workload_cmd,
                            container_name=docker_rt_container,
                            interval_s=docker_rt_interval,
                            warmup_s=docker_rt_warmup,
                            memory_mode=docker_rt_memory_mode,
                            io_scope=docker_rt_io_scope,
                            max_runtime_s=workload_timeout_sec,
                        ),
                        vm_monitor=lambda: monitor_resources_from_vm_runtime_workload(
                            workload_cmd=baseline_workload_cmd,
                            vm_host=vm_rt_host,
                            ssh_target=vm_rt_ssh_target,
                            ssh_user=vm_rt_ssh_user,
                            ssh_port=vm_rt_ssh_port,
                            ssh_identity_file=vm_rt_ssh_identity_file,
                            interval_s=vm_rt_interval,
                            warmup_s=vm_rt_warmup,
                            connect_timeout_s=vm_rt_connect_timeout,
                            disk_devices=vm_rt_disk_devices,
                            cpu_mode=vm_rt_cpu_mode,
                            io_mode=vm_rt_io_mode,
                            memory_mode=vm_rt_memory_mode,
                            max_runtime_s=workload_timeout_sec,
                        ),
                    ),
                )
                baseline_runtime_resource_avg, baseline_runtime_resource_stats = monitor_result
                baseline_run = {
                    "start_ts": float(
                        (baseline_db_view_summary.get("window") or [baseline_monitor_start, time.time()])[0]
                    ),
                    "end_ts": float(
                        (baseline_db_view_summary.get("window") or [baseline_monitor_start, time.time()])[-1]
                    ),
                    "benchmark": dict(baseline_runtime_resource_stats.get("benchmark") or {}),
                    "benchmark_latency": dict(
                        baseline_runtime_resource_stats.get("benchmark_latency") or {}
                    ),
                    "workload_output": str(
                        baseline_runtime_resource_stats.get("workload_output") or ""
                    ),
                    "db_view_monitor": copy.deepcopy(baseline_db_view_summary),
                    "resource_avg": dict(baseline_runtime_resource_avg),
                    "resource_stats": dict(baseline_runtime_resource_stats),
                }
                baseline_start_ts = float(baseline_run.get("start_ts") or time.time())
                baseline_sampled_concurrency = dict(baseline_run.get("concurrency") or {})
                baseline_benchmark = dict(baseline_run.get("benchmark") or {})
                baseline_benchmark_latency = dict(baseline_run.get("benchmark_latency") or {})
                if baseline_run.get("errors"):
                    main_logger.log_struct(
                        {
                            "event": "baseline_pg_stat_activity_sampling_warning",
                            "dbname": pg_stat_dbname,
                            "errors": baseline_run.get("errors"),
                        }
                    )
            elif not startup_baseline_reuse_enabled and metrics_source == "vm-runtime":
                baseline_monitor_start = time.time()
                monitor_result, baseline_db_view_summary = _run_with_db_view_monitor(
                    "baseline",
                    lambda: monitor_resources_from_vm_runtime_workload(
                        workload_cmd=baseline_workload_cmd,
                        vm_host=vm_rt_host,
                        ssh_target=vm_rt_ssh_target,
                        ssh_user=vm_rt_ssh_user,
                        ssh_port=vm_rt_ssh_port,
                        ssh_identity_file=vm_rt_ssh_identity_file,
                        interval_s=vm_rt_interval,
                        warmup_s=vm_rt_warmup,
                        connect_timeout_s=vm_rt_connect_timeout,
                        disk_devices=vm_rt_disk_devices,
                        cpu_mode=vm_rt_cpu_mode,
                        io_mode=vm_rt_io_mode,
                        memory_mode=vm_rt_memory_mode,
                        max_runtime_s=workload_timeout_sec,
                    ),
                )
                baseline_runtime_resource_avg, baseline_runtime_resource_stats = monitor_result
                baseline_run = {
                    "start_ts": float(
                        (baseline_db_view_summary.get("window") or [baseline_monitor_start, time.time()])[0]
                    ),
                    "end_ts": float(
                        (baseline_db_view_summary.get("window") or [baseline_monitor_start, time.time()])[-1]
                    ),
                    "benchmark": dict(baseline_runtime_resource_stats.get("benchmark") or {}),
                    "benchmark_latency": dict(
                        baseline_runtime_resource_stats.get("benchmark_latency") or {}
                    ),
                    "workload_output": str(
                        baseline_runtime_resource_stats.get("workload_output") or ""
                    ),
                    "db_view_monitor": copy.deepcopy(baseline_db_view_summary),
                }
                baseline_start_ts = float(baseline_run.get("start_ts") or baseline_monitor_start)
                baseline_benchmark = dict(baseline_run.get("benchmark") or {})
                baseline_benchmark_latency = dict(baseline_run.get("benchmark_latency") or {})
            elif not startup_baseline_reuse_enabled:
                baseline_run, _ = _run_with_db_view_monitor(
                    "baseline",
                    lambda: _run_workload_with_pg_concurrency_sampling(
                        dbname=None,
                        command=baseline_workload_cmd,
                    ),
                )
                baseline_run["db_view_monitor"] = copy.deepcopy(
                    getattr(_run_with_db_view_monitor, "last_summary", {}) or {}
                )
                baseline_start_ts = float(baseline_run.get("start_ts") or time.time())
                baseline_benchmark = dict(baseline_run.get("benchmark") or {})
                baseline_benchmark_latency = dict(baseline_run.get("benchmark_latency") or {})
        finally:
            baseline_end_ts = time.time()
            if partial_startup_resume_checkpoint is not None:
                baseline_all_sql = copy.deepcopy(
                    partial_startup_resume_checkpoint.get("baseline_top_sql") or []
                )
            elif metrics_source == "plan-estimator" and collected_replay_sql:
                baseline_all_sql = list(collected_replay_sql)
            else:
                baseline_all_sql = _fetch_top_slowest_sql(dbname=pg_stat_dbname, limit=None)
            baseline_top_sql = (
                copy.deepcopy(
                    partial_startup_resume_checkpoint.get("baseline_top_sql") or []
                )[:20]
                if partial_startup_resume_checkpoint is not None
                else _fetch_top_slowest_sql(dbname=pg_stat_dbname, limit=20)
            )
            if metrics_source == "plan-estimator" and plan_estimator_bootstrap_once and not baseline_all_sql:
                raise RuntimeError(
                    "Plan-estimator baseline captured no benchmark SQL from pg_stat_statements. "
                    "The workload may have failed, returned too early, or only internal sampling SQL was recorded."
                )
            baseline_plan_candidates = (
                copy.deepcopy(baseline_top_sql)
                if partial_startup_resume_checkpoint is not None
                else _fetch_top_slowest_sql(
                    dbname=pg_stat_dbname,
                    limit=plan_capture_candidate_limit if plan_capture_enabled else 20,
                )
            )
            baseline_plan_candidates = _merge_plan_query_candidates(
                baseline_plan_candidates,
                baseline_top_sql,
                baseline_all_sql,
            )
            tracked_plan_queries = _select_plan_queries(
                baseline_plan_candidates,
                limit=plan_capture_limit if plan_capture_enabled else 20,
                coverage_pct=plan_capture_coverage_pct,
                min_queries=plan_capture_min_queries,
                changed_keys=tracked_plan_change_keys,
                slow_mean_ms=plan_capture_slow_mean_ms,
            )
            if partial_startup_resume_checkpoint is not None:
                plan_estimator_workload_profile = copy.deepcopy(
                    partial_startup_resume_checkpoint.get(
                        "baseline_workload_profile"
                    )
                    or {}
                )
                plan_estimator_workload_profile["benchmark"] = dict(
                    baseline_benchmark
                )
                plan_estimator_workload_profile["benchmark_latency"] = dict(
                    baseline_benchmark_latency
                )
                plan_estimator_workload_profile["runtime_resource_raw"] = dict(
                    baseline_runtime_resource_avg
                )
                plan_estimator_workload_profile["runtime_resource_stats"] = dict(
                    baseline_runtime_resource_stats
                )
                plan_estimator_workload_profile[
                    "baseline_runtime_memory_bytes"
                ] = float(baseline_runtime_resource_avg.get("memory", 0.0) or 0.0)
                plan_estimator_workload_profile[
                    "source"
                ] = "sealed_partial_round_checkpoint"
            elif metrics_source == "plan-estimator" and plan_estimator_bootstrap_once:
                plan_estimator_workload_profile = _collect_plan_estimator_workload_profile(
                    dbname=pg_stat_dbname,
                    start_ts=baseline_start_ts,
                    end_ts=baseline_end_ts,
                    all_sql=baseline_all_sql,
                    sampled_concurrency=baseline_sampled_concurrency,
                    hybench_runtime=hybench_runtime_cfg,
                )
                if baseline_benchmark:
                    plan_estimator_workload_profile["benchmark"] = dict(baseline_benchmark)
                if baseline_benchmark_latency:
                    plan_estimator_workload_profile["benchmark_latency"] = dict(baseline_benchmark_latency)
                if baseline_runtime_resource_avg:
                    plan_estimator_workload_profile["runtime_resource_raw"] = dict(baseline_runtime_resource_avg)
                    plan_estimator_workload_profile["baseline_runtime_memory_bytes"] = float(
                        baseline_runtime_resource_avg.get("memory", 0.0) or 0.0
                    )
                if baseline_runtime_resource_stats:
                    plan_estimator_workload_profile["runtime_resource_stats"] = dict(baseline_runtime_resource_stats)
            if partial_startup_resume_checkpoint is None:
                _run_post_benchmark_cleanup("baseline")
        baseline_plan_samples = (
            copy.deepcopy(
                partial_startup_resume_checkpoint.get("baseline_plan_samples") or []
            )
            if partial_startup_resume_checkpoint is not None
            else _capture_plan_signatures(
                tracked_plan_queries if tracked_plan_queries else baseline_top_sql,
                dbname=pg_stat_dbname,
                limit=plan_capture_limit if plan_capture_enabled else 10,
            )
        )
        previous_iteration_plan_samples = list(baseline_plan_samples)
        baseline_plan_capture_file = (
            _dump_plan_capture(
                baseline_plan_samples,
                label="baseline",
                output_dir=plan_capture_output_dir,
            )
            if plan_capture_enabled
            else None
        )
        main_logger.log_struct(
            {
                "event": "baseline_top_sql",
                "dbname": pg_stat_dbname,
                "window": [baseline_start_ts, baseline_end_ts],
                "all_sql_count": len(baseline_all_sql),
                "all_sql_top10": baseline_all_sql[:10],
                "collected_sql_event_count": collected_sql_summary.get("sql_event_count"),
                "collected_replay_sql_count": len(collected_replay_sql),
                "replay_queries_file": collected_sql_summary.get("replay_queries_file"),
                "plan_estimator_workload_profile": plan_estimator_workload_profile,
                "baseline_benchmark": baseline_benchmark,
                "baseline_benchmark_latency": baseline_benchmark_latency,
                "workload_output": baseline_run.get("workload_output") if isinstance(baseline_run, dict) else None,
                "baseline_db_view_monitor": baseline_run.get("db_view_monitor") if isinstance(baseline_run, dict) else {},
                "baseline_runtime_resource_avg": baseline_runtime_resource_avg,
                "baseline_runtime_resource_stats": baseline_runtime_resource_stats,
                "auto_explain_sql_collect": {
                    "sql_event_count": collected_sql_summary.get("sql_event_count"),
                    "distinct_sql_fingerprint_count": collected_sql_summary.get("distinct_sql_fingerprint_count"),
                    "distinct_sql_text_count": collected_sql_summary.get("distinct_sql_text_count"),
                    "replay_sql_count": len(collected_replay_sql),
                    "top_sql_by_count": collected_sql_summary.get("top_sql_by_count"),
                    "replay_queries_file": collected_sql_summary.get("replay_queries_file"),
                },
                "top": baseline_top_sql,
                "tracked_plan_query_count": len(tracked_plan_queries),
                "tracked_plan_queries_top10": list(tracked_plan_queries[:10]),
                "plan_hashes": _plan_log_view(baseline_plan_samples),
                "plan_capture_file": baseline_plan_capture_file,
                "plan_capture_count": len(baseline_plan_samples),
            }
        )
        baseline_qps = _to_float_or_none(
            baseline_benchmark.get("ap_qps") or baseline_benchmark.get("xp_qps")
        )
        if formal_pg_resource_enabled:
            formal_baseline_qps, formal_baseline_qps_source = _resolve_formal_db_qps(
                source=formal_pg_resource_cfg.get("db_qps_source"),
                benchmark_metrics=baseline_benchmark,
                db_view_monitor=baseline_db_view_summary,
            )
            baseline_db_view_summary["formal_qps"] = float(formal_baseline_qps)
            baseline_db_view_summary["db_qps"] = float(formal_baseline_qps)
            baseline_db_view_summary["formal_qps_source"] = formal_baseline_qps_source
            baseline_db_view_summary["db_qps_source"] = formal_baseline_qps_source
        baseline_tps = _to_float_or_none(
            baseline_benchmark.get("tp_tps") or baseline_benchmark.get("xp_tps")
        )
        baseline_p90 = _to_float_or_none(
            baseline_benchmark.get("latency_p90") or baseline_benchmark_latency.get("all_p90_avg")
        )
        baseline_p95 = _to_float_or_none(
            baseline_benchmark.get("latency_p95") or baseline_benchmark_latency.get("all_p95_avg")
        )
        baseline_p99 = _to_float_or_none(
            baseline_benchmark.get("latency_p99") or baseline_benchmark_latency.get("all_p99_avg")
        )
        if any(value is not None for value in (baseline_qps, baseline_tps, baseline_p90, baseline_p95, baseline_p99)):
            print("\nBaseline :")
            if formal_pg_resource_enabled:
                print(
                    "  DB QPS: "
                    f"{float(baseline_db_view_summary['db_qps']):.4f} "
                    f"(source={baseline_db_view_summary['db_qps_source']})"
                )
            if baseline_qps is not None:
                print(f"  Workload QPS (audit only): {baseline_qps:.4f}")
            if baseline_tps is not None:
                print(f"  TPS: {baseline_tps:.4f}")
            if baseline_p90 is not None:
                print(f"  P90: {baseline_p90:.4f} ms")
            if baseline_p95 is not None:
                print(f"  P95: {baseline_p95:.4f} ms")
            if baseline_p99 is not None:
                print(f"  P99: {baseline_p99:.4f} ms")
        if baseline_runtime_resource_avg and baseline_runtime_resource_stats:
            baseline_runtime_normalized, baseline_runtime_util = _normalize_runtime_resource_avg(
                baseline_runtime_resource_avg,
                baseline_runtime_resource_stats,
            )
            baseline_correction_state["actual_baseline"] = copy.deepcopy(baseline_runtime_normalized)
            print("\nBaseline :")
            baseline_resource_rows = [
                ("cpu", "CPU"),
                ("memory", "Memory"),
                ("io", "IO"),
            ]
            if "io" not in capability and ("io_read" in capability or "io_write" in capability):
                baseline_resource_rows = [
                    ("cpu", "CPU"),
                    ("memory", "Memory"),
                    ("io_read", "IO Read"),
                    ("io_write", "IO Write"),
                ]
            for key, label in baseline_resource_rows:
                print(
                    f"  {label:<12} value={float(baseline_runtime_normalized.get(key, 0.0)):.4f} "
                    f"util={float(baseline_runtime_util.get(key, 0.0)):.2f}%"
                )
            main_logger.log_struct(
                {
                    "event": "baseline_runtime_resource_summary",
                    "window": [baseline_start_ts, baseline_end_ts],
                    "resource_raw": baseline_runtime_resource_avg,
                    "resource_stats": baseline_runtime_resource_stats,
                    "resource_normalized": baseline_runtime_normalized,
                    "utilization_pct": baseline_runtime_util,
                }
            )

            feedback_cfg_for_baseline_gate = (
                final_eval_cfg.get("feedback_loop")
                or cfg.get("final_feedback_loop")
                or {}
            )
            if not isinstance(feedback_cfg_for_baseline_gate, dict):
                feedback_cfg_for_baseline_gate = {}
            resource_goal_for_baseline_gate = (
                feedback_cfg_for_baseline_gate.get("resource_iteration_goal")
                or {}
            )
            if not isinstance(resource_goal_for_baseline_gate, dict):
                resource_goal_for_baseline_gate = {}
            strong_cfg_for_baseline_gate = (
                resource_goal_for_baseline_gate.get("strong_constraints")
                or {}
            )
            if not isinstance(strong_cfg_for_baseline_gate, dict):
                strong_cfg_for_baseline_gate = {}
            baseline_gate_target_resource = str(
                resource_goal_for_baseline_gate.get("bottleneck_resource", "")
            ).strip().lower()
            none_baseline_gate_enabled = (
                baseline_gate_target_resource == "none"
                and _to_bool(strong_cfg_for_baseline_gate.get("enabled", False), False)
                and _to_bool(
                    strong_cfg_for_baseline_gate.get(
                        "none_require_all_initial_resources_in_range",
                        True,
                    ),
                    True,
                )
            )
            single_bottleneck_baseline_gate_enabled = (
                baseline_gate_target_resource in {"cpu", "memory", "io"}
                and _to_bool(strong_cfg_for_baseline_gate.get("enabled", False), False)
                and _to_bool(
                    strong_cfg_for_baseline_gate.get(
                        "bottleneck_require_single_initial_bottleneck",
                        False,
                    ),
                    False,
                )
            )
            baseline_gate_enabled = bool(
                none_baseline_gate_enabled
                or single_bottleneck_baseline_gate_enabled
            )
            if baseline_gate_enabled:
                baseline_gate_min_pct = max(
                    0.0,
                    float(
                        _to_float_or_none(
                            strong_cfg_for_baseline_gate.get(
                                "none_initial_util_min_pct",
                                20.0,
                            )
                        )
                        or 20.0
                    ),
                )
                baseline_gate_max_pct = max(
                    baseline_gate_min_pct,
                    float(
                        _to_float_or_none(
                            strong_cfg_for_baseline_gate.get(
                                "none_initial_util_max_pct",
                                30.0,
                            )
                        )
                        or 30.0
                    ),
                )
                baseline_gate_checks = []
                if none_baseline_gate_enabled:
                    per_resource_ranges = strong_cfg_for_baseline_gate.get(
                        "none_initial_resource_ranges"
                    ) or {}
                    io_uses_normalized = _to_bool(
                        strong_cfg_for_baseline_gate.get(
                            "io_good_range_uses_normalized_mib_s",
                            False,
                        ),
                        False,
                    )
                    for resource_name in ("cpu", "memory", "io"):
                        bounds = (
                            per_resource_ranges.get(resource_name)
                            if isinstance(per_resource_ranges, dict)
                            else None
                        )
                        if isinstance(bounds, (list, tuple)) and len(bounds) == 2:
                            required_min = _to_float_or_none(bounds[0])
                            required_max = _to_float_or_none(bounds[1])
                        else:
                            required_min = baseline_gate_min_pct
                            required_max = baseline_gate_max_pct
                        metric_source = "utilization_pct"
                        metric_value = _to_float_or_none(
                            baseline_runtime_util.get(resource_name)
                        )
                        if resource_name == "io" and io_uses_normalized:
                            metric_source = "resource_normalized_mib_s"
                            metric_value = _to_float_or_none(
                                baseline_runtime_normalized.get("io")
                            )
                        passed = (
                            metric_value is not None
                            and required_min is not None
                            and required_max is not None
                            and float(required_min)
                            <= float(metric_value)
                            <= float(required_max)
                        )
                        baseline_gate_checks.append(
                            {
                                "resource": resource_name,
                                "metric_source": metric_source,
                                "metric_value": metric_value,
                                "required_min": required_min,
                                "required_max": required_max,
                                "passed": bool(passed),
                            }
                        )
                else:
                    _, baseline_gate_checks = _re_evaluate_single_bottleneck_gate(
                        baseline_runtime_util,
                        baseline_gate_target_resource,
                        strong_cfg_for_baseline_gate,
                    )
                baseline_gate_passed = all(
                    item.get("passed") for item in baseline_gate_checks
                )
                main_logger.log_struct(
                    {
                        "event": "baseline_strong_constraint_gate",
                        "target_resource": baseline_gate_target_resource,
                        "gate_type": (
                            "none_baseline_ranges"
                            if none_baseline_gate_enabled
                            else "exactly_one_bottleneck"
                        ),
                        "passed": bool(baseline_gate_passed),
                        "checks": baseline_gate_checks,
                        "action": (
                            "continue_to_candidate_search"
                            if baseline_gate_passed
                            else "abort_before_candidate_search"
                        ),
                    }
                )
                if not baseline_gate_passed:
                    failed = [
                        item
                        for item in baseline_gate_checks
                        if not item.get("passed")
                    ]
                    if none_baseline_gate_enabled:
                        baseline_strong_gate_failure = RuntimeError(
                            "Bonect strong none baseline gate failed before candidate "
                            f"search: failed={failed}"
                        )
                    else:
                        baseline_strong_gate_failure = RuntimeError(
                            "Bonect single-bottleneck baseline gate failed before candidate "
                            f"search: target={baseline_gate_target_resource}, failed={failed}"
                        )

            bottleneck_calibration_cfg = cfg.get("bottleneck_calibration") or {}
            if _to_bool(bottleneck_calibration_cfg.get("enabled", False), False):
                resource_cfg = bottleneck_calibration_cfg.get(
                    "resources",
                    bottleneck_calibration_cfg.get(
                        "resource",
                        bottleneck_calibration_cfg.get("bottleneck_resource", "io"),
                    ),
                )
                if isinstance(resource_cfg, str):
                    bottleneck_resources = [
                        item.strip() for item in resource_cfg.split(",") if item.strip()
                    ]
                elif isinstance(resource_cfg, list):
                    bottleneck_resources = [str(item).strip() for item in resource_cfg if str(item).strip()]
                else:
                    bottleneck_resources = ["io"]

                min_util_pct = float(
                    _to_float_or_none(
                        bottleneck_calibration_cfg.get(
                            "min_util_pct",
                            bottleneck_calibration_cfg.get("threshold_util_pct", 80.0),
                        )
                    )
                    or 80.0
                )
                target_util_pct = float(
                    _to_float_or_none(
                        bottleneck_calibration_cfg.get(
                            "target_util_pct",
                            bottleneck_calibration_cfg.get("target_util", 95.0),
                        )
                    )
                    or 95.0
                )
                min_capability = max(
                    0.0,
                    float(_to_float_or_none(bottleneck_calibration_cfg.get("min_capability")) or 0.0),
                )
                expand_overloaded_non_targets = _to_bool(
                    bottleneck_calibration_cfg.get("expand_overloaded_non_targets", True),
                    True,
                )
                non_target_overload_pct = float(
                    _to_float_or_none(
                        bottleneck_calibration_cfg.get("non_target_overload_util_pct", 100.0)
                    )
                    or 100.0
                )
                non_target_target_pct = float(
                    _to_float_or_none(
                        bottleneck_calibration_cfg.get("non_target_target_util_pct", 80.0)
                    )
                    or 80.0
                )
                write_back = _to_bool(bottleneck_calibration_cfg.get("write_back", False), False)
                backup = _to_bool(bottleneck_calibration_cfg.get("backup", True), True)
                stop_on_vm_profile_reapply_required = _to_bool(
                    bottleneck_calibration_cfg.get("stop_on_vm_profile_reapply_required", True),
                    True,
                )
                target_ratio = max(target_util_pct / 100.0, 1e-9)
                non_target_target_ratio = max(non_target_target_pct / 100.0, 1e-9)
                calibration_updates: Dict[str, Dict[str, float]] = {}
                bottleneck_resource_set = set(bottleneck_resources)

                for resource_name in bottleneck_resources:
                    if resource_name not in capability:
                        print(
                            f"[Bottleneck Calibration] skip {resource_name}: not in capability",
                            flush=True,
                        )
                        continue
                    observed = float(baseline_runtime_normalized.get(resource_name, 0.0) or 0.0)
                    old_cap = float(capability.get(resource_name, 0.0) or 0.0)
                    if observed <= 0.0 or old_cap <= 0.0:
                        print(
                            f"[Bottleneck Calibration] skip {resource_name}: "
                            f"observed={observed:.4f}, capability={old_cap:.4f}",
                            flush=True,
                        )
                        continue
                    old_util_pct = observed / old_cap * 100.0
                    if old_util_pct >= 100.0:
                        new_cap = max(observed / target_ratio, min_capability)
                        if new_cap <= old_cap:
                            print(
                                f"[Bottleneck Calibration] {resource_name} already exceeds capability; "
                                f"computed cap {new_cap:.4f} <= old cap {old_cap:.4f}",
                                flush=True,
                            )
                            continue
                        capability[resource_name] = new_cap
                        calibration_updates[resource_name] = {
                            "observed": observed,
                            "old_capability": old_cap,
                            "new_capability": new_cap,
                            "old_util_pct": old_util_pct,
                            "new_util_pct": observed / new_cap * 100.0 if new_cap > 0 else 0.0,
                        }
                        continue
                    if old_util_pct >= min_util_pct:
                        print(
                            f"[Bottleneck Calibration] {resource_name} already near bottleneck: "
                            f"value={observed:.4f}, cap={old_cap:.4f}, util={old_util_pct:.2f}%",
                            flush=True,
                        )
                        continue

                    new_cap = max(observed / target_ratio, min_capability)
                    # This strategy constructs a bottleneck only by lowering the
                    # capability ceiling; it never raises an existing limit.
                    if new_cap >= old_cap:
                        print(
                            f"[Bottleneck Calibration] skip {resource_name}: "
                            f"computed cap {new_cap:.4f} >= old cap {old_cap:.4f}",
                            flush=True,
                        )
                        continue
                    capability[resource_name] = new_cap
                    calibration_updates[resource_name] = {
                        "observed": observed,
                        "old_capability": old_cap,
                        "new_capability": new_cap,
                        "old_util_pct": old_util_pct,
                        "new_util_pct": observed / new_cap * 100.0 if new_cap > 0 else 0.0,
                    }

                if expand_overloaded_non_targets:
                    for resource_name in list(capability.keys()):
                        if resource_name in bottleneck_resource_set:
                            continue
                        observed = float(baseline_runtime_normalized.get(resource_name, 0.0) or 0.0)
                        old_cap = float(capability.get(resource_name, 0.0) or 0.0)
                        if observed <= 0.0 or old_cap <= 0.0:
                            continue
                        old_util_pct = observed / old_cap * 100.0
                        if old_util_pct <= non_target_overload_pct:
                            continue
                        new_cap = max(observed / non_target_target_ratio, min_capability)
                        if new_cap <= old_cap:
                            continue
                        capability[resource_name] = new_cap
                        calibration_updates[resource_name] = {
                            "observed": observed,
                            "old_capability": old_cap,
                            "new_capability": new_cap,
                            "old_util_pct": old_util_pct,
                            "new_util_pct": observed / new_cap * 100.0 if new_cap > 0 else 0.0,
                            "reason": "expand_overloaded_non_target",
                        }

                if calibration_updates:
                    cfg.setdefault("capability", {})
                    for resource_name, update in calibration_updates.items():
                        cfg["capability"][resource_name] = update["new_capability"]
                        baseline_runtime_util[resource_name] = update["new_util_pct"]

                    vm_resource_cfg = cfg.setdefault("vm_resource", {})
                    vm_resource_updates: Dict[str, Any] = {}
                    for resource_name, update in calibration_updates.items():
                        old_cap = float(update.get("old_capability", 0.0) or 0.0)
                        new_cap = float(update.get("new_capability", 0.0) or 0.0)
                        if old_cap <= 0.0 or new_cap <= 0.0:
                            continue
                        if resource_name == "cpu":
                            old_vm_cpu = float(vm_resource_cfg.get("cpu", 0.0) or 0.0)
                            headroom = old_cap / old_vm_cpu if old_vm_cpu > 0.0 else 1.0
                            recommended_cpu = max(1, int(np.ceil(new_cap / max(headroom, 1e-9))))
                            old_cpu_raw = vm_resource_cfg.get("cpu")
                            if int(float(old_cpu_raw or 0.0)) != recommended_cpu:
                                vm_resource_updates["cpu"] = {
                                    "old": old_cpu_raw,
                                    "new": recommended_cpu,
                                }
                                vm_resource_cfg["cpu"] = recommended_cpu
                        elif resource_name == "memory":
                            old_vm_memory = float(vm_resource_cfg.get("memory_gb", 0.0) or 0.0)
                            headroom = old_cap / old_vm_memory if old_vm_memory > 0.0 else 1.0
                            recommended_memory_gb = max(1, int(np.ceil(new_cap / max(headroom, 1e-9))))
                            old_memory_raw = vm_resource_cfg.get("memory_gb")
                            if float(old_memory_raw or 0.0) != float(recommended_memory_gb):
                                vm_resource_updates["memory_gb"] = {
                                    "old": old_memory_raw,
                                    "new": recommended_memory_gb,
                                }
                                vm_resource_cfg["memory_gb"] = recommended_memory_gb
                        elif resource_name == "io":
                            old_read = float(vm_resource_cfg.get("read_mb", 0.0) or 0.0)
                            old_write = float(vm_resource_cfg.get("write_mb", 0.0) or 0.0)
                            old_total = old_read + old_write
                            headroom = old_cap / old_total if old_total > 0.0 else 1.0
                            recommended_total = max(1.0, new_cap / max(headroom, 1e-9))
                            read_ratio = old_read / old_total if old_total > 0.0 else 0.5
                            recommended_read = max(1, int(np.ceil(recommended_total * read_ratio)))
                            recommended_write = max(1, int(np.ceil(recommended_total * (1.0 - read_ratio))))
                            old_read_raw = vm_resource_cfg.get("read_mb")
                            old_write_raw = vm_resource_cfg.get("write_mb")
                            if int(float(old_read_raw or 0.0)) != recommended_read:
                                vm_resource_updates["read_mb"] = {
                                    "old": old_read_raw,
                                    "new": recommended_read,
                                }
                                vm_resource_cfg["read_mb"] = recommended_read
                            if int(float(old_write_raw or 0.0)) != recommended_write:
                                vm_resource_updates["write_mb"] = {
                                    "old": old_write_raw,
                                    "new": recommended_write,
                                }
                                vm_resource_cfg["write_mb"] = recommended_write
                    if vm_resource_updates:
                        vm_resource_cfg["adaptive_source"] = {
                            "method": "baseline_actual_runtime_capability",
                            "requires_vm_profile_reapply": True,
                            "baseline_actual_resource": copy.deepcopy(baseline_runtime_normalized),
                            "capability_updates": copy.deepcopy(calibration_updates),
                            "vm_resource_updates": copy.deepcopy(vm_resource_updates),
                        }

                    print("\n[Bottleneck Calibration] capability  baseline :")
                    for resource_name, update in calibration_updates.items():
                        print(
                            f"  {resource_name}: observed={update['observed']:.4f}, "
                            f"cap {update['old_capability']:.4f} -> {update['new_capability']:.4f}, "
                            f"util {update['old_util_pct']:.2f}% -> {update['new_util_pct']:.2f}%",
                            flush=True,
                        )

                    write_back_error = None
                    backup_path = None
                    if write_back:
                        try:
                            if backup and config_path and os.path.exists(config_path):
                                backup_path = f"{config_path}.bak_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
                                with open(config_path, "r", encoding="utf-8") as src:
                                    with open(backup_path, "w", encoding="utf-8") as dst:
                                        dst.write(src.read())
                            save_optimizer_config(config_path, cfg)
                            print(
                                f"[Bottleneck Calibration] Configuration: {config_path}",
                                flush=True,
                            )
                            if backup_path:
                                print(
                                    f"[Bottleneck Calibration] Configuration: {backup_path}",
                                    flush=True,
                                )
                        except Exception as exc:
                            write_back_error = str(exc)
                            print(
                                f"[WARN] Bottleneck calibration write_back failed: {exc}",
                                flush=True,
                            )

                    main_logger.log_struct(
                        {
                            "event": "bottleneck_calibration",
                            "enabled": True,
                            "resources": bottleneck_resources,
                            "min_util_pct": min_util_pct,
                            "target_util_pct": target_util_pct,
                            "expand_overloaded_non_targets": expand_overloaded_non_targets,
                            "non_target_overload_util_pct": non_target_overload_pct,
                            "non_target_target_util_pct": non_target_target_pct,
                            "updates": calibration_updates,
                            "vm_resource_updates": vm_resource_updates,
                            "write_back": write_back,
                            "backup_path": backup_path,
                            "write_back_error": write_back_error,
                            "capability": copy.deepcopy(capability),
                        }
                    )
                    if vm_resource_updates and stop_on_vm_profile_reapply_required:
                        reapply_event = {
                            "event": "vm_profile_reapply_required",
                            "reason": "baseline_actual_runtime_capability_changed_vm_resource",
                            "required_action": (
                                "stop current optimization, apply vm_resource to the VM, "
                                "restart PostgreSQL, and rerun baseline before tuning"
                            ),
                            "vm_resource": copy.deepcopy(cfg.get("vm_resource") or {}),
                            "vm_resource_updates": copy.deepcopy(vm_resource_updates),
                            "capability_updates": copy.deepcopy(calibration_updates),
                            "config_path": config_path,
                        }
                        main_logger.log_struct(reapply_event)
                        print(
                            "\n[Bottleneck Calibration] VM profile reapply required; "
                            "stop this run, apply vm_resource, and rerun baseline before optimization.",
                            flush=True,
                        )
                        raise SystemExit(75)
                else:
                    main_logger.log_struct(
                        {
                            "event": "bottleneck_calibration",
                            "enabled": True,
                            "resources": bottleneck_resources,
                            "min_util_pct": min_util_pct,
                            "target_util_pct": target_util_pct,
                            "expand_overloaded_non_targets": expand_overloaded_non_targets,
                            "non_target_overload_util_pct": non_target_overload_pct,
                            "non_target_target_util_pct": non_target_target_pct,
                            "updates": {},
                            "capability": copy.deepcopy(capability),
                        }
                    )

        # After bottleneck calibration, re-evaluate single-bottleneck baseline
        # gate with adjusted utilization that may turn a failing raw baseline
        # into a valid calibrated bottleneck.
        if (
            baseline_strong_gate_failure is not None
            and single_bottleneck_baseline_gate_enabled
            and isinstance(strong_cfg_for_baseline_gate, dict)
        ):
            _adj_passed, _adj_checks = _re_evaluate_single_bottleneck_gate(
                baseline_runtime_util=baseline_runtime_util,
                target_resource=baseline_gate_target_resource,
                strong_cfg=strong_cfg_for_baseline_gate,
            )
            main_logger.log_struct({
                "event": "baseline_strong_constraint_gate_recalibrated",
                "target_resource": baseline_gate_target_resource,
                "gate_type": "exactly_one_bottleneck",
                "raw_passed": False,
                "adjusted_passed": bool(_adj_passed),
                "adjusted_checks": _adj_checks,
                "action": (
                    "continue_to_candidate_search"
                    if _adj_passed
                    else "abort_before_candidate_search_adjusted_still_fails"
                ),
            })
            if _adj_passed:
                print(
                    "[Gate Recalibration] Baseline strong-constraint gate passed "
                    "after bottleneck calibration adjustment; clearing gate failure.",
                    flush=True,
                )
                baseline_strong_gate_failure = None
            else:
                print(
                    "[Gate Recalibration] Baseline strong-constraint gate still "
                    "fails after bottleneck calibration adjustment; "
                    "gate failure preserved.",
                    flush=True,
                )

        if (
            metrics_source == "plan-estimator"
            and plan_estimator_bootstrap_once
        ):
            calibration_queries = (
                list(collected_replay_sql)
                if collected_replay_sql
                else list(baseline_top_sql)
            )
            io_calibration_cfg = (plan_estimator_cfg.get("io_calibration") or {})
            if calibration_queries and _to_bool(io_calibration_cfg.get("enabled", False), False):
                try:
                    topn = max(1, _to_int(io_calibration_cfg.get("topn", 20), 20))
                    output_dir = str(
                        io_calibration_cfg.get("output_dir") or os.path.join("history", "io_calibration")
                    )
                    apply_to_runtime = _to_bool(io_calibration_cfg.get("apply_to_runtime", True), True)
                    io_calibrator = IOCalibrator(
                        cfg,
                        pg_host=pg_host,
                        pg_port=pg_port,
                        pg_user=pg_user,
                        pg_dbname=pg_stat_dbname,
                    )
                    calibration_result = io_calibrator.calibrate(
                        calibration_queries,
                        workload_context=plan_estimator_workload_profile,
                        topn=topn,
                    )
                    os.makedirs(output_dir, exist_ok=True)
                    output_file = os.path.join(
                        output_dir,
                        f"io_calibration_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json",
                    )
                    with open(output_file, "w", encoding="utf-8") as fh:
                        json.dump(calibration_result, fh, ensure_ascii=False, indent=2, default=str)

                    recommendations = (
                        (calibration_result.get("recommendations") or {}).get("cache_miss_factors") or {}
                    )
                    applied_factors: Dict[str, float] = {}
                    if apply_to_runtime:
                        io_cfg_runtime = plan_estimator_cfg.setdefault("io", {})
                        miss_cfg_runtime = io_cfg_runtime.setdefault("cache_miss_factors", {})
                        for category, rec in recommendations.items():
                            suggested = _to_float_or_none((rec or {}).get("suggested"))
                            if suggested is None:
                                continue
                            miss_cfg_runtime[category] = float(suggested)
                            applied_factors[category] = float(suggested)

                    global_rec = (calibration_result.get("recommendations") or {}).get("global") or {}
                    print("\nI/O :")
                    print(f"   SQL : {int(calibration_result.get('sample_query_count') or 0)}")
                    read_ratio = _to_float_or_none(global_rec.get("read_ratio_actual_over_estimated"))
                    write_ratio = _to_float_or_none(global_rec.get("write_ratio_actual_over_estimated"))
                    print(
                        "  /: "
                        f"{float(read_ratio if read_ratio is not None else 0.0):.4f}"
                    )
                    print(
                        "  /: "
                        f"{float(write_ratio if write_ratio is not None else 0.0):.4f}"
                    )
                    print(f"  : {output_file}")
                    if applied_factors:
                        print("   cache_miss_factors:")
                        for category in sorted(applied_factors.keys()):
                            print(f"    {category}: {applied_factors[category]:.6f}")

                    main_logger.log_struct(
                        {
                            "event": "io_calibration_summary",
                            "output_file": output_file,
                            "topn": topn,
                            "apply_to_runtime": apply_to_runtime,
                            "global": global_rec,
                            "applied_cache_miss_factors": applied_factors,
                            "recommendations": recommendations,
                            "sample_query_count": calibration_result.get("sample_query_count"),
                            "successful_query_count": calibration_result.get("successful_query_count"),
                            "failed_query_count": calibration_result.get("failed_query_count"),
                        }
                    )
                except Exception as exc:
                    print(f"[WARN] I/O calibration failed: {exc}")
                    main_logger.log_struct(
                        {
                            "event": "io_calibration_error",
                            "error": str(exc),
                        }
                    )
            formula_calibration_cfg = (plan_estimator_cfg.get("formula_calibration") or {})
            if calibration_queries and _to_bool(formula_calibration_cfg.get("enabled", False), False):
                try:
                    topn = max(1, _to_int(formula_calibration_cfg.get("topn", 20), 20))
                    output_dir = str(
                        formula_calibration_cfg.get("output_dir") or os.path.join("history", "formula_calibration")
                    )
                    apply_to_runtime = _to_bool(formula_calibration_cfg.get("apply_to_runtime", True), True)
                    selected_resources = {
                        str(item).strip().lower()
                        for item in (formula_calibration_cfg.get("resources") or ["io", "cpu", "memory"])
                    }
                    calibrator = PlanFormulaCalibrator(
                        cfg,
                        pg_host=pg_host,
                        pg_port=pg_port,
                        pg_user=pg_user,
                        pg_dbname=pg_stat_dbname,
                    )
                    calibration_result = calibrator.calibrate(
                        calibration_queries,
                        workload_context=plan_estimator_workload_profile,
                        topn=topn,
                    )
                    os.makedirs(output_dir, exist_ok=True)
                    output_file = os.path.join(
                        output_dir,
                        f"formula_calibration_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json",
                    )
                    with open(output_file, "w", encoding="utf-8") as fh:
                        json.dump(calibration_result, fh, ensure_ascii=False, indent=2, default=str)

                    recommendations = calibration_result.get("recommendations") or {}
                    applied_updates: Dict[str, Any] = {}

                    if apply_to_runtime:
                        if "io" in selected_resources:
                            io_rec = ((recommendations.get("io") or {}).get("cache_miss_factors") or {})
                            io_cfg_runtime = plan_estimator_cfg.setdefault("io", {})
                            miss_cfg_runtime = io_cfg_runtime.setdefault("cache_miss_factors", {})
                            io_applied: Dict[str, float] = {}
                            for category, rec in io_rec.items():
                                suggested = _to_float_or_none((rec or {}).get("suggested"))
                                if suggested is None:
                                    continue
                                miss_cfg_runtime[category] = float(suggested)
                                io_applied[category] = float(suggested)
                            if io_applied:
                                applied_updates["io"] = {"cache_miss_factors": io_applied}

                        if "cpu" in selected_resources:
                            cpu_rec = ((recommendations.get("cpu") or {}).get("cpu_seconds_per_work") or {})
                            suggested_cpu = _to_float_or_none(cpu_rec.get("suggested"))
                            if suggested_cpu is not None:
                                cpu_cfg_runtime = plan_estimator_cfg.setdefault("cpu", {})
                                cpu_cfg_runtime["cpu_seconds_per_work"] = float(suggested_cpu)
                                applied_updates["cpu"] = {
                                    "cpu_seconds_per_work": float(suggested_cpu),
                                }

                        if "memory" in selected_resources:
                            memory_rec = (recommendations.get("memory") or {})
                            memory_cfg_runtime = plan_estimator_cfg.setdefault("memory", {})
                            memory_applied: Dict[str, float] = {}
                            for field_name, rec in memory_rec.items():
                                suggested = _to_float_or_none((rec or {}).get("suggested"))
                                if suggested is None:
                                    continue
                                memory_cfg_runtime[field_name] = float(suggested)
                                memory_applied[field_name] = float(suggested)
                            if memory_applied:
                                applied_updates["memory"] = memory_applied

                    print("\nFormula:")
                    print(f"   SQL : {int(calibration_result.get('sample_query_count') or 0)}")
                    print(f"  : {output_file}")
                    if (recommendations.get("cpu") or {}).get("cpu_seconds_per_work"):
                        cpu_rec = (recommendations.get("cpu") or {}).get("cpu_seconds_per_work") or {}
                        print(
                            "  CPU actual/estimated: "
                            f"{float(_to_float_or_none(cpu_rec.get('median_actual_over_estimated')) or 0.0):.4f}"
                        )
                    io_global = ((recommendations.get("io") or {}).get("global") or {})
                    if io_global:
                        print(
                            "  IO read actual/estimated: "
                            f"{float(_to_float_or_none(io_global.get('read_ratio_actual_over_estimated')) or 0.0):.4f}"
                        )
                        print(
                            "  IO write actual/estimated: "
                            f"{float(_to_float_or_none(io_global.get('write_ratio_actual_over_estimated')) or 0.0):.4f}"
                        )
                    if applied_updates:
                        print("  Formula:")
                        for resource_name in sorted(applied_updates.keys()):
                            print(f"    {resource_name}: {applied_updates[resource_name]}")

                    main_logger.log_struct(
                        {
                            "event": "plan_formula_calibration_summary",
                            "output_file": output_file,
                            "topn": topn,
                            "apply_to_runtime": apply_to_runtime,
                            "selected_resources": sorted(selected_resources),
                            "recommendations": recommendations,
                            "applied_updates": applied_updates,
                            "sample_query_count": calibration_result.get("sample_query_count"),
                            "successful_query_count": calibration_result.get("successful_query_count"),
                            "failed_query_count": calibration_result.get("failed_query_count"),
                        }
                    )
                except Exception as exc:
                    print(f"[WARN] Formula calibration failed: {exc}")
                    main_logger.log_struct(
                        {
                            "event": "plan_formula_calibration_error",
                            "error": str(exc),
                        }
                    )
    except Exception as exc:
        print(f"[WARN] Baseline top SQL collection failed: {exc}")
        main_logger.log_struct(
            {
                "event": "baseline_top_sql_error",
                "dbname": pg_stat_dbname,
                "error": str(exc),
            }
        )
        if (
            metrics_source == "plan-estimator"
            and plan_estimator_bootstrap_once
            and not baseline_all_sql
        ):
            raise RuntimeError(
                "Plan-estimator baseline workload failed before usable SQL was collected; "
                "aborting instead of optimizing against empty/internal resource estimates."
            ) from exc
        if metrics_source == "vm-runtime" and not baseline_runtime_resource_avg:
            raise RuntimeError(
                "Baseline workload failed before VM runtime resources were collected; "
                "aborting instead of running a duplicate p_real baseline workload. "
                "Fix the baseline workload first, for example by raising statement_timeout "
                "or reducing the AP query set."
            ) from exc

    baseline_resource_band_gate_summary = evaluate_baseline_resource_band_gate(
        utilization_pct=baseline_runtime_util,
        gate_cfg=cfg.get("baseline_resource_band_gate"),
    )
    if baseline_resource_band_gate_summary.get("enabled"):
        baseline_resource_band_gate_passed = bool(
            baseline_resource_band_gate_summary.get("passed")
        )
        main_logger.log_struct(
            {
                "event": "baseline_resource_band_gate",
                **copy.deepcopy(baseline_resource_band_gate_summary),
                "action": (
                    "continue_to_resource_model_retrain"
                    if baseline_resource_band_gate_passed
                    else "abort_before_resource_model_retrain_and_candidate_search"
                ),
            }
        )
        if (
            not baseline_resource_band_gate_passed
            and baseline_resource_band_gate_summary.get("hard_fail")
        ):
            raise RuntimeError(
                "Baseline resource-band gate failed before resource-model retraining "
                "and candidate search: "
                f"failed={baseline_resource_band_gate_summary.get('failures')}"
            )

    if baseline_strong_gate_failure is not None and not baseline_only:
        raise baseline_strong_gate_failure

    if baseline_only:
        _bf_mode = "tp_mixed"
        if baseline_benchmark:
            _has_ap_only_qps = (
                baseline_benchmark.get("ap_qps") is not None
                and baseline_benchmark.get("tp_tps") is None
                and baseline_benchmark.get("xp_tps") is None
            )
            if _has_ap_only_qps:
                _bf_mode = "ap_only"
        baseline_only_measurement_issues = _baseline_only_measurement_issues(
            qps=baseline_qps,
            tps=baseline_tps,
            resource_normalized=baseline_runtime_normalized,
            resource_utilization_pct=baseline_runtime_util,
            benchmark=baseline_benchmark,
            collected_sql=baseline_all_sql,
            benchmark_mode=_bf_mode,
        )
        if baseline_only_measurement_issues:
            main_logger.log_struct(
                {
                    "event": "baseline_only_failed",
                    "issues": baseline_only_measurement_issues,
                    "baseline_qps": baseline_qps,
                    "baseline_tps": baseline_tps,
                    "baseline_resource_normalized": copy.deepcopy(
                        baseline_runtime_normalized
                    ),
                    "baseline_resource_utilization_pct": copy.deepcopy(
                        baseline_runtime_util
                    ),
                    "benchmark": copy.deepcopy(baseline_benchmark),
                    "collected_sql_count": len(baseline_all_sql),
                    "action": "abort_for_supervisor_or_controller_retry",
                }
            )
            raise RuntimeError(
                "Baseline-only measurement is incomplete; refusing to emit a "
                "successful calibration label: "
                + ", ".join(baseline_only_measurement_issues)
            )
        baseline_only_plan_estimation: Dict[str, Any] = {}
        if metrics_source == "plan-estimator" and baseline_all_sql:
            try:
                estimated_raw, estimated_stats, estimated_metadata = estimate_plan_resources(
                    queries=baseline_all_sql,
                    pg_host=pg_host,
                    pg_port=pg_port,
                    pg_user=pg_user,
                    pg_dbname=pg_stat_dbname,
                    estimator_cfg=plan_estimator_cfg,
                    plan_capture_modes=plan_capture_modes,
                    custom_plan_params=plan_capture_custom_plan_params,
                    psql_query_func=lambda sql: _psql_query(sql, dbname=pg_stat_dbname),
                    params=p_real,
                    workload_context=plan_estimator_workload_profile,
                )
                baseline_only_plan_estimation = {
                    "estimated_resource_normalized": _normalize_estimated_resource(
                        estimated_raw,
                        estimated_stats,
                    ),
                    "estimated_resource_raw": estimated_raw,
                    "estimated_resource_stats": estimated_stats,
                    "estimation_metadata": estimated_metadata,
                }
                main_logger.log_struct(
                    {
                        "event": "baseline_only_plan_resource_estimation",
                        **baseline_only_plan_estimation,
                    }
                )
            except Exception as exc:
                baseline_only_plan_estimation = {"error": str(exc)}
                main_logger.log_struct(
                    {
                        "event": "baseline_only_plan_resource_estimation_error",
                        "error": str(exc),
                    }
                )
        main_logger.log_struct(
            {
                "event": "baseline_only_complete",
                "baseline_qps": baseline_qps,
                "baseline_tps": baseline_tps,
                "baseline_resource_normalized": copy.deepcopy(baseline_runtime_normalized),
                "baseline_resource_utilization_pct": copy.deepcopy(baseline_runtime_util),
                "benchmark": copy.deepcopy(baseline_benchmark),
                "strong_none_gate_passed": baseline_strong_gate_failure is None,
                "strong_none_gate_failure": (
                    str(baseline_strong_gate_failure)
                    if baseline_strong_gate_failure is not None
                    else ""
                ),
                "plan_resource_estimation_available": bool(
                    baseline_only_plan_estimation
                    and not baseline_only_plan_estimation.get("error")
                ),
                "action": "exit_before_model_retraining_and_candidate_search",
            }
        )
        print(
            "Baseline-only validation complete; exiting before model retraining and candidate search.",
            flush=True,
        )
        main_logger.close()
        raise SystemExit(0)

    if metrics_source == "plan-estimator" and plan_estimator_bootstrap_once:
        model_retraining_cfg = plan_estimator_cfg.get("model_retraining") or {}
        retrain_enabled = _to_bool(
            os.environ.get(
                "RESOURCE_MODEL_RETRAIN_ENABLED",
                model_retraining_cfg.get("enabled", True),
            ),
            True,
        )
        if retrain_enabled:
            repo_root = Path(__file__).resolve().parent
            retrain_run_id = str(
                model_retraining_cfg.get("run_id")
                or f"baseline_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
            )
            feature_cache_dir = Path(
                str(
                    model_retraining_cfg.get("feature_cache_dir")
                    or "/home/anonymous/program/features_cache_M1"
                )
            )
            output_root = Path(
                str(
                    model_retraining_cfg.get("output_dir")
                    or "config/generated/baseline_retrained"
                )
            )
            if not output_root.is_absolute():
                output_root = repo_root / output_root
            pretrained_bundle_dir_raw = str(
                model_retraining_cfg.get("pretrained_bundle_dir") or ""
            ).strip()
            pretrained_bundle_dir = (
                Path(pretrained_bundle_dir_raw)
                if pretrained_bundle_dir_raw
                else None
            )
            if (
                pretrained_bundle_dir is not None
                and not pretrained_bundle_dir.is_absolute()
            ):
                pretrained_bundle_dir = repo_root / pretrained_bundle_dir
            apply_to_runtime = _to_bool(model_retraining_cfg.get("apply_to_runtime", True), True)
            calibrate_baseline_error = _to_bool(
                model_retraining_cfg.get("baseline_error_bound_enabled", True),
                True,
            )
            optimizer_cfg_for_retrain = cfg.get("optimizer") or {}
            bf_cfg_for_retrain = (
                optimizer_cfg_for_retrain.get("bruteforce")
                if isinstance(optimizer_cfg_for_retrain.get("bruteforce"), dict)
                else {}
            )
            candidate_gate_for_retrain = (
                bf_cfg_for_retrain.get("candidate_gate")
                if isinstance(bf_cfg_for_retrain.get("candidate_gate"), dict)
                else {}
            )
            robust_cfg_for_retrain = (
                candidate_gate_for_retrain.get("robust_ranking")
                if isinstance(candidate_gate_for_retrain.get("robust_ranking"), dict)
                else {}
            )
            strict_retrain_gate = _to_bool(
                os.environ.get(
                    "BONECT_STRICT_RESOURCE_RETRAIN_GATE",
                    model_retraining_cfg.get("strict_retrain_gate", False),
                ),
                False,
            )
            robust_v5_retrain_fallback_default = bool(
                robust_cfg_for_retrain.get("enabled", False)
                and str(
                    robust_cfg_for_retrain.get("variant")
                    or robust_cfg_for_retrain.get("selected_variant")
                    or ""
                )
                == DEFAULT_ROBUST_VARIANT
                and not strict_retrain_gate
            )
            fallback_on_error = _to_bool(
                os.environ.get(
                    "BONECT_ALLOW_V5_RETRAIN_FALLBACK",
                    model_retraining_cfg.get(
                        "fallback_on_error",
                        robust_v5_retrain_fallback_default,
                    ),
                ),
                robust_v5_retrain_fallback_default,
            )
            if robust_v5_retrain_fallback_default:
                fallback_on_error = True
            fallback_model_version = str(
                model_retraining_cfg.get("fallback_model_version") or "v5"
            ).strip()
            require_all_resources = _to_bool(
                model_retraining_cfg.get("require_all_resources", True),
                True,
            )
            quality_gate_cfg = model_retraining_cfg.get("quality_gate") or {}
            if isinstance(quality_gate_cfg, dict):
                quality_gate_cfg = copy.deepcopy(quality_gate_cfg)
            else:
                quality_gate_cfg = {}
            if phase2_memory_ap_quality_memory_optional:
                required_resources = [
                    str(item).strip().lower()
                    for item in (quality_gate_cfg.get("required_resources") or [])
                    if str(item).strip() and str(item).strip().lower() != "memory"
                ]
                for resource_name in ("cpu", "io"):
                    if resource_name not in required_resources:
                        required_resources.append(resource_name)
                optional_resources = [
                    str(item).strip().lower()
                    for item in (quality_gate_cfg.get("optional_resources") or [])
                    if str(item).strip()
                ]
                if "memory" not in optional_resources:
                    optional_resources.append("memory")
                quality_gate_cfg["required_resources"] = required_resources
                quality_gate_cfg["optional_resources"] = optional_resources
            quality_gate_summary: Dict[str, Any] = {}
            pre_retrain_learned_models = {
                resource_name: copy.deepcopy(
                    (plan_estimator_cfg.get(resource_name) or {}).get("learned_model")
                )
                for resource_name in ("cpu", "io", "memory")
            }

            def _restore_pre_retrain_models() -> Dict[str, Any]:
                restored: Dict[str, Any] = {}
                for resource_name, learned_model in pre_retrain_learned_models.items():
                    resource_cfg = plan_estimator_cfg.setdefault(resource_name, {})
                    if learned_model is None:
                        resource_cfg.pop("learned_model", None)
                        restored[resource_name] = None
                    else:
                        resource_cfg["learned_model"] = copy.deepcopy(learned_model)
                        restored[resource_name] = copy.deepcopy(learned_model)
                return restored

            try:
                if require_all_resources and not apply_to_runtime:
                    raise RuntimeError("strict resource model retraining requires apply_to_runtime=true")
                print("\n[Resource Model Retrain] baseline  CPU/IO/Memory ...", flush=True)
                retrain_result = retrain_resource_models(
                    root=repo_root,
                    feature_cache_dir=feature_cache_dir,
                    output_root=output_root,
                    run_id=retrain_run_id,
                    seed=_to_int(model_retraining_cfg.get("seed", 42), 42),
                    pretrained_bundle_dir=pretrained_bundle_dir,
                )
                if require_all_resources:
                    required_errors = {
                        key: value
                        for key, value in (retrain_result.get("errors") or {}).items()
                        if key in ("cpu", "io")
                    }
                    if required_errors:
                        raise RuntimeError(f"required CPU/IO resource model retraining failed: {required_errors}")
                retrain_paths = dict(retrain_result.get("paths") or {})
                applied_model_paths: Dict[str, str] = {}
                if apply_to_runtime:
                    for resource_name, path_key in (
                        ("cpu", "cpu_json"),
                        ("io", "io_json"),
                        ("memory", "memory_json"),
                    ):
                        model_path = str(retrain_paths.get(path_key) or "").strip()
                        if not model_path:
                            continue
                        learned_cfg = plan_estimator_cfg.setdefault(resource_name, {}).setdefault("learned_model", {})
                        learned_cfg["enabled"] = True
                        learned_cfg["path"] = model_path
                        applied_model_paths[resource_name] = model_path

                baseline_bound_summary: Dict[str, Any] = {}
                baseline_estimated_normalized: Dict[str, float] = {}
                baseline_sanity_summary: Dict[str, Any] = {}
                memory_retrain_summary: Dict[str, Any] = {}
                memory_artifact_mutated_after_estimation = False
                if (
                    calibrate_baseline_error
                    and apply_to_runtime
                    and baseline_all_sql
                    and baseline_runtime_normalized
                ):
                    estimated_raw, estimated_stats, estimated_metadata = estimate_plan_resources(
                        queries=baseline_all_sql,
                        pg_host=pg_host,
                        pg_port=pg_port,
                        pg_user=pg_user,
                        pg_dbname=pg_stat_dbname,
                        estimator_cfg=plan_estimator_cfg,
                        plan_capture_modes=plan_capture_modes,
                        custom_plan_params=plan_capture_custom_plan_params,
                        psql_query_func=lambda sql: _psql_query(sql, dbname=pg_stat_dbname),
                        params=p_real,
                        workload_context=plan_estimator_workload_profile,
                    )
                    baseline_estimated_normalized = _normalize_estimated_resource(
                        estimated_raw,
                        estimated_stats,
                    )
                    memory_model_path = str(retrain_paths.get("memory_json") or "").strip()
                    if memory_model_path:
                        existing_memory_summary = (
                            (retrain_result.get("resources") or {}).get("memory") or {}
                        )
                        existing_memory_source = str(
                            existing_memory_summary.get("source") or ""
                        ).strip()
                        if (
                            existing_memory_summary.get("status") == "retrained"
                            and existing_memory_source
                            != "baseline_memory_single_sample_retrain"
                        ):
                            memory_retrain_summary = copy.deepcopy(existing_memory_summary)
                            memory_retrain_summary["actual_memory_mb"] = (
                                _to_float(baseline_runtime_normalized.get("memory"), 0.0)
                                * 1024.0
                            )
                            learned_memory = (
                                (((estimated_metadata.get("resource_breakdown") or {}).get("memory") or {})
                                .get("calibration_breakdown") or {})
                                .get("learned_model") or {}
                            )
                            selected_memory_model_set = str(
                                learned_memory.get("model_set")
                                or memory_retrain_summary.get("selected_model_set")
                                or ""
                            ).strip()
                            if selected_memory_model_set:
                                memory_retrain_summary["selected_model_set"] = (
                                    selected_memory_model_set
                                )
                        else:
                            memory_retrain_summary = retrain_memory_model_from_baseline(
                                memory_json_path=memory_model_path,
                                baseline_actual_normalized=baseline_runtime_normalized,
                                baseline_estimation_metadata=estimated_metadata,
                                root=repo_root,
                            )
                            memory_artifact_mutated_after_estimation = (
                                memory_retrain_summary.get("status") == "retrained"
                            )
                        retrain_result.setdefault("resources", {})["memory"] = memory_retrain_summary
                        if memory_retrain_summary.get("status") == "retrained":
                            retrain_errors = retrain_result.get("errors")
                            if isinstance(retrain_errors, dict) and retrain_errors.get("memory"):
                                retrain_result.setdefault("overridden_errors", {})["memory"] = {
                                    "error": retrain_errors.get("memory"),
                                    "override_reason": (
                                        "current_baseline_memory_single_sample_retrain_succeeded"
                                    ),
                                    "memory_retrain": copy.deepcopy(memory_retrain_summary),
                                }
                                retrain_errors.pop("memory", None)
                    elif require_all_resources:
                        raise RuntimeError("required memory model retraining failed: memory_json path is missing")
                    if memory_artifact_mutated_after_estimation:
                        # The baseline-memory retrainer updates the model after
                        # the first estimate.  Refresh the raw prediction before
                        # constructing the anchor; otherwise stale pre-mutation
                        # metadata can anchor the newly anchored model again.
                        estimated_raw, estimated_stats, estimated_metadata = estimate_plan_resources(
                            queries=baseline_all_sql,
                            pg_host=pg_host,
                            pg_port=pg_port,
                            pg_user=pg_user,
                            pg_dbname=pg_stat_dbname,
                            estimator_cfg=plan_estimator_cfg,
                            plan_capture_modes=plan_capture_modes,
                            custom_plan_params=plan_capture_custom_plan_params,
                            psql_query_func=lambda sql: _psql_query(sql, dbname=pg_stat_dbname),
                            params=p_real,
                            workload_context=plan_estimator_workload_profile,
                        )
                        baseline_estimated_normalized = _normalize_estimated_resource(
                            estimated_raw,
                            estimated_stats,
                        )
                        main_logger.log_struct(
                            {
                                "event": "baseline_model_prediction_refreshed_after_memory_retrain",
                                "prediction_stage": "raw_model_before_anchor_and_error_bound",
                                "memory_retrain": copy.deepcopy(memory_retrain_summary),
                            }
                        )
                    baseline_bound_summary = apply_baseline_error_bounds(
                        artifact_paths=retrain_paths,
                        baseline_actual_normalized=baseline_runtime_normalized,
                        baseline_estimation_metadata=estimated_metadata,
                        root=repo_root,
                    )
                    if (baseline_bound_summary.get("updated") or {}):
                        estimated_raw, estimated_stats, estimated_metadata = estimate_plan_resources(
                            queries=baseline_all_sql,
                            pg_host=pg_host,
                            pg_port=pg_port,
                            pg_user=pg_user,
                            pg_dbname=pg_stat_dbname,
                            estimator_cfg=plan_estimator_cfg,
                            plan_capture_modes=plan_capture_modes,
                            custom_plan_params=plan_capture_custom_plan_params,
                            psql_query_func=lambda sql: _psql_query(sql, dbname=pg_stat_dbname),
                            params=p_real,
                            workload_context=plan_estimator_workload_profile,
                        )
                        baseline_estimated_normalized = _normalize_estimated_resource(
                            estimated_raw,
                            estimated_stats,
                        )
                    baseline_sanity_cfg = (
                        quality_gate_cfg.get("baseline_sanity")
                        if isinstance(quality_gate_cfg, dict)
                        else {}
                    )
                    if isinstance(baseline_sanity_cfg, dict):
                        baseline_sanity_cfg = copy.deepcopy(baseline_sanity_cfg)
                    else:
                        baseline_sanity_cfg = {}
                    baseline_sanity_summary = validate_resource_model_baseline_sanity_gate(
                        baseline_actual_normalized=baseline_runtime_normalized,
                        baseline_estimated_normalized=baseline_estimated_normalized,
                        baseline_estimation_metadata=estimated_metadata,
                        gate_cfg=baseline_sanity_cfg,
                    )
                    anchor_exempt_resources = baseline_anchor_correction_exempt_resources(
                        applied_model_paths=applied_model_paths,
                        baseline_error_bounds=baseline_bound_summary,
                        baseline_sanity_gate=baseline_sanity_summary,
                    )
                    if anchor_exempt_resources:
                        baseline_correction_state["exempt_resources"] = anchor_exempt_resources
                        baseline_correction_state["exemption_source"] = (
                            "resource_model_baseline_anchor_sanity_gate"
                        )
                    main_logger.log_struct(
                        {
                            "event": "resource_model_baseline_sanity_gate",
                            "summary": baseline_sanity_summary,
                            "baseline_correction_exempt_resources": anchor_exempt_resources,
                        }
                    )
                    baseline_sanity_hard_fail = _resource_quality_bool(
                        baseline_sanity_cfg.get("hard_fail", False)
                        if isinstance(baseline_sanity_cfg, dict)
                        else False,
                        False,
                    )
                    if (
                        baseline_sanity_summary.get("enabled")
                        and not baseline_sanity_summary.get("passed")
                        and baseline_sanity_hard_fail
                    ):
                        raise RuntimeError(
                            "resource model baseline sanity gate failed before optimization: "
                            f"{baseline_sanity_summary.get('failures')}"
                        )
                elif require_all_resources:
                    raise RuntimeError(
                        "strict resource model retraining requires baseline SQL, "
                        "baseline actual resources, and baseline error calibration"
                    )

                if require_all_resources:
                    resources = retrain_result.get("resources") or {}
                    missing_resources = [
                        resource_name
                        for resource_name in ("cpu", "io", "memory")
                        if resource_name not in resources
                    ]
                    if missing_resources:
                        raise RuntimeError(
                            f"required resource model retraining missing resources: {missing_resources}"
                        )
                    memory_status = (
                        resources.get("memory", {}).get("status")
                        if isinstance(resources.get("memory"), dict)
                        else None
                    )
                    if memory_status != "retrained":
                        raise RuntimeError(
                            f"required memory model retraining did not complete: {resources.get('memory')}"
                        )
                    required_errors = {
                        key: value
                        for key, value in (retrain_result.get("errors") or {}).items()
                        if key in ("cpu", "io", "memory")
                    }
                    if required_errors:
                        raise RuntimeError(f"required resource model retraining failed: {required_errors}")

                quality_gate_summary = validate_resource_model_quality_gate(
                    retrain_result,
                    quality_gate_cfg if isinstance(quality_gate_cfg, dict) else {},
                    baseline_estimation_metadata=estimated_metadata,
                )
                main_logger.log_struct(
                    {
                        "event": "resource_model_quality_gate",
                        "summary": quality_gate_summary,
                    }
                )
                if quality_gate_summary.get("enabled") and not quality_gate_summary.get("passed"):
                    raise RuntimeError(
                        "resource model quality gate failed before optimization: "
                        f"{quality_gate_summary.get('failures')}"
                    )

                plan_estimator_workload_profile["resource_model_retraining"] = {
                    "enabled": True,
                    "run_id": retrain_run_id,
                    "feature_cache_dir": str(feature_cache_dir),
                    "output_root": str(output_root),
                    "apply_to_runtime": apply_to_runtime,
                    "applied_model_paths": applied_model_paths,
                    "summary": retrain_result,
                    "baseline_estimated_normalized": baseline_estimated_normalized,
                    "baseline_error_bounds": baseline_bound_summary,
                    "memory_retrain": memory_retrain_summary,
                    "require_all_resources": require_all_resources,
                    "quality_gate": quality_gate_summary,
                    "baseline_sanity_gate": baseline_sanity_summary,
                    "strict_retrain_gate": strict_retrain_gate,
                }
                print("[Resource Model Retrain] :")
                for resource_name, model_path in applied_model_paths.items():
                    print(f"  {resource_name}: {model_path}", flush=True)
                if baseline_bound_summary.get("updated"):
                    print("  baseline error bounds  artifact", flush=True)
                if quality_gate_summary:
                    status = "passed" if quality_gate_summary.get("passed") else "failed"
                    print(
                        f"  resource model quality gate: {status} "
                        f"({len(quality_gate_summary.get('checks') or [])} checks)",
                        flush=True,
                    )
                if retrain_result.get("errors"):
                    print(f"  : {retrain_result.get('errors')}", flush=True)
                main_logger.log_struct(
                    {
                        "event": "resource_model_retraining",
                        "enabled": True,
                        "run_id": retrain_run_id,
                        "apply_to_runtime": apply_to_runtime,
                        "applied_model_paths": applied_model_paths,
                        "summary": retrain_result,
                        "baseline_actual_normalized": baseline_runtime_normalized,
                        "baseline_estimated_normalized": baseline_estimated_normalized,
                        "baseline_error_bounds": baseline_bound_summary,
                        "memory_retrain": memory_retrain_summary,
                        "require_all_resources": require_all_resources,
                        "quality_gate": quality_gate_summary,
                        "baseline_sanity_gate": baseline_sanity_summary,
                        "strict_retrain_gate": strict_retrain_gate,
                    }
                )
            except Exception as exc:
                print(f"[WARN] Resource model retraining failed: {exc}", flush=True)
                fallback_quality_gate_summary = quality_gate_summary
                if not fallback_quality_gate_summary:
                    fallback_quality_gate_summary = {
                        "enabled": bool(
                            (quality_gate_cfg or {}).get("enabled", False)
                            if isinstance(quality_gate_cfg, dict)
                            else False
                        ),
                        "passed": False,
                        "checks": [],
                        "failures": [
                            {
                                "reason": "resource_model_retraining_failed_before_quality_gate",
                                "error": str(exc),
                            }
                        ],
                        "warnings": [],
                    }
                restored_models: Dict[str, Any] = {}
                fallback_mode = None
                if fallback_on_error:
                    restored_models = _restore_pre_retrain_models()
                    fallback_mode = "v5_robust_ranking_with_pre_retrain_resource_models"
                    print(
                        "[WARN] Resource model retraining fallback enabled; "
                        "continuing with v5 robust ranking and pre-retrain model artifacts.",
                        flush=True,
                    )
                main_logger.log_struct(
                    {
                        "event": "resource_model_retraining_error",
                        "enabled": True,
                        "run_id": retrain_run_id,
                        "feature_cache_dir": str(feature_cache_dir),
                        "output_root": str(output_root),
                        "fallback_on_error": fallback_on_error,
                        "fallback_model_version": fallback_model_version,
                        "fallback_mode": fallback_mode,
                        "require_all_resources": require_all_resources,
                        "quality_gate": fallback_quality_gate_summary,
                        "strict_retrain_gate": strict_retrain_gate,
                        "error": str(exc),
                    }
                )
                if fallback_on_error:
                    main_logger.log_struct(
                        {
                            "event": "resource_model_retraining_fallback",
                            "enabled": True,
                            "fallback_model_version": fallback_model_version,
                            "mode": fallback_mode,
                            "reason": str(exc),
                            "policy": (
                                "current baseline retraining/gate did not pass; "
                                "continue the outer real-validation loop with "
                                "latest v5 robust ranking, recorded uncertainty, "
                                "and pre-retrain resource-model artifacts"
                            ),
                            "restored_learned_models": restored_models,
                            "quality_gate": fallback_quality_gate_summary,
                        }
                    )
                plan_estimator_workload_profile["resource_model_retraining"] = {
                    "enabled": True,
                    "success": False,
                    "fallback_on_error": fallback_on_error,
                    "fallback_model_version": fallback_model_version,
                    "fallback_mode": fallback_mode,
                    "require_all_resources": require_all_resources,
                    "quality_gate": fallback_quality_gate_summary,
                    "strict_retrain_gate": strict_retrain_gate,
                    "error": str(exc),
                }
                if not fallback_on_error:
                    raise
        else:
            main_logger.log_struct(
                {
                    "event": "resource_model_retraining",
                    "enabled": False,
                    "reason": "disabled_by_config_or_env",
                }
            )


    # start_ts = time.time()
    # subprocess.run(workload_cmd, shell=True, check=True)
    # end_ts = time.time()
    #
    # resource_avg, resource_stats = monitor_resources_from_prometheus(
    #     prom_url=prom_url,
    #     start_ts=start_ts,
    #     end_ts=end_ts,
    #     step="5s",
    #     cpu_promql=cpu_promql,
    #     mem_promql=mem_promql,
    #     io_read_promql=io_read_promql,
    #     io_write_promql=io_write_promql
    # )

    # print(f"  avg: {resource_avg}")
    # print(f"  stats: {resource_stats}")


    def raw_resource_estimation_func(sql_set, params):
        _ = sql_set
        start_ts = time.time()
        resource_avg = {}
        resource_stats = {}
        iteration_metadata: Dict[str, Any] = {}
        pg_noise_before: Optional[Dict[str, Any]] = None
        current_label = str(
            getattr(raw_resource_estimation_func, "current_label", "iteration")
        )
        estimation_context = str(
            getattr(raw_resource_estimation_func, "estimation_context", "") or ""
        )
        compact_candidate_probe_log = bool(
            candidate_probe_compact_logging
            and estimation_context == "candidate_pair_probe"
        )
        if (
            current_label.startswith("p_real")
            and params == p_real
            and baseline_runtime_resource_avg
            and baseline_runtime_resource_stats
        ):
            resource_stats = copy.deepcopy(baseline_runtime_resource_stats)
            if baseline_benchmark:
                resource_stats.setdefault("benchmark", copy.deepcopy(baseline_benchmark))
            if baseline_benchmark_latency:
                resource_stats.setdefault(
                    "benchmark_latency",
                    copy.deepcopy(baseline_benchmark_latency),
                )
            iteration_metadata = {
                "workload_execution": {
                    "executed": False,
                    "mode": "reuse-outer-baseline-runtime",
                    "reason": "p_real already measured by the startup baseline run",
                },
                "top_sql": list(baseline_top_sql),
                "baseline_all_sql_count": len(baseline_all_sql),
                "baseline_all_sql_top10": list(baseline_all_sql[:10]),
                "db_view_monitor": copy.deepcopy(
                    (baseline_run.get("db_view_monitor") if isinstance(baseline_run, dict) else {}) or {}
                ),
                "effective_params": _read_effective_params(
                    params, dbname=pg_stat_dbname
                ),
            }
            raw_resource_estimation_func.last_stats = resource_stats
            raw_resource_estimation_func.last_window = (baseline_start_ts, baseline_end_ts)
            raw_resource_estimation_func.last_metadata = iteration_metadata
            main_logger.log_struct(
                {
                    "event": "reuse_outer_baseline_runtime",
                    "label": current_label,
                    "window": [baseline_start_ts, baseline_end_ts],
                    "resource_avg": baseline_runtime_resource_avg,
                    "resource_stats_keys": sorted(resource_stats.keys()),
                }
            )
            print(
                "[Baseline] Reusing startup baseline runtime metrics for optimizer p_real; "
                "skipping duplicate workload run.",
                flush=True,
            )
            return copy.deepcopy(baseline_runtime_resource_avg)
        should_run_iteration_workload = (
            metrics_source != "plan-estimator" or not plan_estimator_bootstrap_once
        )
        if not should_run_iteration_workload:
            iteration_metadata["pg_stat_statements_reset"] = {
                "success": False,
                "skipped": True,
                "reason": "plan-estimator-reuses-baseline-workload",
            }
        before_calls: Optional[int] = None
        try:
            # Restore/rebuild first, then apply candidate parameters and reset
            # statistics immediately before measurement. This keeps load/COPY
            # work out of pg_stat_statements and workload resource windows.
            if should_run_iteration_workload:
                _run_external_replay_safe_guard(f"before_iteration:{current_label}")
                _run_pre_benchmark_recovery("iteration")

            apply_params_via_alter_system(_with_fixed_params(params))
            iteration_metadata["effective_params"] = _read_effective_params(
                params, dbname=pg_stat_dbname
            )

            if should_run_iteration_workload:
                _reset_pg_stat_statements_for_workload("Iteration", iteration_metadata)
                before_calls = _read_total_statement_calls(pg_stat_dbname)

            current_plan_samples = _capture_plan_signatures(
                tracked_plan_queries if tracked_plan_queries else baseline_top_sql,
                dbname=pg_stat_dbname,
                limit=plan_capture_limit if plan_capture_enabled else 10,
            )
            plan_changes = _diff_plan_signatures(
                previous_iteration_plan_samples,
                current_plan_samples,
            )
            iteration_metadata["plan_changes"] = [
                {k: v for k, v in item.items() if k not in ("previous_normalized_plan", "current_normalized_plan")}
                for item in plan_changes
            ]
            iteration_metadata["plan_change_count"] = len(plan_changes)
            iteration_metadata["plan_capture_file"] = (
                _dump_plan_capture(
                    current_plan_samples,
                    label=current_label,
                    output_dir=plan_capture_output_dir,
                )
                if plan_capture_enabled and not compact_candidate_probe_log
                else None
            )
            iteration_metadata["plan_capture_count"] = len(current_plan_samples)
            iteration_metadata["plan_change_detail_files"] = (
                []
                if compact_candidate_probe_log
                else _dump_changed_plan_details(
                    plan_changes,
                    dbname=pg_stat_dbname,
                    label=current_label,
                )
            )
            iteration_plan_change_keys = sorted(
                {
                    key
                    for key in (_plan_query_key(item) for item in plan_changes)
                    if key
                }
            )
            tracked_plan_change_keys.update(iteration_plan_change_keys)
            iteration_metadata["plan_change_keys"] = iteration_plan_change_keys
            iteration_metadata["cumulative_plan_change_count"] = len(tracked_plan_change_keys)
            iteration_metadata["cumulative_plan_change_keys"] = sorted(tracked_plan_change_keys)
            if compact_candidate_probe_log:
                main_logger.log_struct(
                    {
                        "event": "candidate_probe_plan_changes",
                        "window": [start_ts, start_ts],
                        "estimation_context": estimation_context,
                        "plan_change_count": len(plan_changes),
                        "plan_capture_count": iteration_metadata["plan_capture_count"],
                        "plan_change_keys": iteration_plan_change_keys,
                        "cumulative_plan_change_count": len(tracked_plan_change_keys),
                    }
                )
            else:
                _print_plan_changes(plan_changes, limit=10)
                main_logger.log_struct(
                    {
                        "event": "iteration_plan_changes",
                        "window": [start_ts, start_ts],
                        "changes": iteration_metadata["plan_changes"],
                        "detail_files": iteration_metadata["plan_change_detail_files"],
                        "plan_capture_file": iteration_metadata["plan_capture_file"],
                        "plan_capture_count": iteration_metadata["plan_capture_count"],
                        "plan_change_keys": iteration_plan_change_keys,
                        "cumulative_plan_change_count": len(tracked_plan_change_keys),
                        "cumulative_plan_change_keys": sorted(tracked_plan_change_keys),
                    }
                )
            previous_iteration_plan_samples[:] = list(current_plan_samples)
            if metrics_source == "docker-runtime":
                pg_noise_before = _read_pg_noise_snapshot(pg_stat_dbname)
                monitor_result, _ = _run_with_db_view_monitor(
                    current_label,
                    lambda: monitor_resources_from_docker_runtime_workload(
                        workload_cmd=workload_cmd,
                        container_name=docker_rt_container,
                        interval_s=docker_rt_interval,
                        warmup_s=docker_rt_warmup,
                        memory_mode=docker_rt_memory_mode,
                        io_scope=docker_rt_io_scope,
                        max_runtime_s=workload_timeout_sec,
                    ),
                )
                resource_avg, resource_stats = monitor_result
                iteration_metadata["db_view_monitor"] = copy.deepcopy(
                    getattr(_run_with_db_view_monitor, "last_summary", {}) or {}
                )
                resource_stats["db_view_monitor"] = iteration_metadata["db_view_monitor"]
            elif metrics_source == "vm-runtime":
                pg_noise_before = _read_pg_noise_snapshot(pg_stat_dbname)
                monitor_result, _ = _run_with_db_view_monitor(
                    current_label,
                    lambda: monitor_resources_from_vm_runtime_workload(
                        workload_cmd=workload_cmd,
                        vm_host=vm_rt_host,
                        ssh_target=vm_rt_ssh_target,
                        ssh_user=vm_rt_ssh_user,
                        ssh_port=vm_rt_ssh_port,
                        ssh_identity_file=vm_rt_ssh_identity_file,
                        interval_s=vm_rt_interval,
                        warmup_s=vm_rt_warmup,
                        connect_timeout_s=vm_rt_connect_timeout,
                        disk_devices=vm_rt_disk_devices,
                        cpu_mode=vm_rt_cpu_mode,
                        io_mode=vm_rt_io_mode,
                        memory_mode=vm_rt_memory_mode,
                        max_runtime_s=workload_timeout_sec,
                    ),
                )
                resource_avg, resource_stats = monitor_result
                iteration_metadata["db_view_monitor"] = copy.deepcopy(
                    getattr(_run_with_db_view_monitor, "last_summary", {}) or {}
                )
                resource_stats["db_view_monitor"] = iteration_metadata["db_view_monitor"]
            elif metrics_source == "plan-estimator" and plan_estimator_bootstrap_once:
                iteration_metadata["workload_execution"] = {
                    "executed": False,
                    "mode": "reuse-baseline-workload",
                    "all_sql_count": len(baseline_all_sql),
                }
            else:
                pg_noise_before = _read_pg_noise_snapshot(pg_stat_dbname)
                _, _ = _run_with_db_view_monitor(
                    current_label,
                    lambda: subprocess.run(workload_cmd, shell=True, check=True),
                )
                iteration_metadata["db_view_monitor"] = copy.deepcopy(
                    getattr(_run_with_db_view_monitor, "last_summary", {}) or {}
                )
        finally:
            end_ts = time.time()
            if metrics_source == "plan-estimator" and plan_estimator_bootstrap_once:
                iteration_metadata["top_sql"] = list(baseline_top_sql)
                iteration_metadata["bootstrap_all_sql_count"] = len(baseline_all_sql)
                iteration_metadata["bootstrap_all_sql_top10"] = list(baseline_all_sql[:10])
                iteration_metadata["bootstrap_workload_profile"] = plan_estimator_workload_profile
            else:
                try:
                    iteration_top_sql = _fetch_top_slowest_sql(
                        dbname=pg_stat_dbname,
                        limit=max(20, plan_capture_candidate_limit),
                    )
                    iteration_metadata["top_sql"] = iteration_top_sql
                    tracked_plan_queries[:] = _select_plan_queries(
                        iteration_top_sql,
                        limit=plan_capture_limit if plan_capture_enabled else 20,
                        coverage_pct=plan_capture_coverage_pct,
                        min_queries=plan_capture_min_queries,
                        changed_keys=tracked_plan_change_keys,
                        slow_mean_ms=plan_capture_slow_mean_ms,
                    )
                except Exception as exc:
                    iteration_metadata["top_sql"] = []
                    iteration_metadata["top_sql_error"] = str(exc)
                    print(f"[WARN] Iteration top SQL collection failed: {exc}")
                if pg_noise_before is not None:
                    try:
                        pg_noise_after = _read_pg_noise_snapshot(pg_stat_dbname)
                        pg_noise_delta = _build_pg_noise_delta(pg_noise_before, pg_noise_after)
                        iteration_metadata["pg_noise"] = pg_noise_delta
                        main_logger.log_struct(
                            {
                                "event": "iteration_pg_noise",
                                "label": current_label,
                                "window": [start_ts, end_ts],
                                "pg_noise": pg_noise_delta,
                            }
                        )
                    except Exception as exc:
                        iteration_metadata["pg_noise_error"] = str(exc)
                        main_logger.log_struct(
                            {
                                "event": "iteration_pg_noise_error",
                                "label": current_label,
                                "window": [start_ts, end_ts],
                                "error": str(exc),
                            }
                        )
                _run_post_benchmark_cleanup("iteration")

        try:
            iteration_top_sql = iteration_metadata.get("top_sql") or []
            if compact_candidate_probe_log:
                main_logger.log_struct(
                    {
                        "event": "candidate_probe_top_sql_reused",
                        "window": [start_ts, end_ts],
                        "estimation_context": estimation_context,
                        "top_sql_count": len(iteration_top_sql),
                        "bootstrap_workload_once": plan_estimator_bootstrap_once,
                    }
                )
            else:
                _print_top_sql("Iteration Top Slow SQL", iteration_top_sql, limit=10)
                main_logger.log_struct(
                    {
                        "event": "iteration_top_sql",
                        "window": [start_ts, end_ts],
                        "top": iteration_top_sql,
                    }
                )
        except Exception as exc:
            iteration_metadata["top_sql"] = []
            iteration_metadata["top_sql_error"] = str(exc)
            print(f"[WARN] Iteration top SQL collection failed: {exc}")
            main_logger.log_struct(
                {
                    "event": "iteration_top_sql_error",
                    "window": [start_ts, end_ts],
                    "dbname": pg_stat_dbname,
                    "error": str(exc),
                }
            )

        after_calls = (
            _read_total_statement_calls(pg_stat_dbname)
            if metrics_source != "plan-estimator" or not plan_estimator_bootstrap_once
            else None
        )
        if before_calls is not None and after_calls is not None:
            iteration_metadata["iteration_sql_count"] = max(0, after_calls - before_calls)

        if metrics_source == "prometheus":

            time.sleep(10)
            resource_avg, resource_stats = monitor_resources_from_prometheus(
                prom_url=prom_url,
                start_ts=start_ts,
                end_ts=end_ts,
                step=prom_step,
                cpu_promql=cpu_promql,
                mem_promql=mem_promql,
                io_read_promql=io_read_promql,
                io_write_promql=io_write_promql,
                qps_promql=qps_promql,
                concurrency_promql=concurrency_promql,
                query_count_promql=query_count_promql,
                query_time_promql=query_time_promql,
            )
        elif metrics_source == "plan-estimator":
            plan_queries = (
                list(baseline_all_sql)
                if plan_estimator_bootstrap_once and baseline_all_sql
                else _fetch_top_slowest_sql(dbname=pg_stat_dbname, limit=None)
            )
            logged_sql_topn = list(plan_queries[:10])
            resource_avg, resource_stats, plan_metadata = estimate_plan_resources(
                queries=plan_queries,
                pg_host=pg_host,
                pg_port=pg_port,
                pg_user=pg_user,
                pg_dbname=pg_stat_dbname,
                estimator_cfg=plan_estimator_cfg,
                plan_capture_modes=plan_capture_modes,
                custom_plan_params=plan_capture_custom_plan_params,
                psql_query_func=lambda sql: _psql_query(sql, dbname=pg_stat_dbname),
                params=params,
                workload_context=plan_estimator_workload_profile,
            )
            iteration_metadata["all_sql_for_plan_estimator_count"] = len(plan_queries)
            iteration_metadata["all_sql_for_plan_estimator_top10"] = logged_sql_topn
            iteration_metadata["plan_estimator_workload_profile"] = plan_estimator_workload_profile
            iteration_metadata["plan_estimator_bootstrap_workload_once"] = plan_estimator_bootstrap_once
            iteration_metadata["plan_resource_estimation"] = plan_metadata
            if compact_candidate_probe_log:
                compact_breakdown: Dict[str, Dict[str, Any]] = {}
                for resource_name, resource_item in (
                    (plan_metadata.get("resource_breakdown") or {}).items()
                ):
                    if not isinstance(resource_item, dict):
                        continue
                    calibration = resource_item.get("calibration_breakdown") or {}
                    learned = (
                        calibration.get("learned_model")
                        if isinstance(calibration, dict)
                        else {}
                    ) or {}
                    if not isinstance(learned, dict):
                        learned = {}
                    fallback = (
                        learned.get("learned_model_fallback")
                    ) or {}
                    if not isinstance(fallback, dict):
                        fallback = {}
                    compact_breakdown[str(resource_name)] = {
                        "value": resource_item.get("value"),
                        "unit": resource_item.get("unit"),
                        "model_set": learned.get("model_set"),
                        "formula_name": calibration.get("formula_name"),
                        "fallback_used": bool(fallback),
                        "fallback_reason": fallback.get("reason"),
                    }
                main_logger.log_struct(
                    {
                        "event": "candidate_probe_plan_resource_estimation",
                        "window": [start_ts, end_ts],
                        "estimation_context": estimation_context,
                        "params": copy.deepcopy(params),
                        "all_sql_count": len(plan_queries),
                        "bootstrap_workload_once": plan_estimator_bootstrap_once,
                        "resource_breakdown_summary": compact_breakdown,
                        "resource_estimation_log_count": len(
                            plan_metadata.get("resource_estimation_logs") or []
                        ),
                        "query_count": plan_metadata.get("query_count"),
                    }
                )
            else:
                main_logger.log_struct(
                    {
                        "event": "plan_resource_estimation",
                        "window": [start_ts, end_ts],
                        "all_sql_count": len(plan_queries),
                        "all_sql_top10": logged_sql_topn,
                        "bootstrap_workload_once": plan_estimator_bootstrap_once,
                        "workload_profile": _compact_plan_estimator_workload_profile(plan_estimator_workload_profile),
                        "resource_breakdown": plan_metadata.get("resource_breakdown"),
                        "resource_estimation_logs": plan_metadata.get("resource_estimation_logs"),
                        "query_count": plan_metadata.get("query_count"),
                    }
                )
        elif docker_rt_io_from_prom:
            # Hybrid mode: cpu/memory from docker runtime, IO/IOPS from Prometheus(node metrics)
            try:
                time.sleep(10)
                prom_io_avg, prom_io_stats = monitor_resources_from_prometheus(
                    prom_url=prom_url,
                    start_ts=start_ts,
                    end_ts=end_ts,
                    step=prom_step,
                    io_read_promql=io_read_promql,
                    io_write_promql=io_write_promql,
                    qps_promql=qps_promql,
                    concurrency_promql=concurrency_promql,
                    query_count_promql=query_count_promql,
                    query_time_promql=query_time_promql,
                )
                resource_avg["io"] = prom_io_avg.get("io", resource_avg.get("io", 0.0))
                if "qps" in prom_io_stats:
                    resource_stats["qps"] = prom_io_stats.get("qps")
                if "concurrency" in prom_io_stats:
                    resource_stats["concurrency"] = prom_io_stats.get("concurrency")
                if "query_count" in prom_io_stats:
                    resource_stats["query_count"] = prom_io_stats.get("query_count")
                if "query_time" in prom_io_stats:
                    resource_stats["query_time"] = prom_io_stats.get("query_time")
                resource_stats["io_read"] = prom_io_stats.get(
                    "io_read",
                    resource_stats.get("io_read", {"min": 0.0, "max": 0.0, "avg": 0.0}),
                )
                resource_stats["io_write"] = prom_io_stats.get(
                    "io_write",
                    resource_stats.get("io_write", {"min": 0.0, "max": 0.0, "avg": 0.0}),
                )
            except Exception as exc:
                main_logger.log_struct(
                    {
                        "event": "docker_runtime_io_prometheus_fallback",
                        "success": False,
                        "error": str(exc),
                    }
                )
        if "concurrency" not in resource_stats:
            resource_stats["concurrency"] = None
        if "db_view_monitor" not in resource_stats and iteration_metadata.get("db_view_monitor"):
            resource_stats["db_view_monitor"] = iteration_metadata.get("db_view_monitor")
        if iteration_metadata.get("pg_noise"):
            resource_stats["pg_noise"] = iteration_metadata.get("pg_noise")
        noisy, noisy_reasons = _is_noisy_candidate_run(
            current_label,
            resource_avg,
            iteration_metadata.get("pg_noise") or {},
        )
        retry_depth = int(getattr(raw_resource_estimation_func, "_noise_retry_depth", 0) or 0)
        if noisy and retry_depth < noise_guard_max_retries:
            main_logger.log_struct(
                {
                    "event": "noise_guard_retry",
                    "label": current_label,
                    "retry_depth": retry_depth,
                    "max_retries": noise_guard_max_retries,
                    "resource_avg": resource_avg,
                    "reasons": noisy_reasons,
                    "pg_noise": iteration_metadata.get("pg_noise") or {},
                }
            )
            print(
                "[NoiseGuard] Candidate run marked noisy; "
                f"rerun {retry_depth + 1}/{noise_guard_max_retries}. "
                f"Reasons: {', '.join(noisy_reasons)}",
                flush=True,
            )
            setattr(raw_resource_estimation_func, "_noise_retry_depth", retry_depth + 1)
            try:
                return raw_resource_estimation_func(sql_set, params)
            finally:
                setattr(raw_resource_estimation_func, "_noise_retry_depth", retry_depth)
        if noisy:
            iteration_metadata["noise_guard"] = {
                "noisy": True,
                "retries_exhausted": retry_depth >= noise_guard_max_retries,
                "reasons": noisy_reasons,
            }
            resource_stats["noise_guard"] = iteration_metadata["noise_guard"]
            main_logger.log_struct(
                {
                    "event": "noise_guard_noisy_final",
                    "label": current_label,
                    "retry_depth": retry_depth,
                    "max_retries": noise_guard_max_retries,
                    "resource_avg": resource_avg,
                    "reasons": noisy_reasons,
                }
            )
        else:
            iteration_metadata["noise_guard"] = {
                "noisy": False,
                "reasons": [],
            }
            resource_stats["noise_guard"] = iteration_metadata["noise_guard"]

        raw_resource_estimation_func.last_stats = resource_stats
        raw_resource_estimation_func.last_window = (start_ts, end_ts)
        raw_resource_estimation_func.last_metadata = iteration_metadata
        return resource_avg

    def _calibrate_baseline_estimation_if_needed(sql_set: Any = None) -> None:
        if not baseline_correction_state.get("enabled"):
            return
        if baseline_correction_state.get("completed"):
            return
        if not baseline_runtime_normalized:
            baseline_correction_state["completed"] = True
            baseline_correction_state["skip_reason"] = "missing_actual_baseline"
            return

        exempt_resources = set(baseline_correction_state.get("exempt_resources") or [])
        active_resources = [
            key for key in baseline_correction_resources if key not in exempt_resources
        ]
        if not active_resources:
            baseline_correction_state["completed"] = True
            baseline_correction_state["success"] = True
            baseline_correction_state["skip_reason"] = "all_resources_baseline_anchored"
            main_logger.log_struct(
                {
                    "event": "baseline_estimation_correction",
                    "success": True,
                    "completed": True,
                    "resources": baseline_correction_resources,
                    "active_resources": [],
                    "exempt_resources": sorted(exempt_resources),
                    "scales": baseline_correction_state.get("scales"),
                    "skip_reason": baseline_correction_state.get("skip_reason"),
                }
            )
            return

        correction_history: List[Dict[str, Any]] = []
        previous_label = getattr(raw_resource_estimation_func, "current_label", "iteration")
        try:
            print("\n[Baseline Correction] ...")
            for round_idx in range(1, baseline_correction_max_rounds + 1):
                setattr(raw_resource_estimation_func, "current_label", f"baseline_correction_round_{round_idx}")
                estimated_raw = raw_resource_estimation_func(sql_set, p_real)
                estimated_stats = getattr(raw_resource_estimation_func, "last_stats", {}) or {}
                estimated_normalized = _normalize_estimated_resource(estimated_raw, estimated_stats)
                corrected_estimated = _apply_baseline_correction_to_normalized(estimated_normalized)

                round_errors: Dict[str, float] = {}
                round_actuals: Dict[str, float] = {}
                round_estimateds: Dict[str, float] = {}
                scales_before = copy.deepcopy(baseline_correction_state["scales"])
                max_log10_error = 0.0

                for key in active_resources:
                    actual_value = float(baseline_runtime_normalized.get(key, 0.0) or 0.0)
                    estimated_value = float(corrected_estimated.get(key, 0.0) or 0.0)
                    actual_anchor = max(
                        abs(actual_value),
                        baseline_correction_signal_floor,
                    )
                    estimated_anchor = max(
                        abs(estimated_value),
                        baseline_correction_signal_floor,
                    )
                    log10_error = abs(np.log10(estimated_anchor) - np.log10(actual_anchor))
                    round_errors[key] = log10_error
                    round_actuals[key] = actual_value
                    round_estimateds[key] = estimated_value
                    max_log10_error = max(max_log10_error, log10_error)

                    target_scale = actual_value / estimated_anchor
                    if actual_value == 0.0 and abs(estimated_value) <= baseline_correction_signal_floor:
                        target_scale = 1.0
                    current_scale = float(baseline_correction_state["scales"].get(key, 1.0) or 1.0)
                    updated_scale = current_scale * (target_scale ** baseline_correction_learning_rate)
                    updated_scale = min(
                        baseline_correction_max_scale,
                        max(1.0 / baseline_correction_max_scale, updated_scale),
                    )
                    baseline_correction_state["scales"][key] = updated_scale

                round_record = {
                    "round": round_idx,
                    "estimated_before_correction": estimated_normalized,
                    "estimated_after_correction": corrected_estimated,
                    "actual_baseline": round_actuals,
                    "log10_errors": round_errors,
                    "max_log10_error": max_log10_error,
                    "scales_before": scales_before,
                    "scales_after": copy.deepcopy(baseline_correction_state["scales"]),
                }
                correction_history.append(round_record)
                baseline_correction_state["round_count"] = round_idx
                baseline_correction_state["last_max_log10_error"] = max_log10_error

                print(
                    f"[Baseline Correction] round={round_idx} "
                    f"max_log10_error={max_log10_error:.4f} "
                    f"target={baseline_correction_target_log10_error:.4f}"
                )
                for key in active_resources:
                    print(
                        f"  {key:<10} actual={round_actuals[key]:.4f} "
                        f"estimated={round_estimateds[key]:.4f} "
                        f"log10_error={round_errors[key]:.4f} "
                        f"scale={float(baseline_correction_state['scales'].get(key, 1.0)):.6f}"
                    )

                if max_log10_error <= baseline_correction_target_log10_error:
                    baseline_correction_state["success"] = True
                    break

            baseline_correction_state["history"] = correction_history
            baseline_correction_state["completed"] = True
            if not baseline_correction_state.get("success"):
                baseline_correction_state["skip_reason"] = "max_rounds_reached"
            main_logger.log_struct(
                {
                    "event": "baseline_estimation_correction",
                    "success": baseline_correction_state.get("success"),
                    "completed": baseline_correction_state.get("completed"),
                    "target_log10_error": baseline_correction_target_log10_error,
                    "max_rounds": baseline_correction_max_rounds,
                    "learning_rate": baseline_correction_learning_rate,
                    "signal_floor": baseline_correction_signal_floor,
                    "actual_baseline": baseline_runtime_normalized,
                    "resources": baseline_correction_resources,
                    "active_resources": active_resources,
                    "exempt_resources": sorted(exempt_resources),
                    "scales": baseline_correction_state.get("scales"),
                    "history": correction_history,
                    "last_max_log10_error": baseline_correction_state.get("last_max_log10_error"),
                    "skip_reason": baseline_correction_state.get("skip_reason"),
                }
            )
        finally:
            setattr(raw_resource_estimation_func, "current_label", previous_label)


    def normalized_resource_estimation(sql_set, params):
        _calibrate_baseline_estimation_if_needed(sql_set)

        current_label = getattr(normalized_resource_estimation, "current_label", None)
        if current_label is not None:
            setattr(raw_resource_estimation_func, "current_label", current_label)
        previous_estimation_context = getattr(
            raw_resource_estimation_func,
            "estimation_context",
            None,
        )
        estimation_context = getattr(
            normalized_resource_estimation,
            "estimation_context",
            None,
        )
        if estimation_context is not None:
            setattr(
                raw_resource_estimation_func,
                "estimation_context",
                estimation_context,
            )
        try:
            resource_avg = raw_resource_estimation_func(sql_set, params)
        finally:
            if previous_estimation_context is None:
                try:
                    delattr(raw_resource_estimation_func, "estimation_context")
                except AttributeError:
                    pass
            else:
                setattr(
                    raw_resource_estimation_func,
                    "estimation_context",
                    previous_estimation_context,
                )
        resource_stats = getattr(raw_resource_estimation_func, "last_stats", {}) or {}


        normalized_raw = _normalize_estimated_resource(resource_avg, resource_stats)
        correction_applied = _should_apply_baseline_correction(current_label, params)
        normalized = (
            _apply_baseline_correction_to_normalized(normalized_raw)
            if correction_applied
            else dict(normalized_raw)
        )


        cap = capability
        summary_lines = []
        summary_lines.append("=" * 70)
        summary_lines.append("  Resource Monitor Summary")
        summary_lines.append("=" * 70)
        summary_lines.append(f"  {'Resource':<12} {'Value':>10} {'Capability':>12} {'Util%':>8} {'Status'}")
        summary_lines.append(f"  {'-'*12} {'-'*10} {'-'*12} {'-'*8} {'-'*10}")
        utilization_map = {}
        resource_rows = [
            ("cpu", "CPU", "cores"),
            ("memory", "Memory", "GB"),
            ("io", "IO", "MB/s"),
        ]
        if "io" not in cap and ("io_read" in cap or "io_write" in cap):
            resource_rows = [
                ("cpu", "CPU", "cores"),
                ("memory", "Memory", "GB"),
                ("io_read", "IO Read", "MB/s"),
                ("io_write", "IO Write", "MB/s"),
            ]
        for key, label, unit in resource_rows:
            val = normalized.get(key, 0.0)
            cap_val = cap.get(key, 0.0)
            util = (val / cap_val * 100) if cap_val > 0 else 0.0
            utilization_map[key] = util
            status = "OVERLOAD" if util > 100 else ("HIGH" if util > 80 else "OK")
            summary_lines.append(f"  {label:<12} {val:>10.2f} {cap_val:>10.2f}   {util:>6.1f}%  {status}")
        mem_source = ((resource_stats.get("memory_source", {}) or {}).get("value"))
        mem_pid_count = ((resource_stats.get("memory_pg_pid_count", {}) or {}).get("value"))

        summary_lines.append(f"\n  {'Resource':<12} {'Min':>10} {'Avg':>10} {'P99':>10} {'Max':>10}")
        summary_lines.append(f"  {'-'*12} {'-'*10} {'-'*10} {'-'*10} {'-'*10}")
        estimator_units = str(mem_source or "").strip().lower() == "plan-estimator"
        detail_scale = {
            "cpu": 1.0,
            "memory": 1.0 if estimator_units else float(1024 ** 3),
            "io": 1.0 if estimator_units else float(1024 ** 2),
            "io_read": 1.0 if estimator_units else float(1024 ** 2),
            "io_write": 1.0 if estimator_units else float(1024 ** 2),
        }
        for key, label in [
            ("cpu", "CPU"), ("memory", "Memory"),
            ("io", "IO"), ("io_read", "IO Read"), ("io_write", "IO Write"),
        ]:
            s = resource_stats.get(key)
            if s and isinstance(s, dict):
                scale = detail_scale.get(key, 1.0) or 1.0
                summary_lines.append(
                    f"  {label:<12} "
                    f"{(float(s.get('min', 0) or 0.0) / scale):>10.2f} "
                    f"{(float(s.get('avg', 0) or 0.0) / scale):>10.2f} "
                    f"{(float(s.get('p99', 0) or 0.0) / scale):>10.2f} "
                    f"{(float(s.get('max', 0) or 0.0) / scale):>10.2f}"
                )

        if mem_source:
            summary_lines.append("")
            summary_lines.append(f"  Memory Source        {mem_source}")
            if mem_pid_count not in (None, ""):
                summary_lines.append(f"  Memory PG PID Count  {int(float(mem_pid_count))}")

        # Print benchmark results
        benchmark = resource_stats.get("benchmark") or {}
        if benchmark:
            summary_lines.append("")
            summary_lines.append("  Benchmark Results (HyBench)")
            summary_lines.append(f"  {'-'*40}")
            for bk, bv in benchmark.items():
                summary_lines.append(f"  {bk:<20} {bv}")

        summary_lines.append("=" * 70)

        summary_text = "\n".join(summary_lines)
        print("\n" + summary_text + "\n")

        # Log to file
        main_logger.log_struct({
            "event": "resource_monitor_summary",
            "normalized_raw": normalized_raw,
            "normalized": normalized,
            "utilization_pct": utilization_map,
            "memory_source": mem_source,
            "memory_pg_pid_count": mem_pid_count,
            "benchmark": benchmark,
            "baseline_correction": {
                "enabled": baseline_correction_state.get("enabled"),
                "completed": baseline_correction_state.get("completed"),
                "success": baseline_correction_state.get("success"),
                "applied": correction_applied,
                "last_max_log10_error": baseline_correction_state.get("last_max_log10_error"),
                "scales": baseline_correction_state.get("scales"),
                "exempt_resources": baseline_correction_state.get("exempt_resources"),
            },
        })


        normalized_resource_estimation.last_stats = resource_stats
        normalized_resource_estimation.last_window = getattr(
            raw_resource_estimation_func, "last_window", None
        )
        normalized_metadata = copy.deepcopy(
            getattr(raw_resource_estimation_func, "last_metadata", None) or {}
        )
        if isinstance(normalized_metadata, dict):
            normalized_metadata["baseline_correction"] = {
                "enabled": baseline_correction_state.get("enabled"),
                "completed": baseline_correction_state.get("completed"),
                "success": baseline_correction_state.get("success"),
                "applied": correction_applied,
                "last_max_log10_error": baseline_correction_state.get("last_max_log10_error"),
                "scales": copy.deepcopy(baseline_correction_state.get("scales") or {}),
                "exempt_resources": copy.deepcopy(
                    baseline_correction_state.get("exempt_resources") or []
                ),
            }
        normalized_resource_estimation.last_metadata = normalized_metadata

        return normalized


    resource_estimation_func = normalized_resource_estimation

    # ============================================================================

    # ============================================================================
    optimizer_cfg = cfg.get("optimizer") or {}
